void DvTrim(char *s) {                       // leading / trailing blanks off (item arguments)
    size_t len = strlen(s);
    while (len && (s[len - 1] == ' ' || s[len - 1] == '\t')) s[--len] = 0;
    size_t lead = strspn(s, " \t");
    if (lead) memmove(s, s + lead, len - lead + 1);
}

// load: the byte checks of precheck_014.txt (projection = the 0.13 checks, g_lblProjOk)
bool DvChecks(const DvCheck *c, size_t count, DWORD *failedAt) {
    for (size_t i = 0; i < count; ++i)
        if (!HexBytesAt(c[i].at, c[i].hex)) { *failedAt = c[i].at; return false; }
    return true;
}
char g_dvTrgWhyBuf[96], g_dvPortalWhyBuf[96], g_dvCpWhyBuf[96];
bool DvLayerOk(int layer, const char **why);  // below
bool DvViewSkips(int layer);                 // 0.16, below
void DebugViewCheck() {
    DWORD at = 0;
    bool base = g_lblProjOk && g_instOk && g_playerOk && g_mainStateOk;
    const char *baseWhy = !g_lblProjOk ? "projection (0.13 checks) failed" : !g_instOk ? "instance list (0.3 check) failed"
                        : !g_playerOk ? "player pointer check failed" : "main state check failed";
    g_dvTrgOk = base && DvChecks(kDvTrigChecks, sizeof(kDvTrigChecks) / sizeof(kDvTrigChecks[0]), &at);
    if (!base) Out(g_dvTrgWhyBuf, sizeof(g_dvTrgWhyBuf), "%s", baseWhy);
    else Out(g_dvTrgWhyBuf, sizeof(g_dvTrgWhyBuf), "trigger code differs at 0x%08lx", at);
    g_dvTrgWhy = g_dvTrgOk ? "ok" : g_dvTrgWhyBuf;
    g_dvPortalOk = base && g_unitOk && DvChecks(kDvPortalChecks, sizeof(kDvPortalChecks) / sizeof(kDvPortalChecks[0]), &at);
    if (!base) Out(g_dvPortalWhyBuf, sizeof(g_dvPortalWhyBuf), "%s", baseWhy);
    else if (!g_unitOk) Out(g_dvPortalWhyBuf, sizeof(g_dvPortalWhyBuf), "stream unit table check failed");
    else Out(g_dvPortalWhyBuf, sizeof(g_dvPortalWhyBuf), "stream portal code differs at 0x%08lx", at);
    g_dvPortalWhy = g_dvPortalOk ? "ok" : g_dvPortalWhyBuf;
    g_dvCpOk = base && DvChecks(kDvCpChecks, sizeof(kDvCpChecks) / sizeof(kDvCpChecks[0]), &at);
    if (!base) Out(g_dvCpWhyBuf, sizeof(g_dvCpWhyBuf), "%s", baseWhy);
    else Out(g_dvCpWhyBuf, sizeof(g_dvCpWhyBuf), "checkpoint game data code differs at 0x%08lx", at);
    g_dvCpWhy = g_dvCpOk ? "ok" : g_dvCpWhyBuf;
    g_dvBaseOk = base;
    g_dvBaseWhy = base ? "ok" : baseWhy;
    memset(g_dvNameKind, 0, sizeof(g_dvNameKind));
    memset(g_dvNameHit, 0, sizeof(g_dvNameHit));
    int on = 0;
    if (g_debugEnabled) {
        for (int i = 0; i < kDvCount; ++i) {
            bool want = g_dvAtStart[i] || (g_dvViewAtStart && !DvViewSkips(i)) || (i < kDvKinds && g_dvTrgAtStart);
            const char *why = "";
            if (want && DvLayerOk(i, &why)) { InterlockedExchange(&g_dvOn[i], 1); ++on; }
        }
        if ((g_dvMarkupAtStart || g_dvViewAtStart) && g_drawOk) InterlockedExchange(&g_drawMarkup, 1);
    }
    Log(g_dvTrgOk && g_dvPortalOk && g_dvCpOk ? 1 : 0, "0.14 debug view: triggers %s, portals %s, checkpoints %s, object "
        "names %s; [Debug] View %d, Triggers %d, %d layer(s) on now, Markup %d, ViewNav '%s', TriggerMax %d, TriggerRadius "
        "%.0f, TriggerLabelMax %d, NameMatch '%s', NameRadius %.0f, NameMax %d, NameScale %.2f, NameColour %06lX, NameIds "
        "%d, Persist %d", g_dvTrgWhy, g_dvPortalWhy, g_dvCpWhy, g_dvBaseWhy, g_dvViewAtStart, g_dvTrgAtStart, on,
        g_drawMarkup ? 1 : 0, g_dvViewNav, g_dvTrgMax, g_dvRadius, g_dvLabelMax, g_dvNameMatch, g_dvNameRadius,
        g_dvNameMax, g_dvNameScale, g_dvNameRgb, g_dvNameIds, g_dvPersist);
}

// the check a layer needs (true = usable)
bool RcLayerOk(const char **why);            // 0.15, below: the collision overlay checks (precheck_015.txt 4 .. 6)
bool M20LayerOk(int layer, const char **why);   // 0.20, below: collectibles / enemies
bool DvLayerOk(int layer, const char **why) {
    if (layer == kDvSlide || layer == kDvEnemyColl) return RcLayerOk(why);
    if (layer == kDvCollect || layer == kDvEnemies) return M20LayerOk(layer, why);
    bool ok = layer < kDvKinds || layer == kDvTrgLabels ? g_dvTrgOk : layer == kDvPortals ? g_dvPortalOk
            : layer == kDvCheckpoints ? g_dvCpOk : layer == kDvNames ? g_dvBaseOk : true;
    *why = layer < kDvKinds || layer == kDvTrgLabels ? g_dvTrgWhy : layer == kDvPortals ? g_dvPortalWhy
         : layer == kDvCheckpoints ? g_dvCpWhy : layer == kDvNames ? g_dvBaseWhy : "ok";
    return ok;
}
int DvFind(const char *text) {
    if (!text) return -1;
    while (*text == ' ') ++text;
    size_t len = 0;
    while (text[len] && text[len] != ' ') ++len;
    for (int i = 0; i < kDvCount; ++i)
        if (strlen(kDvLayers[i].name) == len && !_strnicmp(kDvLayers[i].name, text, len)) return i;
    return -1;
}
bool DvAnyOn() {
    for (int i = 0; i < kDvCount; ++i)
        if (g_dvOn[i]) return true;
    return false;
}
// 0.16: [Debug] ViewSkip names this layer (dbg.view / [Debug] View leave it off)
bool DvViewSkips(int layer) {
    char list[sizeof(g_dvViewSkip)];
    strncpy_s(list, sizeof(list), g_dvViewSkip, _TRUNCATE);
    char *context = nullptr;
    for (char *word = strtok_s(list, ", ", &context); word; word = strtok_s(nullptr, ", ", &context))
        if (!_stricmp(word, kDvLayers[layer].name)) return true;
    return false;
}
bool DvAnyTrigger() {
    for (int i = 0; i < kDvKinds; ++i)
        if (g_dvOn[i]) return true;
    return false;
}

// [Debug] Persist=1: a switch is written back to TruMenu.ini at once (read at the next start)
void DvPersistKey(const char *key, bool on) {
    if (g_dvPersist && g_iniPath[0]) WritePrivateProfileStringA("Debug", key, on ? "1" : "0", g_iniPath);
}
void DvPersistNav() {
    if (!g_dvPersist || !g_iniPath[0]) return;
    char list[200] = "";
    size_t used = 0;
    for (int i = 0; i < kNavCount; ++i) {
        if (!NavByteOn(i)) continue;
        int w = _snprintf_s(list + used, sizeof(list) - used, _TRUNCATE, "%s%s", used ? "," : "", kNavSwitches[i].name);
        if (w > 0) used += static_cast<size_t>(w);
    }
    WritePrivateProfileStringA("Debug", "NavDraw", list, g_iniPath);
}

// one layer on / off (check passed); src for the log line
bool DvSet(int layer, bool on, const char *src, char *o, size_t n) {
    const char *why = "";
    if (!g_debugEnabled) { Out(o, n, "debug drawing off ([Debug] Enabled=0)"); return false; }
    if (!DvLayerOk(layer, &why)) {
        Out(o, n, "disabled: pre-check failed (%s)", why);
        Log(1, "dbg.show %s %d refused - %s (src=%s)", kDvLayers[layer].name, on ? 1 : 0, o, src);
        return false;
    }
    InterlockedExchange(&g_dvOn[layer], on ? 1 : 0);
    InterlockedExchange(&g_dvLogPending, 1);
    DvPersistKey(kDvLayers[layer].key, on);
    Log(1, "dbg.show %s %d (src=%s)", kDvLayers[layer].name, on ? 1 : 0, src);
    Out(o, n, "dbg.show %s %d", kDvLayers[layer].name, on ? 1 : 0);
    return true;
}

// object id -> kind of a trigger instance (kDvDeath .. kDvSound), -1 no keyword, -2 no name; cached per object id
int DvNameKind(DWORD inst, char *name, size_t size) {
    DWORD object = 0, oid = 0;
    name[0] = 0;
    if (!ReadDword(inst + 0x10, &object) || !object || !ReadDword(object + 0x14, &oid)) return -2;
    int id = static_cast<int>(oid & 0xffff);
    if (!ObjectName(id, name, size)) return -2;
    if (id > 0 && id < 4096 && g_dvNameKind[id]) {
        int c = g_dvNameKind[id];
        return c >= 100 ? -1 : c - 1;
    }
    char low[64];
    strncpy_s(low, sizeof(low), name, _TRUNCATE);
    _strlwr_s(low, sizeof(low));
    int kind = -1;
    for (const DvWord &w : kDvWords)
        if (strstr(low, w.part)) { kind = w.kind; break; }
    if (id > 0 && id < 4096) g_dvNameKind[id] = static_cast<signed char>(kind < 0 ? 100 : kind + 1);
    return kind;
}

// projection with a near plane: camera space (x', y' scaled like the game's text space, z' = depth in world units)
struct DvCam { View v; float ux, uy; };     // ux / uy = 1 / length of the scaled x / y columns (world distances)
void DvToCam(const DvCam &c, const float *p, float *o) {
    const float *m = c.v.m;
    o[0] = m[0] * p[0] + m[4] * p[1] + m[8] * p[2] + m[12];
    o[1] = m[1] * p[0] + m[5] * p[1] + m[9] * p[2] + m[13];
    o[2] = m[2] * p[0] + m[6] * p[1] + m[10] * p[2] + m[14];
}
const float kDvNear = 16.5f;                 // the game draws when 16.0 < z' ([0x8451e4])
bool DvCamToScreen(const DvCam &c, const float *q, ImVec2 *out) {
    if (!(q[2] >= kDvNear)) return false;
    float x = static_cast<float>(q[0] / q[2] * c.v.f + c.v.cx) * c.v.sx;
    float y = static_cast<float>(q[1] / q[2] * c.v.f + c.v.cy) * c.v.sy;
    if (!(x > -100000.0f && x < 100000.0f && y > -100000.0f && y < 100000.0f)) return false;
    out->x = x;
    out->y = y;
    return true;
}
// ---- 0.16 readability (owner feedback 2026-11-06 from the first live run in the Croft Manor prologue) ----
// Workspace docs\Befund-TruMenu-Lesbarkeit-0611.md; the new byte checks are pinned in work\asi\menu016\precheck_016.txt.
// Style: every 0.14 / 0.15 overlay colour goes through DvTint - [Debug] LineAlpha (global opacity), LineBright
//   (brightness), Fade / FadeStart / FadeEnd / FadeMin (far objects fainter, distance from the camera), Enclosing (a box
//   around the camera, or a big one around Lara: dim + dashed, or hidden), Fill / FillAlpha (faint faces of boxes and
//   trigger planes).
// Labels: every trigger / portal / checkpoint label is a candidate (DvTagAdd), drawn at the end of the frame nearest
//   first, at most [Debug] ViewLabelMax, each nudged up / down or skipped when its box overlaps one already drawn (or
//   the legend); coincident triggers (same kind, centres within 25 units) share one label "TV x3 (4535..4537)", the
//   two directions of one loading area one label "a <-> b"; LabelShort = short text (TV 4463 / TP 4129 / FIRE 4492,
//   portal "-> main_bedroom") except the nearest label and the one nearest to the screen centre (full text).
// Lara in: the point the engine tests (player +0x20 + (0, 0, 200)) against every listed trigger with the engine's math
//   (box |(p - c) . row_i| <= h_i = 0x46b730, sphere |p - c|^2 < r^2; a plane is a crossing test in the engine, so
//   "near" = within 50 units of its quad); drawn bold with a pulsing white outline, named in the legend. The engine
//   keeps no inside flag of its own: 0x5cd1b0 tests the old and the new position every frame and returns 0 out,
//   1 inside, 2 enter, 3 exit (0x5cd4ef / 0x5cd507); the loop sends enter / exit (0x5cd661 / 0x5cd68b / 0x5cd6b6) only
//   for entries with +0x24 bit 31 (enabled) and bit 30 (tested against the player).
// Depth ([Debug] Depth 1 / 2, below in the 0.16 depth section): lines / faces go into a world-space buffer instead of
//   ImGui and are drawn inside the next frame right after PCScene::Draw returned, with the scene's depth buffer.
int g_dvAlpha = 60, g_dvBright = 100, g_dvFade = 1, g_dvFadeMin = 20;   // [Debug] LineAlpha / LineBright / Fade / FadeMin
float g_dvFadeStart = 2000.0f, g_dvFadeEnd = 10000.0f;                  // [Debug] FadeStart / FadeEnd
int g_dvFill = 0, g_dvFillAlpha = 10;                                   // [Debug] Fill / FillAlpha
int g_dvShort = 1, g_dvLaraIn = 1, g_dvTagMax = 10;                      // [Debug] LabelShort / LaraIn / ViewLabelMax
int g_dvLegendLaraIn = 0;                                               // 0.18 [Debug] LegendLaraIn
int g_dvEncl = 1, g_dvMarkerMax = 8;                                    // [Debug] Enclosing (0 / 1 / 2) / MarkerMax (%)
float g_dvEnclSize = 1500.0f;                                           // [Debug] EnclosingSize
volatile LONG g_dpMode = 2;                  // [Debug] Depth: 0 on top (0.15), 1 hidden behind geometry, 2 hidden dim
                                             // (0.20: 2 by default)
int g_dpDim = 25, g_dpCall = 0;              // [Debug] DepthDim (%) / DepthCall
bool g_dpOk = false, g_dvLaraOk = false;     // precheck_016.txt: depth (scene) / the engine's inside result codes
const char *g_dpWhy = "not checked";
char g_dpWhyBuf[96];
bool g_dvDashed = false;                     // the DvLine calls of one enclosing box draw dashed
float g_dvCamPos[3] = {0, 0, 0};             // camera position (inverse of the 0.14 camera), this frame
bool g_dvCamOk = false;

// distance fade factor (1 = near .. FadeMin / 100 = far)
float DvFadeAt(float dist2) {
    if (!g_dvFade || !(g_dvFadeEnd > g_dvFadeStart)) return 1.0f;
    float d = sqrtf(dist2 > 0.0f ? dist2 : 0.0f), t = (d - g_dvFadeStart) / (g_dvFadeEnd - g_dvFadeStart);
    t = t < 0.0f ? 0.0f : t > 1.0f ? 1.0f : t;
    return 1.0f - t * (1.0f - g_dvFadeMin / 100.0f);
}
ImU32 DvRgba(float r, float g, float b, float a) {
    int ir = static_cast<int>(r), ig = static_cast<int>(g), ib = static_cast<int>(b), ia = static_cast<int>(a);
    ir = ir < 0 ? 0 : ir > 255 ? 255 : ir;
    ig = ig < 0 ? 0 : ig > 255 ? 255 : ig;
    ib = ib < 0 ? 0 : ib > 255 ? 255 : ib;
    ia = ia < 0 ? 0 : ia > 255 ? 255 : ia;
    return IM_COL32(ir, ig, ib, ia);
}
// a layer colour with LineBright, LineAlpha, the distance fade and an extra factor (disabled / enclosing)
ImU32 DvTint(ImU32 colour, float dist2, float extra) {
    const float k = g_dvBright / 100.0f;
    return DvRgba((colour & 0xff) * k, ((colour >> 8) & 0xff) * k, ((colour >> 16) & 0xff) * k,
                  ((colour >> 24) & 0xff) * (g_dvAlpha / 100.0f) * extra * DvFadeAt(dist2));
}
// the face fill colour: FillAlpha with the fade (not LineAlpha)
ImU32 DvFillTint(ImU32 colour, float dist2, float extra) {
    const float k = g_dvBright / 100.0f;
    return DvRgba((colour & 0xff) * k, ((colour >> 8) & 0xff) * k, ((colour >> 16) & 0xff) * k,
                  255.0f * (g_dvFillAlpha / 100.0f) * extra * DvFadeAt(dist2));
}

// the depth sink: one world-space buffer per Present (three, so the scene hook never reads the one being filled)
struct DpLine { float a[3], b[3]; ImU32 colour; float thick; int dashed; };
struct DpTri { float v[3][3]; ImU32 colour; };
const int kDpLineMax = 16384, kDpTriMax = 16384;
struct DpBuf { LONG frame; int lines, tris, dropped; DpLine line[kDpLineMax]; DpTri tri[kDpTriMax]; };
DpBuf g_dpBuf[3];
volatile LONG g_dpPub = -1, g_dpRead = -1;   // published buffer / the one the scene hook reads (-1 none)
DpBuf *g_dpFill = nullptr;                   // Present: the buffer DrawDebugView fills now (nullptr = ImGui path)
LONG g_dpFillIndex = -1;
volatile LONG g_dpFrame = 0;                 // Present counter (RenderModeTick)
void DpPushLine(const float *a, const float *b, ImU32 colour, float thick) {
    DpBuf &d = *g_dpFill;
    if (d.lines >= kDpLineMax) { ++d.dropped; return; }
    DpLine &l = d.line[d.lines++];
    for (int k = 0; k < 3; ++k) { l.a[k] = a[k]; l.b[k] = b[k]; }
    l.colour = colour;
    l.thick = thick;
    l.dashed = g_dvDashed ? 1 : 0;
}
void DpPushTri(const float *a, const float *b, const float *c, ImU32 colour) {
    DpBuf &d = *g_dpFill;
    if (d.tris >= kDpTriMax) { ++d.dropped; return; }
    DpTri &t = d.tri[d.tris++];
    for (int k = 0; k < 3; ++k) { t.v[0][k] = a[k]; t.v[1][k] = b[k]; t.v[2][k] = c[k]; }
    t.colour = colour;
}

// a screen segment clipped to the rectangle [x0, x1] x [y0, y1] (Liang-Barsky); t0 / t1 = the kept part of a .. b
bool DvClip2D(const ImVec2 &a, const ImVec2 &b, float x0, float y0, float x1, float y1, float *t0, float *t1) {
    float dx = b.x - a.x, dy = b.y - a.y, lo = 0.0f, hi = 1.0f;
    const float p[4] = {-dx, dx, -dy, dy}, q[4] = {a.x - x0, x1 - a.x, a.y - y0, y1 - a.y};
    for (int i = 0; i < 4; ++i) {
        if (p[i] == 0.0f) {
            if (q[i] < 0.0f) return false;
            continue;
        }
        float r = q[i] / p[i];
        if (p[i] < 0.0f) { if (r > hi) return false; if (r > lo) lo = r; }
        else { if (r < lo) return false; if (r < hi) hi = r; }
    }
    *t0 = lo;
    *t1 = hi;
    return true;
}
const float kDvDashOn = 9.0f, kDvDashOff = 7.0f;   // px
// a dashed screen line (enclosing boxes), clipped to the display first
void DvDash(ImDrawList *dl, ImVec2 a, ImVec2 b, ImU32 colour, float thick) {
    const ImVec2 ds = ImGui::GetIO().DisplaySize;
    float t0 = 0.0f, t1 = 1.0f;
    if (!DvClip2D(a, b, -20.0f, -20.0f, ds.x + 20.0f, ds.y + 20.0f, &t0, &t1)) return;
    float dx = b.x - a.x, dy = b.y - a.y, len = sqrtf(dx * dx + dy * dy) * (t1 - t0);
    if (len < 1.0f) return;
    ImVec2 s(a.x + dx * t0, a.y + dy * t0);
    float ux = dx * (t1 - t0) / len, uy = dy * (t1 - t0) / len;
    for (float at = 0.0f; at < len; at += kDvDashOn + kDvDashOff) {
        float e = at + kDvDashOn < len ? at + kDvDashOn : len;
        dl->AddLine(ImVec2(s.x + ux * at, s.y + uy * at), ImVec2(s.x + ux * e, s.y + uy * e), colour, thick);
    }
}

// a world line, clipped at the near plane; false = nothing of it in front of the camera. 0.16: into the depth buffer
// when the depth path fills one this frame, dashed while g_dvDashed
bool DvLine(ImDrawList *dl, const DvCam &c, const float *a, const float *b, ImU32 colour, float thick) {
    float ca[3], cb[3];
    DvToCam(c, a, ca);
    DvToCam(c, b, cb);
    if (ca[2] < kDvNear && cb[2] < kDvNear) return false;
    if (g_dpFill) {
        DpPushLine(a, b, colour, thick);
        return true;
    }
    if (ca[2] < kDvNear || cb[2] < kDvNear) {
        float *near_ = ca[2] < kDvNear ? ca : cb;
        const float *far_ = ca[2] < kDvNear ? cb : ca;
        float t = (kDvNear - near_[2]) / (far_[2] - near_[2]);
        for (int k = 0; k < 3; ++k) near_[k] += (far_[k] - near_[k]) * t;
        near_[2] = kDvNear;
    }
    ImVec2 sa, sb;
    if (!DvCamToScreen(c, ca, &sa) || !DvCamToScreen(c, cb, &sb)) return false;
    if (g_dvDashed) DvDash(dl, sa, sb, colour, thick);
    else dl->AddLine(sa, sb, colour, thick);
    return true;
}
// 0.16: a convex world polygon (3 or 4 points), near-plane clipped, filled (face fill; R2 faces)
void DvPoly(ImDrawList *dl, const DvCam &c, const float (*p)[3], int n, ImU32 colour) {
    if (n < 3 || n > 4 || !(colour >> 24)) return;
    if (g_dpFill) {
        float q[3];
        bool any = false;
        for (int i = 0; i < n && !any; ++i) { DvToCam(c, p[i], q); any = q[2] >= kDvNear; }
        for (int i = 1; any && i + 1 < n; ++i) DpPushTri(p[0], p[i], p[i + 1], colour);
        return;
    }
    float q[4][3], poly[5][3];
    for (int a = 0; a < n; ++a) DvToCam(c, p[a], q[a]);
    int m = 0;
    for (int a = 0; a < n; ++a) {                         // Sutherland-Hodgman against z' >= near
        const float *p0 = q[a], *p1 = q[(a + 1) % n];
        bool in0 = p0[2] >= kDvNear, in1 = p1[2] >= kDvNear;
        if (in0) { poly[m][0] = p0[0]; poly[m][1] = p0[1]; poly[m][2] = p0[2]; ++m; }
        if (in0 != in1) {
            float s = (kDvNear - p0[2]) / (p1[2] - p0[2]);
            for (int b = 0; b < 3; ++b) poly[m][b] = p0[b] + (p1[b] - p0[b]) * s;
            poly[m][2] = kDvNear;
            ++m;
        }
    }
    if (m < 3) return;
    ImVec2 pts[5];
    for (int a = 0; a < m; ++a)
        if (!DvCamToScreen(c, poly[a], &pts[a])) return;
    dl->AddConvexPolyFilled(pts, m, colour);
}
bool DvFinite(const float *p, int count) {
    for (int i = 0; i < count; ++i)
        if (!(p[i] > -1.0e7f && p[i] < 1.0e7f)) return false;
    return true;
}
// rows of M = Rz * Ry * Rx (0x49d500) from the Euler angles r (x, y, z), row vectors: world offset = local * M
void DvEulerRows(const float *r, float rows[3][3]) {
    float cx = cosf(r[0]), sx = sinf(r[0]), cy = cosf(r[1]), sy = sinf(r[1]), cz = cosf(r[2]), sz = sinf(r[2]);
    rows[0][0] = cz * cy; rows[0][1] = sz * cx + cz * sy * sx; rows[0][2] = sz * sx - cz * sy * cx;
    rows[1][0] = -sz * cy; rows[1][1] = cz * cx - sz * sy * sx; rows[1][2] = cz * sx + sz * sy * cx;
    rows[2][0] = sy; rows[2][1] = -cy * sx; rows[2][2] = cy * cx;
}
void DvPoint(const float *pos, const float rows[3][3], float a, float b, float c, float *o) {
    for (int k = 0; k < 3; ++k) o[k] = pos[k] + a * rows[0][k] + b * rows[1][k] + c * rows[2][k];
}

struct DvTrig {
    DWORD entry, inst;
    float pos[3], rot[3], ext[3], radius, dist2, extent;
    float rows[3][3];                        // 0.16: M = Rz * Ry * Rx (DvEulerRows), once per frame
    int kind;                                // layer index kDvDeath .. kDvUnknown
    BYTE shape;                              // 1 box, 2 sphere, 0 plane / unknown
    BYTE laraIn;                             // 0.16: 1 the test point is inside, 2 within 50 units of a plane quad
    bool plane, enabled, oneSided;
    bool player, camIn, big;                 // 0.16: +0x24 bit 30, the camera is inside, a big volume
};
DvTrig g_dvTrig[513];                        // 0.16: TriggerMax up to 512 (0.14: 256)
struct DvMark { DWORD inst; float pos[3], dist2; };
DvMark g_dvCp[33];

// distance from the camera (world units) and a cheap "can it be on screen" test with a bounding radius
bool DvVisible(const DvCam &c, const float *p, float extent, float *dist2) {
    float q[3];
    DvToCam(c, p, q);
    float x = q[0] * c.ux, y = q[1] * c.uy;
    *dist2 = x * x + y * y + q[2] * q[2];
    if (q[2] + extent < kDvNear) return false;                // behind the camera
    float z = q[2] > kDvNear ? q[2] : kDvNear;
    // text space half width 256 / half height 224 at focal f: |x'| / z' * f <= 256 (+ the extent)
    if ((fabsf(q[0]) - extent / c.ux) * c.v.f > 320.0f * z) return false;
    if ((fabsf(q[1]) - extent / c.uy) * c.v.f > 290.0f * z) return false;
    return true;
}

// sorted insert (nearest first), at most g_dvTrgMax; returns false when it did not fit
int g_dvTrigCount = 0;
void DvTrigInsert(const DvTrig &t) {
    int at = g_dvTrigCount;
    while (at > 0 && g_dvTrig[at - 1].dist2 > t.dist2) --at;
    if (at >= g_dvTrgMax) return;
    int last = g_dvTrigCount < g_dvTrgMax ? g_dvTrigCount : g_dvTrgMax - 1;
    for (int k = last; k > at; --k) g_dvTrig[k] = g_dvTrig[k - 1];
    g_dvTrig[at] = t;
    if (g_dvTrigCount < g_dvTrgMax) ++g_dvTrigCount;
}

// 0.16: is point p inside trigger t (the engine's math: box 0x46b730 = |(p - c) . row_i| <= h_i, sphere |p - c|^2 <
// r^2 as 0x5cd445 .. 0x5cd4aa); planes: 2 when p is within 50 units of the quad (the engine tests a crossing), else 0
int DvInside(const DvTrig &t, const float *p) {
    float d[3] = {p[0] - t.pos[0], p[1] - t.pos[1], p[2] - t.pos[2]}, l[3];
    for (int i = 0; i < 3; ++i) l[i] = d[0] * t.rows[i][0] + d[1] * t.rows[i][1] + d[2] * t.rows[i][2];
    if (t.plane) return fabsf(l[0]) <= t.ext[0] && fabsf(l[2]) <= t.ext[2] && fabsf(l[1]) <= 50.0f ? 2 : 0;
    if (t.shape == 1) return fabsf(l[0]) <= t.ext[0] && fabsf(l[1]) <= t.ext[1] && fabsf(l[2]) <= t.ext[2] ? 1 : 0;
    if (t.shape == 2) return d[0] * d[0] + d[1] * d[1] + d[2] * d[2] < t.radius * t.radius ? 1 : 0;
    return 0;
}
// 0.16 "Lara in": the triggers the test point is in this frame (every listed one, also of a kind switched off)
struct DvIn { DWORD inst; LONG intro; int kind; BYTE how; bool enabled, player; };
DvIn g_dvIn[16];
int g_dvInN = 0, g_dvInMore = 0;
float g_dvTestPt[3];
bool g_dvTestOk = false;
int g_dvCapped = 0, g_dvEnclN = 0;           // 0.16: last frame - capped at TriggerMax, enclosing boxes dimmed / hidden

// one entry of a trigger list (planes or volumes): instance, position, rotation, data (extent, radius, shape, side),
// kind, rows, flags; false = no usable entry. 0.18: shared by DvCollect and the overlay's "Lara in" scan
bool DvTrigRead(bool planes, DWORD i, DvTrig *out, bool *known, bool *haveData) {
    DvTrig t = {};
    DWORD flags = 0, intro = 0, data = 0;
    if (!ReadDword((planes ? kDvPlanes : kDvVols) + i * 4, &t.entry) || !t.entry) return false;
    if (!ReadDword(t.entry + 0x20, &t.inst) || !t.inst || !ReadDword(t.entry + 0x24, &flags)) return false;
    if (!ReadFloats(t.inst + kInstancePosition, t.pos, 3) || !ReadFloats(t.inst + 0x30, t.rot, 3) ||
        !DvFinite(t.pos, 3) || !DvFinite(t.rot, 3))
        return false;
    t.plane = planes;
    t.enabled = (flags & 0x80000000u) != 0;
    *haveData = ReadDword(t.inst + 0x100, &intro) && intro && ReadDword(intro + 0x78, &data) && data &&
                ReadFloats(data + 0x34, t.ext, 3) && ReadFloats(data + 0x40, &t.radius, 1) &&
                DvFinite(t.ext, 3) && DvFinite(&t.radius, 1) && ReadByte(data + 0x30, &t.shape);
    BYTE side = 1;
    if (*haveData && planes) ReadByte(data + 0x44, &side);
    t.oneSided = planes && side == 0;
    char name[64];
    int kind = DvNameKind(t.inst, name, sizeof(name));
    *known = *haveData && (planes || t.shape == 1 || t.shape == 2) && kind != -2;
    t.kind = !*known ? kDvUnknown : kind >= 0 ? kind : planes ? kDvPlane : kDvVolume;
    DvEulerRows(t.rot, t.rows);
    t.player = (flags & 0x40000000u) != 0;
    *out = t;
    return true;
}

// collect one list (planes or volumes) into g_dvTrig; counters for the state line
struct DvCount { int listed, behind, far_, noData, disabled; };
void DvCollect(const DvCam &c, bool planes, DvCount *k) {
    DWORD count = 0;
    if (!ReadDword(planes ? kDvPlaneCount : kDvVolCount, &count) || count > kDvListMax) return;
    for (DWORD i = 0; i < count; ++i) {
        DvTrig t;
        bool known = false, haveData = false;
        if (!DvTrigRead(planes, i, &t, &known, &haveData)) continue;
        if (!haveData) ++k->noData;
        ++g_dvListed[t.kind];
        // 0.16: rows once (DvTrigRead); Lara in (every listed trigger with data, also of a kind switched off); camera
        // inside / big
        if (known && g_dvTestOk && g_dvLaraOk) {
            t.laraIn = static_cast<BYTE>(DvInside(t, g_dvTestPt));
            if (t.laraIn) {
                if (g_dvInN < 16) {
                    DvIn &in = g_dvIn[g_dvInN++];
                    in.inst = t.inst;
                    in.intro = 0;
                    DWORD uid = 0;
                    if (ReadDword(t.inst + 0x58, &uid)) in.intro = static_cast<LONG>(uid);
                    in.kind = t.kind;
                    in.how = t.laraIn;
                    in.enabled = t.enabled;
                    in.player = t.player;
                } else {
                    ++g_dvInMore;
                }
            }
        }
        if (known && !planes) {
            t.camIn = g_dvCamOk && DvInside(t, g_dvCamPos) == 1;
            float big = t.shape == 2 ? fabsf(t.radius) : t.ext[0] > t.ext[1] ? (t.ext[0] > t.ext[2] ? t.ext[0] : t.ext[2])
                                                                               : (t.ext[1] > t.ext[2] ? t.ext[1] : t.ext[2]);
            t.big = big >= g_dvEnclSize;
        }
        if (!g_dvOn[t.kind]) continue;
        ++k->listed;
        if (!t.enabled) ++k->disabled;
        t.extent = !known ? 60.0f : planes ? sqrtf(t.ext[0] * t.ext[0] + t.ext[2] * t.ext[2])
                 : t.shape == 2 ? fabsf(t.radius) : sqrtf(t.ext[0] * t.ext[0] + t.ext[1] * t.ext[1] + t.ext[2] * t.ext[2]);
        if (!DvVisible(c, t.pos, t.extent, &t.dist2)) { ++k->behind; continue; }
        if (t.dist2 > g_dvRadius * g_dvRadius) { ++k->far_; continue; }
        DvTrigInsert(t);
    }
}

// ---- 0.18 "Lara in" in the position overlay (Lukas, live 2026-11-06: "Lara in" belongs top left under the coordinates,
// not in the legend; it must work without a trigger layer) ----
// Render thread, at most every 100 ms while the overlay draws: both trigger lists with DvTrigRead and the 0.16 test
// (DvInside: point = player +0x20 + (0, 0, 200), box / sphere inside, plane within 50 units of the quad), every kind,
// whether a layer is drawn or not. Needs the 0.14 trigger checks and the 0.16 result-code checks (g_dvTrgOk, g_dvLaraOk)
// - the same reads as the debug view; nothing is written. g_ovIn: in list order (planes first, then volumes).
DvIn g_ovIn[8];
int g_ovInN = 0, g_ovInMore = 0;
DWORD g_ovInTick = 0;
const char *g_ovInWhy = "not scanned yet";
void OvLaraInScan() {
    const DWORD now = GetTickCount();
    if (g_ovInTick && now - g_ovInTick < 100) return;
    g_ovInTick = now ? now : 1;
    g_ovInN = g_ovInMore = 0;
    if (!g_dvTrgOk) { g_ovInWhy = g_dvTrgWhy; return; }
    if (!g_dvLaraOk) { g_ovInWhy = "Lara-in result code checks failed"; return; }
    DWORD player = 0;
    float p[3];
    if (!ReadDword(kPlayerPtr, &player) || !player || !ReadFloats(player + kInstancePosition, p, 3) || !DvFinite(p, 3)) {
        g_ovInWhy = "no player";
        return;
    }
    p[2] += kDvTestLift;
    g_ovInWhy = "";
    for (int list = 0; list < 2; ++list) {
        const bool planes = list == 0;
        DWORD count = 0;
        if (!ReadDword(planes ? kDvPlaneCount : kDvVolCount, &count) || count > kDvListMax) continue;
        for (DWORD i = 0; i < count; ++i) {
            DvTrig t;
            bool known = false, haveData = false;
            if (!DvTrigRead(planes, i, &t, &known, &haveData) || !known) continue;
            const int how = DvInside(t, p);
            if (!how) continue;
            if (g_ovInN >= static_cast<int>(sizeof(g_ovIn) / sizeof(g_ovIn[0]))) { ++g_ovInMore; continue; }
            DvIn &in = g_ovIn[g_ovInN++];
            DWORD uid = 0;
            in.inst = t.inst;
            in.intro = ReadDword(t.inst + 0x58, &uid) ? static_cast<LONG>(uid) : 0;
            in.kind = t.kind;
            in.how = static_cast<BYTE>(how);
            in.enabled = t.enabled;
            in.player = t.player;
        }
    }
}

// one trigger: box 12 lines, sphere 3 circles, plane quad + diagonals (+ normal arrow when one-sided), unknown a cross
// 0.16: colour / thickness / face fill come from the caller (DvTint, Lara in, enclosing); fill 0 = no faces; the label
// anchor is the top centre (box: +h along row 2, plane: the upper edge's centre, sphere: the top)
void DvDrawTrig(ImDrawList *dl, const DvCam &c, const DvTrig &t, ImU32 colour, float thick, ImU32 fill, ImVec2 *labelAt,
                bool *labelSeen) {
    const float (*rows)[3] = t.rows;
    float top[3] = {t.pos[0], t.pos[1], t.pos[2]};
    if (t.kind == kDvUnknown && !(t.plane || t.shape == 1 || t.shape == 2)) {
        for (int a = 0; a < 3; ++a) {
            float p0[3] = {t.pos[0], t.pos[1], t.pos[2]}, p1[3] = {t.pos[0], t.pos[1], t.pos[2]};
            p0[a] -= 60.0f;
            p1[a] += 60.0f;
            DvLine(dl, c, p0, p1, colour, thick);
        }
    } else if (t.plane) {
        float q[4][3];
        const float s[4][2] = {{1, -1}, {1, 1}, {-1, 1}, {-1, -1}};
        for (int i = 0; i < 4; ++i) DvPoint(t.pos, rows, s[i][0] * t.ext[0], 0.0f, s[i][1] * t.ext[2], q[i]);
        if (fill) DvPoly(dl, c, q, 4, fill);  // 0.16 face fill
        for (int i = 0; i < 4; ++i) DvLine(dl, c, q[i], q[(i + 1) & 3], colour, thick);
        DvLine(dl, c, q[0], q[2], colour, 1.0f);
        DvLine(dl, c, q[1], q[3], colour, 1.0f);
        if (t.oneSided) {
            float len = t.ext[0] < t.ext[2] ? t.ext[0] : t.ext[2];
            len = len < 50.0f ? 50.0f : len > 300.0f ? 300.0f : len;
            float tip[3];
            DvPoint(t.pos, rows, 0.0f, len, 0.0f, tip);
            DvLine(dl, c, t.pos, tip, colour, thick);
        }
        DvPoint(t.pos, rows, 0.0f, 0.0f, t.ext[2], top);   // 0.16: the upper edge's centre (0.14: the centre)
    } else if (t.shape == 1) {
        float q[8][3];
        for (int i = 0; i < 8; ++i)
            DvPoint(t.pos, rows, (i & 1 ? 1.0f : -1.0f) * t.ext[0], (i & 2 ? 1.0f : -1.0f) * t.ext[1],
                    (i & 4 ? 1.0f : -1.0f) * t.ext[2], q[i]);
        if (fill) {                           // 0.16 face fill: the 6 faces (corner index bits x 1, y 2, z 4)
            static const BYTE kFaces[6][4] = {{0, 2, 6, 4}, {1, 3, 7, 5}, {0, 1, 5, 4}, {2, 3, 7, 6}, {0, 1, 3, 2},
                                              {4, 5, 7, 6}};
            for (const auto &f : kFaces) {
                const float face[4][3] = {{q[f[0]][0], q[f[0]][1], q[f[0]][2]}, {q[f[1]][0], q[f[1]][1], q[f[1]][2]},
                                          {q[f[2]][0], q[f[2]][1], q[f[2]][2]}, {q[f[3]][0], q[f[3]][1], q[f[3]][2]}};
                DvPoly(dl, c, face, 4, fill);
            }
        }
        static const BYTE kEdges[12][2] = {{0, 1}, {2, 3}, {4, 5}, {6, 7}, {0, 2}, {1, 3}, {4, 6}, {5, 7},
                                           {0, 4}, {1, 5}, {2, 6}, {3, 7}};
        for (const auto &e : kEdges) DvLine(dl, c, q[e[0]], q[e[1]], colour, thick);
        DvPoint(t.pos, rows, 0.0f, 0.0f, t.ext[2], top);
    } else {                                  // sphere: world-axis great circles, 24 segments each
        const float r = fabsf(t.radius);
        for (int plane = 0; plane < 3; ++plane) {
            int a = plane == 2 ? 1 : 0, b = plane == 0 ? 1 : 2;
            float prev[3] = {t.pos[0], t.pos[1], t.pos[2]};
            prev[a] += r;
            for (int s = 1; s <= 24; ++s) {
                float ang = s * (2.0f * 3.14159265f / 24.0f), p[3] = {t.pos[0], t.pos[1], t.pos[2]};
                p[a] += r * cosf(ang);
                p[b] += r * sinf(ang);
                DvLine(dl, c, prev, p, colour, thick);
                prev[0] = p[0]; prev[1] = p[1]; prev[2] = p[2];
            }
        }
        top[2] += r;
    }
    float q[3];
    DvToCam(c, top, q);
    *labelSeen = DvCamToScreen(c, q, labelAt);
}

// 0.16 labels ("tags"): candidates of the frame, drawn nearest first with overlap avoidance (DvTagsDraw)
struct DvTag {
    ImVec2 at;                               // anchor on screen
    float dist2, centre[3];
    ImU32 colour;
    int kind;                                // trigger kind (merge key), kDvPortals, or -1 = never merged
    int count;                               // merged coincident triggers
    LONG idMin, idMax;                       // intro ids (triggers), -1 = text only
    char full[96], brief[48], sufFull[24], sufBrief[16];
    char unit[40];                           // owner unit when it is not Lara's ("" = Lara's / unknown)
};
// 0.16 (live finding 2026-11-06: a fire volume of a neighbour unit looked near, was ~6100 units away): every label
// shows the distance to Lara (+0x20) and the height difference in game units, and the owner unit of the instance
// when it is not Lara's unit - owner = the loaded unit whose intro array (Level +0x74 -> unit DTP: +0xc count, +0x10
// Intro* of 0x90 bytes, as the intro loader 0x5d1dda .. 0x5d1e39 walks it) holds the instance's intro (+0x100).
// Live coordinates of every unit are in Lara's unit frame (data - origin Level +0x80 of Lara's unit), so the distance
// of two live positions is right across units.
size_t DvCommonPrefix(const char *a, const char *b);   // below
struct DvUnitRange { DWORD lo, hi; char name[40]; };
DvUnitRange g_dvUnits[16];
int g_dvUnitN = 0;
char g_dvLaraUnit[40] = "";
float g_dvLaraPos[3];
bool g_dvLaraPosOk = false;
bool g_dvUnitOk = false;                     // precheck_016.txt: the intro loader's Level +0x74 layout
// 0.18 (live 2026-11-06, prologue start: labels said [L3_main_bedroom] while Lara stood in that unit): unit names come
// in two spellings - the stream table entry +0xc holds the name the unit was requested with ("L3_main_bedroom" from the
// new-game start data, "l3_main_hall" from a portal), GameTracker+0x38 the current unit name. So "Lara's unit" = the
// stream entry of GameTracker+0xc0 (the whole table is scanned now - 0.16 stopped after 16 units with intro arrays and
// could miss Lara's entry); only when no loaded entry has that id, GameTracker+0x38 (it may stay on the unit the level
// was loaded with while Lara walks on, so it is the fallback, not a second match). Every comparison is case-insensitive
// (DvSameUnit, DvCommonPrefix). One "0.18 units:" log line when the two names differ in more than case.
char g_dvLaraUnit2[40] = "";                 // GameTracker+0x38 (CurrentUnit)
void CurrentUnit(char *out, size_t size);    // 0.2, above
bool DvSameUnit(const char *a, const char *b) { return a && b && a[0] && b[0] && !_stricmp(a, b); }
bool DvIsLaraUnit(const char *name) { return DvSameUnit(name, g_dvLaraUnit[0] ? g_dvLaraUnit : g_dvLaraUnit2); }
void DvUnitsRead() {
    g_dvUnitN = 0;
    g_dvLaraUnit[0] = 0;
    CurrentUnit(g_dvLaraUnit2, sizeof(g_dvLaraUnit2));
    if (!g_dvUnitOk) return;
    DWORD cur = 0;
    bool haveCur = g_unitOk && ReadDword(kUnitId, &cur);
    for (DWORD e = kStreamUnits; e < kStreamUnitsEnd; e += kStreamUnitSize) {
        DWORD id = 0, state = 0, level = 0, dtp = 0, n = 0, arr = 0;
        if (!ReadDword(e, &id) || !ReadDword(e + 4, &state) || (state & 0xff) != 2) continue;
        char name[40];
        if (!ReadString(e + 0xc, name, sizeof(name))) name[0] = 0;
        if (haveCur && id == cur) strncpy_s(g_dvLaraUnit, sizeof(g_dvLaraUnit), name, _TRUNCATE);
        if (g_dvUnitN >= 16) continue;       // 0.18: keep scanning for Lara's entry
        if (!ReadDword(e + 8, &level) || !level || !ReadDword(level + 0x74, &dtp) || !dtp || !ReadDword(dtp + 0xc, &n) ||
            n > 20000 || !ReadDword(dtp + 0x10, &arr) || !arr)
            continue;
        DvUnitRange &u = g_dvUnits[g_dvUnitN++];
        u.lo = arr;
        u.hi = arr + 0x90 * n;
        strncpy_s(u.name, sizeof(u.name), name, _TRUNCATE);
    }
    static char lastA[40] = "", lastB[40] = "";   // diagnosis, once per change
    if (strcmp(lastA, g_dvLaraUnit) || strcmp(lastB, g_dvLaraUnit2)) {
        strncpy_s(lastA, sizeof(lastA), g_dvLaraUnit, _TRUNCATE);
        strncpy_s(lastB, sizeof(lastB), g_dvLaraUnit2, _TRUNCATE);
        if (g_dvLaraUnit2[0] && !DvSameUnit(g_dvLaraUnit, g_dvLaraUnit2))
            Log(1, "0.18 units: Lara's stream unit '%s' (GameTracker+0xc0 %lu), GameTracker+0x38 '%s' - the owner tags "
                   "use %s", g_dvLaraUnit[0] ? g_dvLaraUnit : "(no loaded entry)", cur, g_dvLaraUnit2,
                g_dvLaraUnit[0] ? "the stream unit" : "GameTracker+0x38 (fallback)");
    }
}
// the owner unit's name of an instance when it is not Lara's unit, else "" (also when unknown); 0.18: case-insensitive
// against both of Lara's unit names
const char *DvOwnerUnit(DWORD inst) {
    DWORD intro = 0;
    if (!g_dvUnitN || !ReadDword(inst + 0x100, &intro) || !intro) return "";
    for (int i = 0; i < g_dvUnitN; ++i)
        if (intro >= g_dvUnits[i].lo && intro < g_dvUnits[i].hi)
            return DvIsLaraUnit(g_dvUnits[i].name) ? "" : g_dvUnits[i].name;
    return "";
}
// " 6100u v1500u [mansion_exterior_afterburn]": distance to Lara, height (^ above / v below, from 50 units), owner unit
void DvDistText(const float *p, const char *unit, char *o, size_t n) {
    size_t used = 0;
    o[0] = 0;
    if (g_dvLaraPosOk) {
        float dx = p[0] - g_dvLaraPos[0], dy = p[1] - g_dvLaraPos[1], dz = p[2] - g_dvLaraPos[2];
        LONG d = static_cast<LONG>(sqrtf(dx * dx + dy * dy + dz * dz) / 10.0f + 0.5f) * 10;
        LabelAdd(o, n, &used, " %ldu", d);
        if (fabsf(dz) >= 50.0f) LabelAdd(o, n, &used, " %c%ldu", dz > 0.0f ? '^' : 'v',
                                         static_cast<LONG>(fabsf(dz) / 10.0f + 0.5f) * 10);
    }
    const char *lara = g_dvLaraUnit[0] ? g_dvLaraUnit : g_dvLaraUnit2;   // 0.18: case-insensitive, second name
    if (unit && unit[0] && !DvIsLaraUnit(unit))
        LabelAdd(o, n, &used, " [%s]", unit + (lara[0] ? DvCommonPrefix(unit, lara) : 0));
}
const int kDvTagMax = 160;
DvTag g_dvTag[kDvTagMax];
int g_dvTagN = 0, g_dvTagShown = 0, g_dvTagSkipped = 0, g_dvTagMerged = 0, g_dvTagTrg = 0;
int g_dvTagOff = 0;                          // 0.17: candidates whose anchor lies outside the screen (skipped)
struct DvRect { float x0, y0, x1, y1; };
DvRect g_dvRects[224];
int g_dvRectN = 0;
DvRect g_dvLegendRect = {0, 0, 0, 0};        // the legend panel of the last frame (labels keep out of it)
DvRect g_qbRect = {0, 0, 0, 0};              // 0.17: the quick-toggle bar of the last frame (labels keep out of it too)
const char *const kDvBrief[kDvKinds] = {"DEATH", "FIRE", "CPT", "WATER", "SND", "TV", "TP", "?"};

bool DvRectFree(const DvRect &r) {
    for (int i = 0; i < g_dvRectN; ++i) {
        const DvRect &o = g_dvRects[i];
        if (r.x0 < o.x1 && o.x0 < r.x1 && r.y0 < o.y1 && o.y0 < r.y1) return false;
    }
    return true;
}
void DvRectTake(const DvRect &r) {
    if (g_dvRectN < static_cast<int>(sizeof(g_dvRects) / sizeof(g_dvRects[0]))) g_dvRects[g_dvRectN++] = r;
}
// one label candidate: full / brief text (+ suffixes appended after the id), merge kind and intro id (triggers)
void DvTagAdd(ImVec2 at, float dist2, const float *centre, ImU32 colour, int kind, LONG id, const char *full,
              const char *brief, const char *sufFull, const char *sufBrief, const char *unit) {
    if (g_dvTagN >= kDvTagMax) return;
    DvTag &t = g_dvTag[g_dvTagN++];
    strncpy_s(t.unit, sizeof(t.unit), unit ? unit : "", _TRUNCATE);
    t.at = at;
    t.dist2 = dist2;
    for (int k = 0; k < 3; ++k) t.centre[k] = centre[k];
    t.colour = colour;
    t.kind = kind;
    t.count = 1;
    t.idMin = t.idMax = id;
    strncpy_s(t.full, sizeof(t.full), full, _TRUNCATE);
    strncpy_s(t.brief, sizeof(t.brief), brief, _TRUNCATE);
    strncpy_s(t.sufFull, sizeof(t.sufFull), sufFull, _TRUNCATE);
    strncpy_s(t.sufBrief, sizeof(t.sufBrief), sufBrief, _TRUNCATE);
}
// "l3_bedroom_hall" / "l3_main_bedroom" -> length of the common prefix up to its last '_' ("l3_")
size_t DvCommonPrefix(const char *a, const char *b) {   // 0.18: case-insensitive ("L3_main_bedroom" / "l3_main_hall")
    size_t i = 0, cut = 0;
    while (a[i] && tolower(static_cast<unsigned char>(a[i])) == tolower(static_cast<unsigned char>(b[i]))) {
        if (a[i] == '_') cut = i + 1;
        ++i;
    }
    return cut;
}
// draw the candidates: sort nearest first, merge coincident ones, full text for the nearest and the one nearest to the
// screen centre (or all with LabelShort=0), nudge up / down or skip on overlap, at most ViewLabelMax
void DvTagsDraw(ImDrawList *dl) {
    const ImVec2 ds = ImGui::GetIO().DisplaySize;
    g_dvTagShown = g_dvTagSkipped = g_dvTagMerged = g_dvTagTrg = g_dvTagOff = 0;
    for (int i = 1; i < g_dvTagN; ++i) {     // insertion sort by distance
        DvTag t = g_dvTag[i];
        int j = i;
        while (j > 0 && g_dvTag[j - 1].dist2 > t.dist2) { g_dvTag[j] = g_dvTag[j - 1]; --j; }
        g_dvTag[j] = t;
    }
    for (int i = 0; i < g_dvTagN; ++i) {     // merge coincident (centres within 25 units, same kind) into the nearer
        DvTag &a = g_dvTag[i];
        if (a.kind < 0 || !a.count) continue;
        for (int j = i + 1; j < g_dvTagN; ++j) {
            DvTag &b = g_dvTag[j];
            if (!b.count || b.kind != a.kind) continue;
            float dx = a.centre[0] - b.centre[0], dy = a.centre[1] - b.centre[1], dz = a.centre[2] - b.centre[2];
            if (dx * dx + dy * dy + dz * dz > 25.0f * 25.0f) continue;
            if (a.kind == kDvPortals) {      // the two directions of one loading area: "a <-> b"
                const char *arrow = strstr(a.full, " -> ");
                if (arrow && a.count == 1) {
                    char unit[48];
                    size_t len = static_cast<size_t>(arrow - a.full);
                    strncpy_s(unit, sizeof(unit), a.full, len < sizeof(unit) - 1 ? len : sizeof(unit) - 1);
                    char both[96];
                    Out(both, sizeof(both), "%s <-> %s", unit, arrow + 4);
                    strncpy_s(a.full, sizeof(a.full), both, _TRUNCATE);
                    size_t cut = DvCommonPrefix(unit, arrow + 4);
                    Out(a.brief, sizeof(a.brief), "%s <-> %s", unit + cut, arrow + 4 + cut);
                }
            } else {
                if (b.idMin < a.idMin) a.idMin = b.idMin;
                if (b.idMax > a.idMax) a.idMax = b.idMax;
            }
            ++a.count;
            b.count = 0;
            ++g_dvTagMerged;
        }
    }
    int aim = -1;                            // nearest to the screen centre (within 15 % of the width)
    float best = ds.x * 0.15f * ds.x * 0.15f;
    for (int i = 0; i < g_dvTagN; ++i) {
        if (!g_dvTag[i].count) continue;
        float dx = g_dvTag[i].at.x - ds.x * 0.5f, dy = g_dvTag[i].at.y - ds.y * 0.5f;
        if (dx * dx + dy * dy < best) { best = dx * dx + dy * dy; aim = i; }
    }
    const float fs = ImGui::GetFontSize();
    bool first = true;
    for (int i = 0; i < g_dvTagN; ++i) {
        const DvTag &t = g_dvTag[i];
        if (!t.count) continue;
        if (g_dvTagShown >= g_dvTagMax) { ++g_dvTagSkipped; continue; }
        // 0.17 (live 2026-11-06: off-screen boxes had their labels pinned to the screen edges): a label whose anchor is
        // outside the screen is skipped; an anchor on screen still keeps its box inside the screen (clamp below)
        if (!(t.at.x >= 0.0f && t.at.x <= ds.x && t.at.y >= 0.0f && t.at.y <= ds.y)) { ++g_dvTagOff; continue; }
        bool full = !g_dvShort || first || i == aim;
        first = false;
        char text[160], dist[64];
        const char *base = full ? t.full : t.brief;
        const char *suf = full ? t.sufFull : t.sufBrief;
        DvDistText(t.centre, t.unit, dist, sizeof(dist));
        if (t.idMin < 0 && t.idMax < 0) Out(text, sizeof(text), "%s%s%s", base, suf, dist);
        else if (t.count > 1 && t.kind != kDvPortals)
            Out(text, sizeof(text), "%s x%d (%ld..%ld)%s", base, t.count, t.idMin, t.idMax, dist);
        else Out(text, sizeof(text), "%s %ld%s%s", base, t.idMin, suf, dist);
        ImVec2 s = ImGui::CalcTextSize(text);
        float w = s.x + 8.0f, h = fs + 4.0f;
        DvRect r = {t.at.x - w * 0.5f, t.at.y - h - 8.0f, 0, 0};
        r.x0 = r.x0 < 4.0f ? 4.0f : r.x0 > ds.x - w - 4.0f ? ds.x - w - 4.0f : r.x0;
        bool placed = false;
        const float shift[5] = {0.0f, -(h + 2.0f), h + 2.0f, -2.0f * (h + 2.0f), 2.0f * (h + 2.0f)};
        DvRect pick = r;
        for (float dy : shift) {
            pick.x0 = r.x0;
            pick.y0 = r.y0 + dy;
            pick.y0 = pick.y0 < 4.0f ? 4.0f : pick.y0 > ds.y - h - 4.0f ? ds.y - h - 4.0f : pick.y0;
            pick.x1 = pick.x0 + w;
            pick.y1 = pick.y0 + h;
            if (DvRectFree(pick)) { placed = true; break; }
        }
        if (!placed) { ++g_dvTagSkipped; continue; }
        DvRectTake(pick);
        ImU32 lead = (t.colour & 0x00ffffff) | (170u << 24);
        dl->AddLine(ImVec2(t.at.x, pick.y1 < t.at.y ? pick.y1 : pick.y0), t.at, lead, 1.2f);
        dl->AddCircleFilled(t.at, 2.5f, t.colour, 8);
        dl->AddRectFilled(ImVec2(pick.x0, pick.y0), ImVec2(pick.x1, pick.y1), IM_COL32(0, 0, 0, 170), 3.0f);
        dl->AddText(ImVec2(pick.x0 + 4.0f, pick.y0 + 2.0f), t.colour | 0xff000000u, text);
        ++g_dvTagShown;
        if (t.kind >= 0 && t.kind < kDvKinds) ++g_dvTagTrg;
    }
}
// 0.16: camera position = the point the 0.14 camera maps to (0, 0, 0): solve A p = -t (A = the 3x3 part, columns
// scaled like the text space - the inverse takes that out)
bool DvCamPos(const DvCam &c, float *o) {
    const float *m = c.v.m;
    const float a00 = m[0], a01 = m[4], a02 = m[8], a10 = m[1], a11 = m[5], a12 = m[9], a20 = m[2], a21 = m[6], a22 = m[10];
    const float det = a00 * (a11 * a22 - a12 * a21) - a01 * (a10 * a22 - a12 * a20) + a02 * (a10 * a21 - a11 * a20);
    if (!(fabsf(det) > 1.0e-12f)) return false;
    const float b0 = -m[12], b1 = -m[13], b2 = -m[14];
    o[0] = (b0 * (a11 * a22 - a12 * a21) - a01 * (b1 * a22 - a12 * b2) + a02 * (b1 * a21 - a11 * b2)) / det;
    o[1] = (a00 * (b1 * a22 - a12 * b2) - b0 * (a10 * a22 - a12 * a20) + a02 * (a10 * b2 - b1 * a20)) / det;
    o[2] = (a00 * (a11 * b2 - b1 * a21) - a01 * (a10 * b2 - b1 * a20) + b0 * (a10 * a21 - a11 * a20)) / det;
    return DvFinite(o, 3);
}
// 0.16: camera matrix + focal for a target of w x h pixels (0.14 projection), false = not readable
bool DvCamRead(DvCam *c, float w, float h) {
    if (!ReadView(&c->v, w, h) || !ReadFloats(kLblMatrix, c->v.m, 16) || !DvFinite(c->v.m, 16)) return false;
    float lx = sqrtf(c->v.m[0] * c->v.m[0] + c->v.m[4] * c->v.m[4] + c->v.m[8] * c->v.m[8]);
    float ly = sqrtf(c->v.m[1] * c->v.m[1] + c->v.m[5] * c->v.m[5] + c->v.m[9] * c->v.m[9]);
    if (!(lx > 1.0e-4f && ly > 1.0e-4f)) return false;
    c->ux = 1.0f / lx;
    c->uy = 1.0f / ly;
    return true;
}

// object names: does object id / name pass [Debug] NameMatch (cached per object id; the cache is cleared on a change)
bool DvNameMatches(int id, const char *name) {
    if (id > 0 && id < 4096 && g_dvNameHit[id]) return g_dvNameHit[id] == 1;
    bool hit = !g_dvNameMatch[0];
    if (!hit) {
        char low[64], list[sizeof(g_dvNameMatch)];
        strncpy_s(low, sizeof(low), name, _TRUNCATE);
        _strlwr_s(low, sizeof(low));
        strncpy_s(list, sizeof(list), g_dvNameMatch, _TRUNCATE);
        _strlwr_s(list, sizeof(list));
        char *context = nullptr;
        for (char *part = strtok_s(list, ", ", &context); part && !hit; part = strtok_s(nullptr, ", ", &context))
            hit = !strcmp(part, "*") || strstr(low, part) != nullptr;
    }
    if (id > 0 && id < 4096) g_dvNameHit[id] = hit ? 1 : 2;
    return hit;
}
struct DvName { DWORD inst; float pos[3], dist2; };
DvName g_dvNames[65];
// every instance (also Lara) whose object name matches, the nearest to the camera first (also from high above while
// flying), at most [Debug] NameMax within NameRadius; text size NameScale, colour NameColour
void DvDrawNames(ImDrawList *dl, const DvCam &c, char *state, size_t stateSize, size_t *used) {
    int count = 0, found = 0, walked = 0;
    const float r2 = g_dvNameRadius * g_dvNameRadius;
    DWORD inst = 0;
    ReadDword(kFirstInstance, &inst);
    for (int guard = 0; inst && guard < 4096; ++guard, ++walked) {
        DWORD next = 0, object = 0, oid = 0;
        float p[3], d2 = 0.0f;
        if (ReadDword(inst + 0x10, &object) && object && ReadDword(object + 0x14, &oid) &&
            ReadFloats(inst + kInstancePosition, p, 3) && DvFinite(p, 3)) {
            int id = static_cast<int>(oid & 0xffff);
            bool hit = false;
            if (id > 0 && id < 4096 && g_dvNameHit[id]) hit = g_dvNameHit[id] == 1;
            else {
                char name[64];
                hit = ObjectName(id, name, sizeof(name)) && DvNameMatches(id, name);
            }
            if (hit) {
                ++found;
                if (DvVisible(c, p, 100.0f, &d2) && d2 <= r2) {
                    int at = count;
                    while (at > 0 && g_dvNames[at - 1].dist2 > d2) --at;
                    if (at < g_dvNameMax) {
                        int last = count < g_dvNameMax ? count : g_dvNameMax - 1;
                        for (int m = last; m > at; --m) g_dvNames[m] = g_dvNames[m - 1];
                        g_dvNames[at].inst = inst;
                        g_dvNames[at].pos[0] = p[0]; g_dvNames[at].pos[1] = p[1]; g_dvNames[at].pos[2] = p[2];
                        g_dvNames[at].dist2 = d2;
                        if (count < g_dvNameMax) ++count;
                    }
                }
            }
        }
        if (!ReadDword(inst + 8, &next)) break;
        inst = next;
    }
    ImFont *font = ImGui::GetFont();
    const float size = ImGui::GetFontSize() * g_dvNameScale;
    const ImU32 colour = IM_COL32((g_dvNameRgb >> 16) & 0xff, (g_dvNameRgb >> 8) & 0xff, g_dvNameRgb & 0xff, 255);
    int drawn = 0, skipped = 0;
    for (int i = 0; i < count; ++i) {
        const DvName &d = g_dvNames[i];
        float q[3];
        ImVec2 at;
        DvToCam(c, d.pos, q);
        if (!DvCamToScreen(c, q, &at)) continue;
        DWORD object = 0, oid = 0, intro = 0;
        char name[64], line[160];
        ReadDword(d.inst + 0x10, &object);
        if (object) ReadDword(object + 0x14, &oid);
        if (!ObjectName(static_cast<int>(oid & 0xffff), name, sizeof(name))) Out(name, sizeof(name), "obj %lu", oid & 0xffff);
        ReadDword(d.inst + 0x58, &intro);
        char dist[64];                        // 0.16: distance / height to Lara, owner unit when not Lara's
        DvDistText(d.pos, DvOwnerUnit(d.inst), dist, sizeof(dist));
        if (g_dvNameIds) Out(line, sizeof(line), "%s %ld%s", name, static_cast<LONG>(intro), dist);
        else Out(line, sizeof(line), "%s%s", name, dist);
        ImVec2 s = font->CalcTextSizeA(size, FLT_MAX, 0.0f, line);
        ImVec2 box(at.x - s.x * 0.5f - 3.0f, at.y - s.y - 8.0f);
        const DvRect r = {box.x, box.y, box.x + s.x + 6.0f, box.y + s.y + 2.0f};
        if (!DvRectFree(r)) { ++skipped; continue; }   // 0.16: no name over a label / another name / the legend
        DvRectTake(r);
        dl->AddRectFilled(box, ImVec2(box.x + s.x + 6.0f, box.y + s.y + 2.0f), IM_COL32(0, 0, 0, 165), 3.0f);
        dl->AddCircleFilled(at, 2.5f, colour, 8);
        dl->AddText(font, size, ImVec2(box.x + 3.0f, box.y + 1.0f), colour, line);
        ++drawn;
    }
    g_dvListed[kDvNames] = found;
    g_dvDrawn[kDvNames] = drawn;
    LabelAdd(state, stateSize, used, "names %d drawn of %d matching '%s' (%d instances, radius %.0f, max %d, %d skipped: "
             "overlap); ", drawn, found, g_dvNameMatch[0] ? g_dvNameMatch : "*", walked, g_dvNameRadius, g_dvNameMax, skipped);
}

// 0.15, below: the collision overlay (stage R2) - slide faces / enemy-only collision groups of the loaded units
void RcDraw(ImDrawList *dl, const DvCam &c, char *state, size_t stateSize, size_t *used);
// 0.20, below (section "0.20 collectibles"): markers of collectibles / enemies (world, before the depth buffer is
// published), their labels (after the trigger labels), their legend rows
void M20Draw(ImDrawList *dl, const DvCam &c, char *state, size_t stateSize, size_t *used);
void M20Labels(ImDrawList *dl);
int M20Legend(char (*lines)[112], char (*counts)[24], ImU32 *colours, bool *square, int n, int max);

// 0.16, below (depth section): the depth path is usable this frame (the scene hook qualified a frame ago)
bool DpUsable();
void DpBeginFill();
void DpPublish();
const char *DpStateText();
const char *DpLegendText();                  // 0.17: "Depth: on" / "Depth: dim (waits)" for the legend

// Present, every frame while a 0.14 layer is on
void DrawDebugView() {
    char why[160];
    memset(g_dvDrawn, 0, sizeof(g_dvDrawn));
    memset(g_dvListed, 0, sizeof(g_dvListed));
    g_dvInN = g_dvInMore = g_dvCapped = g_dvEnclN = 0;
    g_dvTagN = g_dvRectN = 0;
    g_dvTagShown = g_dvTagSkipped = g_dvTagMerged = g_dvTagTrg = 0;
    if (!g_debugEnabled) { Out(g_dvState, sizeof(g_dvState), "[Debug] Enabled=0"); return; }
    if (!g_dvBaseOk) { Out(g_dvState, sizeof(g_dvState), "pre-check failed: %s", g_dvBaseWhy); return; }
    if (!LabelWorldReady(why, sizeof(why))) { Out(g_dvState, sizeof(g_dvState), "waits: %s", why); return; }
    ImGuiIO &io = ImGui::GetIO();
    DvCam c;
    if (!DvCamRead(&c, io.DisplaySize.x, io.DisplaySize.y)) {
        Out(g_dvState, sizeof(g_dvState), "camera matrix 0x%08lx / focal not readable or degenerate", kLblMatrix);
        return;
    }
    g_dvCamOk = DvCamPos(c, g_dvCamPos);
    ImDrawList *dl = ImGui::GetBackgroundDrawList();
    size_t used = 0;
    g_dvState[0] = 0;
    if (g_dvOn[kDvLegend] && g_dvLegendRect.x1 > g_dvLegendRect.x0) DvRectTake(g_dvLegendRect);
    if (g_qbRect.x1 > g_qbRect.x0) DvRectTake(g_qbRect);   // 0.17: no label under the quick-toggle bar
    // 0.16 depth: lines / faces of this frame go into a world buffer drawn inside the next frame (else ImGui, on top)
    g_dpFill = nullptr;
    if (DpUsable()) DpBeginFill();
    // the point the game tests: player +0x20 + (0, 0, 200)
    DWORD player = 0;
    g_dvTestOk = ReadDword(kPlayerPtr, &player) && player && ReadFloats(player + kInstancePosition, g_dvTestPt, 3) &&
                 DvFinite(g_dvTestPt, 3);
    g_dvLaraPosOk = g_dvTestOk;              // 0.16: labels measure from Lara +0x20
    if (g_dvTestOk) {
        for (int a = 0; a < 3; ++a) g_dvLaraPos[a] = g_dvTestPt[a];
        g_dvTestPt[2] += kDvTestLift;
    }
    DvUnitsRead();                           // 0.16: owner units of the labelled instances
    // triggers
    DvCount k = {};
    g_dvTrigCount = 0;
    int boxes = 0, spheres = 0, quads = 0, labels = 0, hiddenEncl = 0;
    if (g_dvTrgOk && DvAnyTrigger()) {
        DvCollect(c, true, &k);
        DvCollect(c, false, &k);
        // 0.16 Lara in: pulsing white outline (0.55 .. 1)
        const float pulse = 0.775f + 0.225f * sinf(static_cast<float>(GetTickCount() % 100000u) * 0.006f);
        for (int i = 0; i < g_dvTrigCount; ++i) {
            const DvTrig &t = g_dvTrig[i];
            ImVec2 at;
            bool seen = false;
            // 0.16: enclosing = the camera inside, or Lara inside a big one (sound volumes over a whole corridor)
            bool encl = t.camIn || (t.laraIn == 1 && t.big);
            if (encl && g_dvEncl == 2) { ++hiddenEncl; continue; }
            float extra = t.enabled ? 1.0f : 0.35f;   // the game skips a disabled entry
            g_dvDashed = encl && g_dvEncl == 1;
            if (g_dvDashed) { extra *= 0.35f; ++g_dvEnclN; }
            float thick = t.kind == kDvDeath ? 2.5f : 1.8f;
            ImU32 colour = DvTint(kDvLayers[t.kind].colour, t.dist2, extra);
            ImU32 fill = g_dvFill ? DvFillTint(kDvLayers[t.kind].colour, t.dist2, extra) : 0;
            if (g_dvLaraIn && g_dvLaraOk && t.laraIn && !encl) {
                DvDrawTrig(dl, c, t, IM_COL32(255, 255, 255, static_cast<int>(220.0f * pulse)), thick + 3.0f, 0, &at, &seen);
                colour = DvRgba((kDvLayers[t.kind].colour & 0xff) * 1.0f, ((kDvLayers[t.kind].colour >> 8) & 0xff) * 1.0f,
                                ((kDvLayers[t.kind].colour >> 16) & 0xff) * 1.0f, 255.0f);
                thick += 1.2f;
            }
            DvDrawTrig(dl, c, t, colour, thick, fill, &at, &seen);
            g_dvDashed = false;
            ++g_dvDrawn[t.kind];
            if (t.plane) ++quads;
            else if (t.shape == 2) ++spheres;
            else if (t.shape == 1) ++boxes;
            if (g_dvOn[kDvTrgLabels] && seen && labels < g_dvLabelMax) {
                char name[64], sufFull[24], sufBrief[16];
                DWORD intro = 0;
                if (DvNameKind(t.inst, name, sizeof(name)) == -2) Out(name, sizeof(name), "?");
                ReadDword(t.inst + 0x58, &intro);
                Out(sufFull, sizeof(sufFull), "%s%s%s", t.plane ? (t.oneSided ? " E1" : " E2") : t.shape == 2 ? " K"
                    : t.shape == 1 ? " B" : " ?", t.enabled ? "" : " (aus)", t.laraIn && g_dvLaraIn ? " <Lara>" : "");
                Out(sufBrief, sizeof(sufBrief), "%s%s", t.enabled ? "" : " aus", t.laraIn && g_dvLaraIn ? " <L>" : "");
                DvTagAdd(at, t.dist2, t.pos, kDvLayers[t.kind].colour, t.kind, static_cast<LONG>(intro), name,
                         kDvBrief[t.kind], sufFull, sufBrief, DvOwnerUnit(t.inst));
                ++labels;
            }
        }
        g_dvCapped = k.listed - k.behind - k.far_ - g_dvTrigCount;
        // the point the game tests: player +0x20 + (0, 0, 200) (white cross, not tinted: the reference)
        if (g_dvTestOk) {
            const float *p = g_dvTestPt;
            const ImU32 white = IM_COL32(255, 255, 255, 230);
            for (int a = 0; a < 3; ++a) {
                float p0[3] = {p[0], p[1], p[2]}, p1[3] = {p[0], p[1], p[2]};
                p0[a] -= 25.0f;
                p1[a] += 25.0f;
                DvLine(dl, c, p0, p1, white, 2.0f);
            }
        }
        g_dvEnclN += hiddenEncl;
        LabelAdd(g_dvState, sizeof(g_dvState), &used, "triggers %d drawn (box %d, sphere %d, plane %d) of %d listed, "
                 "%d off-screen, %d beyond %.0f, %d capped at %d, %d disabled (dim), %d without data, %d enclosing (%s), "
                 "Lara in %d%s; ", g_dvTrigCount, boxes, spheres, quads, k.listed, k.behind, k.far_, g_dvRadius,
                 g_dvCapped, g_dvTrgMax, k.disabled, k.noData, g_dvEnclN,
                 g_dvEncl == 2 ? "hidden" : g_dvEncl == 1 ? "dim + dashed" : "normal", g_dvInN + g_dvInMore,
                 g_dvLaraOk ? "" : " (result code check failed - off)");
    }
    // portals of every loaded stream unit
    if (g_dvPortalOk && g_dvOn[kDvPortals]) {
        int units = 0, portals = 0, drawn = 0;
        const ImU32 base = kDvLayers[kDvPortals].colour;
        for (DWORD e = kStreamUnits; e < kStreamUnitsEnd && portals < 128; e += kStreamUnitSize) {
            DWORD state = 0, level = 0, terrain = 0, arr = 0;
            WORD count = 0;
            if (!ReadDword(e + 4, &state) || (state & 0xff) != 2) continue;
            if (!ReadDword(e + 8, &level) || !level || !ReadDword(level, &terrain) || !terrain ||
                !ReadWord(terrain + 2, &count) || count > 64 || !ReadDword(terrain + 4, &arr) || !arr)
                continue;
            ++units;
            char unit[48];
            if (!ReadString(e + 0xc, unit, sizeof(unit))) unit[0] = 0;
            for (DWORD i = 0; i < count && portals < 128; ++i) {
                DWORD p = arr + i * 0x100;
                float q[5][4], centre[3] = {0, 0, 0};
                if (!ReadFloats(p + 0xb0, &q[0][0], 20) || !DvFinite(&q[0][0], 20)) continue;
                ++portals;
                for (int a = 0; a < 4; ++a)
                    for (int b = 0; b < 3; ++b) centre[b] += q[a][b] * 0.25f;
                float dist2 = 0.0f;
                float extent = fabsf(q[0][0] - q[2][0]) + fabsf(q[0][1] - q[2][1]) + fabsf(q[0][2] - q[2][2]);
                if (!DvVisible(c, centre, extent, &dist2)) continue;
                const ImU32 colour = DvTint(base, dist2, 1.0f), thin = DvTint(base, dist2, 0.47f);
                if (g_dvFill) {                      // 0.16 face fill (the corners are 4-float records)
                    const float quad[4][3] = {{q[0][0], q[0][1], q[0][2]}, {q[1][0], q[1][1], q[1][2]},
                                              {q[2][0], q[2][1], q[2][2]}, {q[3][0], q[3][1], q[3][2]}};
                    DvPoly(dl, c, quad, 4, DvFillTint(base, dist2, 1.0f));
                }
                bool any = false;
                for (int a = 0; a < 4; ++a) any |= DvLine(dl, c, q[a], q[(a + 1) & 3], colour, 3.0f);
                DvLine(dl, c, q[0], q[2], thin, 1.0f);
                DvLine(dl, c, q[1], q[3], thin, 1.0f);
                float tip[3] = {centre[0] + q[4][0] * 150.0f, centre[1] + q[4][1] * 150.0f, centre[2] + q[4][2] * 150.0f};
                DvLine(dl, c, centre, tip, colour, 2.0f);
                if (!any) continue;
                ++drawn;
                char name[48], full[96], brief[48];
                if (!ReadString(p, name, sizeof(name))) name[0] = 0;
                float cq[3];
                ImVec2 at;
                DvToCam(c, centre, cq);
                if (DvCamToScreen(c, cq, &at)) {     // 0.16: a label candidate (short: "-> main_bedroom")
                    Out(full, sizeof(full), "%s -> %s", unit, name);
                    Out(brief, sizeof(brief), "-> %s", name + DvCommonPrefix(unit, name));
                    DvTagAdd(at, dist2, centre, base, kDvPortals, -1, full, brief, "", "", "");
                }
            }
        }
        g_dvListed[kDvPortals] = portals;
        g_dvDrawn[kDvPortals] = drawn;
        LabelAdd(g_dvState, sizeof(g_dvState), &used, "portals %d drawn of %d in %d loaded unit(s); ", drawn, portals, units);
    }
    // checkpoint objects (instances named *checkpoint*), the active one from the game data
    if (g_dvCpOk && g_dvOn[kDvCheckpoints]) {
        DWORD data = 0, active = 0xffffffff;
        WORD mode = 0;
        if (ReadDword(kDvGameData, &data) && data && ReadWord(data + 0x1f4, &mode)) ReadDword(data + (mode ? 0x114 : 0x90), &active);
        int count = 0, found = 0;
        DWORD inst = 0;
        ReadDword(kFirstInstance, &inst);
        for (int guard = 0; inst && guard < 4096; ++guard) {
            DWORD next = 0, object = 0, oid = 0;
            if (ReadDword(inst + 0x10, &object) && object && ReadDword(object + 0x14, &oid)) {
                int id = static_cast<int>(oid & 0xffff);
                int cached = id > 0 && id < 4096 ? g_dvNameKind[id] : 0;
                bool cp = cached == kDvCheckpoint + 1;
                if (!cached) {
                    char name[64];
                    cp = DvNameKind(inst, name, sizeof(name)) == kDvCheckpoint;
                }
                float p[3], d2 = 0.0f;
                if (cp && ReadFloats(inst + kInstancePosition, p, 3) && DvFinite(p, 3)) {
                    ++found;
                    if (DvVisible(c, p, 300.0f, &d2)) {
                        int at = count;
                        while (at > 0 && g_dvCp[at - 1].dist2 > d2) --at;
                        if (at < 32) {
                            int last = count < 32 ? count : 31;
                            for (int m = last; m > at; --m) g_dvCp[m] = g_dvCp[m - 1];
                            g_dvCp[at].inst = inst;
                            g_dvCp[at].pos[0] = p[0]; g_dvCp[at].pos[1] = p[1]; g_dvCp[at].pos[2] = p[2];
                            g_dvCp[at].dist2 = d2;
                            if (count < 32) ++count;
                        }
                    }
                }
            }
            if (!ReadDword(inst + 8, &next)) break;
            inst = next;
        }
        int activeSeen = 0, capped = 0, hidden = 0;
        const float capPx = g_dvMarkerMax / 100.0f * ImGui::GetIO().DisplaySize.y;
        for (int i = 0; i < count; ++i) {
            const DvMark &m = g_dvCp[i];
            DWORD intro = 0;
            ReadDword(m.inst + 0x58, &intro);
            if (CpHidden(static_cast<LONG>(intro))) { ++hidden; continue; }   // 0.17 checkpoint list: hidden marker
            bool isActive = intro == active;
            const ImU32 base = isActive ? IM_COL32(230, 255, 60, 255) : kDvLayers[kDvCheckpoints].colour;
            const ImU32 colour = DvTint(base, m.dist2, 1.0f);
            float thick = isActive ? 2.4f : 1.8f;
            // 0.16: the marker (post 250 + diamond 60) at most MarkerMax % of the screen height - the active one stood
            // right at Lara and filled the foreground
            float scale = 1.0f, foot[3] = {m.pos[0], m.pos[1], m.pos[2]}, head[3] = {m.pos[0], m.pos[1], m.pos[2] + 310.0f};
            float qa[3], qb[3];
            ImVec2 sa, sb;
            DvToCam(c, foot, qa);
            DvToCam(c, head, qb);
            if (capPx > 0.0f && DvCamToScreen(c, qa, &sa) && DvCamToScreen(c, qb, &sb)) {
                float px = sqrtf((sb.x - sa.x) * (sb.x - sa.x) + (sb.y - sa.y) * (sb.y - sa.y));
                if (px > capPx) { scale = capPx / px; ++capped; }
                if (scale < 0.1f) scale = 0.1f;
            }
            float top[3] = {m.pos[0], m.pos[1], m.pos[2] + 250.0f * scale};
            DvLine(dl, c, m.pos, top, colour, thick);
            float d[4][3];
            const float s[4][2] = {{60, 0}, {0, 60}, {-60, 0}, {0, -60}};
            for (int a = 0; a < 4; ++a) {
                d[a][0] = top[0] + s[a][0] * scale;
                d[a][1] = top[1] + s[a][1] * scale;
                d[a][2] = top[2];
            }
            float up[3] = {top[0], top[1], top[2] + 60.0f * scale}, down[3] = {top[0], top[1], top[2] - 60.0f * scale};
            for (int a = 0; a < 4; ++a) {
                DvLine(dl, c, d[a], up, colour, thick);
                DvLine(dl, c, d[a], down, colour, thick);
            }
            float q[3];
            ImVec2 at;
            DvToCam(c, up, q);
            if (DvCamToScreen(c, q, &at)) {      // 0.16: a label candidate
                char line[64];
                Out(line, sizeof(line), "CP %ld%s", static_cast<LONG>(intro), isActive ? " ACTIVE" : "");
                DvTagAdd(at, m.dist2, m.pos, base, -1, -1, line, line, "", "", DvOwnerUnit(m.inst));
            }
            if (isActive) ++activeSeen;
        }
        g_dvListed[kDvCheckpoints] = found;
        g_dvDrawn[kDvCheckpoints] = count - hidden;
        LabelAdd(g_dvState, sizeof(g_dvState), &used, "checkpoints %d drawn of %d (active id %ld%s, %d marker(s) scaled to "
                 "%d%% of the screen, %d hidden by the list); ", count - hidden, found, static_cast<LONG>(active),
                 activeSeen ? ", drawn" : "", capped, g_dvMarkerMax, hidden);
    }
    if (g_dvOn[kDvSlide] || g_dvOn[kDvEnemyColl]) RcDraw(dl, c, g_dvState, sizeof(g_dvState), &used);   // 0.15 R2
    if (g_dvOn[kDvCollect] || g_dvOn[kDvEnemies]) M20Draw(dl, c, g_dvState, sizeof(g_dvState), &used);   // 0.20
    // 0.16: the world buffer is complete - the scene hook draws it inside the next frame; labels stay on top (ImGui)
    DWORD sinkDrop = 0;
    if (g_dpFill) {
        sinkDrop = static_cast<DWORD>(g_dpFill->dropped);
        DpPublish();
    }
    g_dpFill = nullptr;
    DvTagsDraw(dl);                          // trigger / portal / checkpoint labels: nearest first, no overlap
    M20Labels(dl);                           // 0.20: collectible / enemy labels (only what M20Draw left this frame)
    g_dvListed[kDvTrgLabels] = labels;
    g_dvDrawn[kDvTrgLabels] = g_dvTagTrg;
    if (g_dvTagN) LabelAdd(g_dvState, sizeof(g_dvState), &used, "labels %d shown of %d candidates (%d merged, %d skipped: "
                           "overlap / ViewLabelMax %d); ", g_dvTagShown, g_dvTagN, g_dvTagMerged, g_dvTagSkipped, g_dvTagMax);
    if (g_dvBaseOk && g_dvOn[kDvNames]) DvDrawNames(dl, c, g_dvState, sizeof(g_dvState), &used);
    if (g_dpMode) LabelAdd(g_dvState, sizeof(g_dvState), &used, "depth: %s%s; ", DpStateText(),
                           sinkDrop ? " (buffer full - some dropped)" : "");
    if (!used) Out(g_dvState, sizeof(g_dvState), "nothing switched on that this frame can draw");
    // once per switch (text kept from 0.14: test profiles match "0.14 debug view drawn")
    if (InterlockedExchange(&g_dvLogPending, 0)) Log(1, "0.14 debug view drawn: %s", g_dvState);
}

// 0.15, below: the legend lines of the render mode (flat view state, slide colours); returns the new count
int RmLegend(char (*lines)[112], ImU32 *colours, int n, int max);

// the legend (foreground, top right). 0.16 (owner wish 2026-11-06): fully inside the screen, right-aligned panel as wide
// as its text, semi-transparent dark background, the counts (drawn / found) in their own right-aligned column and the
// colour squares at the RIGHT edge; extra rows: capped at TriggerMax (warning colour), Lara in, depth state
void DrawDebugLegend() {
    ImGuiIO &io = ImGui::GetIO();
    ImDrawList *dl = ImGui::GetForegroundDrawList();
    const float fs = ImGui::GetFontSize(), pad = 8.0f, sq = 11.0f, gap = 14.0f, rowH = fs + 3.0f;
    const int kRows = kDvCount + 26;         // 0.20: + up to 13 kind rows of collectibles / enemies
    char lines[kRows][112], counts[kRows][24];
    ImU32 colours[kRows];
    bool square[kRows];
    int n = 0;
    // 0.17 (owner, live 2026-11-06): short English terms only, no explanations - the counts and squares stay
    Out(lines[n], sizeof(lines[n]), "Debug view");
    Out(counts[n], sizeof(counts[n]), "drawn/found");
    colours[n] = IM_COL32(235, 235, 235, 255);
    square[n++] = false;
    for (int i = 0; i < kDvCount; ++i) {
        if (!g_dvOn[i] || i == kDvLegend) continue;
        Out(lines[n], sizeof(lines[n]), "%s", kDvLayers[i].brief);
        if (i == kDvTrgLabels) Out(counts[n], sizeof(counts[n]), "%d / %d", g_dvTagTrg, g_dvListed[i]);
        else Out(counts[n], sizeof(counts[n]), "%d / %d", g_dvDrawn[i], g_dvListed[i]);
        colours[n] = kDvLayers[i].colour;
        square[n++] = true;
    }
    n = M20Legend(lines, counts, colours, square, n, kRows - 12);   // 0.20: the kinds seen (keeps 12 rows for the rest)
    if (DvAnyTrigger()) {
        Out(lines[n], sizeof(lines[n]), "Test point");
        counts[n][0] = 0;
        colours[n] = IM_COL32(255, 255, 255, 230);
        square[n++] = true;
        if (g_dvCapped > 0) {                // 0.16: live 2026-11-06 - 15 triggers silently missing at TriggerMax 64
            Out(lines[n], sizeof(lines[n]), "CAPPED");
            Out(counts[n], sizeof(counts[n]), "%d", g_dvCapped);
            colours[n] = IM_COL32(255, 90, 60, 255);
            square[n++] = true;
        }
        // 0.16 Lara in: up to 3 names, then +N; 0.18: only with [Debug] LegendLaraIn=1 (the names are in the overlay)
        if (g_dvLaraIn && g_dvLaraOk && g_dvLegendLaraIn) {
            size_t used = 0;
            lines[n][0] = 0;
            LabelAdd(lines[n], sizeof(lines[n]), &used, "Lara in:");
            int total = g_dvInN + g_dvInMore;
            for (int i = 0; i < g_dvInN && i < 3; ++i) {
                char name[64];
                if (DvNameKind(g_dvIn[i].inst, name, sizeof(name)) == -2) Out(name, sizeof(name), "?");
                LabelAdd(lines[n], sizeof(lines[n]), &used, "%s %s %ld%s%s", i ? "," : "", name, g_dvIn[i].intro,
                         g_dvIn[i].how == 2 ? " near" : "", !g_dvIn[i].enabled ? " off"
                         : !g_dvIn[i].player ? " not player" : "");
            }
            if (total > 3) LabelAdd(lines[n], sizeof(lines[n]), &used, " +%d", total - 3);
            if (!total) LabelAdd(lines[n], sizeof(lines[n]), &used, " -");
            Out(counts[n], sizeof(counts[n]), "%d", total);
            colours[n] = IM_COL32(255, 255, 255, 255);
            square[n++] = total > 0;
        }
        if (g_dvEnclN > 0) {
            Out(lines[n], sizeof(lines[n]), "%s", g_dvEncl == 2 ? "Enclosing hidden" : "Enclosing");
            Out(counts[n], sizeof(counts[n]), "%d", g_dvEnclN);
            colours[n] = IM_COL32(200, 200, 200, 230);
            square[n++] = false;
        }
    }
    if (g_dpMode && n < kRows) {
        Out(lines[n], sizeof(lines[n]), "%s", DpLegendText());
        counts[n][0] = 0;
        colours[n] = DpUsable() ? IM_COL32(160, 230, 255, 255) : IM_COL32(255, 170, 90, 255);
        square[n++] = false;
    }
    char rmLines[6][112];
    ImU32 rmColours[6];
    int rm = RmLegend(rmLines, rmColours, 0, 6);   // 0.15 flat view / slide colours
    for (int i = 0; i < rm && n < kRows; ++i) {
        strncpy_s(lines[n], sizeof(lines[n]), rmLines[i], _TRUNCATE);
        counts[n][0] = 0;
        colours[n] = rmColours[i];
        square[n++] = true;
    }
    float nameW = 0.0f, countW = 0.0f;
    for (int i = 0; i < n; ++i) {
        float a = ImGui::CalcTextSize(lines[i]).x, b = counts[i][0] ? ImGui::CalcTextSize(counts[i]).x : 0.0f;
        if (a > nameW) nameW = a;
        if (b > countW) countW = b;
    }
    const float maxW = io.DisplaySize.x - 24.0f;
    float w = pad + nameW + gap + countW + 8.0f + sq + pad;
    if (w > maxW) { nameW -= w - maxW; w = maxW; }   // a too long name is clipped, the counts stay readable
    const float x0 = io.DisplaySize.x - 12.0f - w, y0 = 40.0f, h = n * rowH + 2.0f * pad - 3.0f;
    dl->AddRectFilled(ImVec2(x0, y0), ImVec2(x0 + w, y0 + h), IM_COL32(0, 0, 0, 165), 5.0f);
    g_dvLegendRect = {x0, y0, x0 + w, y0 + h};
    const float countRight = x0 + pad + nameW + gap + countW, sqX = x0 + w - pad - sq;
    for (int i = 0; i < n; ++i) {
        const float y = y0 + pad + i * rowH;
        dl->PushClipRect(ImVec2(x0, y), ImVec2(x0 + pad + nameW + 2.0f, y + rowH), true);
        dl->AddText(ImVec2(x0 + pad, y), colours[i] | 0xff000000u, lines[i]);
        dl->PopClipRect();
        if (counts[i][0]) dl->AddText(ImVec2(countRight - ImGui::CalcTextSize(counts[i]).x, y), colours[i] | 0xff000000u,
                                      counts[i]);
        if (square[i]) dl->AddRectFilled(ImVec2(sqX, y + (fs - sq) * 0.5f + 1.0f), ImVec2(sqX + sq, y + (fs + sq) * 0.5f + 1.0f),
                                         colours[i] | 0xff000000u, 2.0f);
    }
}

void ValDvStatus(char *o, size_t n) {
    char on[200] = "";
    size_t used = 0;
    for (int i = 0; i < kDvCount; ++i)
        if (g_dvOn[i]) LabelAdd(on, sizeof(on), &used, "%s%s", used ? "," : "", kDvLayers[i].name);
    Out(o, n, "[Debug] Enabled %d; checks: triggers %s, portals %s, checkpoints %s; on: %s; last frame: %s", g_debugEnabled,
        g_dvTrgWhy, g_dvPortalWhy, g_dvCpWhy, used ? on : "-", DvAnyOn() ? g_dvState : "off");
}
void ValDvShow(char *o, size_t n) {
    size_t used = 0;
    o[0] = 0;
    for (int i = 0; i < kDvCount; ++i)
        LabelAdd(o, n, &used, "%s%s %d", i ? ", " : "", kDvLayers[i].name, g_dvOn[i] ? 1 : 0);
}
// dbg.show <layer> [0|1]
bool RunDvShow(const char *arg, char *o, size_t n) {
    char buf[64];
    strncpy_s(buf, sizeof(buf), arg ? arg : "", _TRUNCATE);
    char *context = nullptr;
    char *name = strtok_s(buf, " ", &context);
    char *value = name ? strtok_s(nullptr, " ", &context) : nullptr;
    int i = DvFind(name);
    if (i < 0) {
        Out(o, n, "usage: dbg.show <layer> [0|1] - death, fire, checkpoint, water, sound, volume, plane, unknown, portals, "
            "checkpoints, trglabels, legend, names, slide, enemycoll, collect, enemies");
        return false;
    }
    return DvSet(i, BoolArg(value ? value : "", g_dvOn[i] != 0), ShotSource("dbg.show"), o, n);
}
// one layer as a bool item (dbg.portals / dbg.checkpoints / dbg.legend)
bool DvRunOne(int layer, const char *item, const char *arg, char *o, size_t n) {
    return DvSet(layer, BoolArg(arg, g_dvOn[layer] != 0), ShotSource(item), o, n);
}
void ValDvPortals(char *o, size_t n) { Out(o, n, "%d (%d drawn of %d)", g_dvOn[kDvPortals] ? 1 : 0, g_dvDrawn[kDvPortals], g_dvListed[kDvPortals]); }
bool RunDvPortals(const char *arg, char *o, size_t n) { return DvRunOne(kDvPortals, "dbg.portals", arg, o, n); }
void ValDvCheckpoints(char *o, size_t n) {
    Out(o, n, "%d (%d drawn of %d)", g_dvOn[kDvCheckpoints] ? 1 : 0, g_dvDrawn[kDvCheckpoints], g_dvListed[kDvCheckpoints]);
}
bool RunDvCheckpoints(const char *arg, char *o, size_t n) { return DvRunOne(kDvCheckpoints, "dbg.checkpoints", arg, o, n); }
void ValDvLegend(char *o, size_t n) { Out(o, n, "%d", g_dvOn[kDvLegend] ? 1 : 0); }
bool RunDvLegend(const char *arg, char *o, size_t n) { return DvRunOne(kDvLegend, "dbg.legend", arg, o, n); }
// object names: dbg.names (layer), dbg.namefilter <list|*>, dbg.namecolour <preset|RRGGBB>, dbg.namesize <0.5..3>
void ValDvNames(char *o, size_t n) {
    Out(o, n, "%d (%d drawn of %d; filter '%s', radius %.0f, max %d, size %.2f, colour %06lX, ids %d)",
        g_dvOn[kDvNames] ? 1 : 0, g_dvDrawn[kDvNames], g_dvListed[kDvNames], g_dvNameMatch[0] ? g_dvNameMatch : "*",
        g_dvNameRadius, g_dvNameMax, g_dvNameScale, g_dvNameRgb, g_dvNameIds);
}
bool RunDvNames(const char *arg, char *o, size_t n) { return DvRunOne(kDvNames, "dbg.names", arg, o, n); }
void ValDvNameFilter(char *o, size_t n) { Out(o, n, "%s", g_dvNameMatch[0] ? g_dvNameMatch : "*"); }
bool RunDvNameFilter(const char *arg, char *o, size_t n) {
    char v[sizeof(g_dvNameMatch)];
    strncpy_s(v, sizeof(v), arg ? arg : "", _TRUNCATE);
    DvTrim(v);
    bool okChars = v[0] != 0;
    for (const char *p = v; *p; ++p)
        if (!(isalnum(static_cast<unsigned char>(*p)) || *p == '_' || *p == '*' || *p == ',' || *p == ' ')) okChars = false;
    if (!okChars) {
        Out(o, n, "usage: dbg.namefilter <comma list of name parts a-z 0-9 _ | *> (* = every instance); now '%s'",
            g_dvNameMatch[0] ? g_dvNameMatch : "*");
        return false;
    }
    strncpy_s(g_dvNameMatch, sizeof(g_dvNameMatch), strcmp(v, "*") ? v : "", _TRUNCATE);
    memset(g_dvNameHit, 0, sizeof(g_dvNameHit));
    if (g_dvPersist && g_iniPath[0]) WritePrivateProfileStringA("Debug", "NameMatch", g_dvNameMatch, g_iniPath);
    Log(1, "dbg.namefilter '%s' (src=%s)", g_dvNameMatch[0] ? g_dvNameMatch : "*", ShotSource("dbg.namefilter"));
    Out(o, n, "dbg.namefilter %s", g_dvNameMatch[0] ? g_dvNameMatch : "*");
    return true;
}
void ValDvNameColour(char *o, size_t n) { Out(o, n, "%06lX", g_dvNameRgb); }
bool RunDvNameColour(const char *arg, char *o, size_t n) {
    char v[32];
    strncpy_s(v, sizeof(v), arg ? arg : "", _TRUNCATE);
    DvTrim(v);
    DWORD rgb = 0xffffffff;
    for (const DvColourPreset &c : kDvNameColours)
        if (!_stricmp(v, c.name) || !_stricmp(v, c.de)) rgb = c.rgb;
    if (rgb == 0xffffffff && strlen(v) == 6 && strspn(v, "0123456789abcdefABCDEF") == 6) rgb = strtoul(v, nullptr, 16);
    if (rgb == 0xffffffff) {
        Out(o, n, "usage: dbg.namecolour white|yellow|cyan|magenta|RRGGBB; now %06lX", g_dvNameRgb);
        return false;
    }
    g_dvNameRgb = rgb;
    char text[8];
    Out(text, sizeof(text), "%06lX", rgb);
    if (g_dvPersist && g_iniPath[0]) WritePrivateProfileStringA("Debug", "NameColour", text, g_iniPath);
    Log(1, "dbg.namecolour %s (src=%s)", text, ShotSource("dbg.namecolour"));
    Out(o, n, "dbg.namecolour %s", text);
    return true;
}
void ValDvNameSize(char *o, size_t n) { Out(o, n, "%.2f", g_dvNameScale); }
bool RunDvNameSize(const char *arg, char *o, size_t n) {
    float v = arg && arg[0] ? static_cast<float>(atof(arg)) : 0.0f;
    if (!(v >= 0.5f && v <= 3.0f)) { Out(o, n, "usage: dbg.namesize <0.5 .. 3> (font size factor); now %.2f", g_dvNameScale); return false; }
    g_dvNameScale = v;
    char text[16];
    Out(text, sizeof(text), "%.2f", v);
    if (g_dvPersist && g_iniPath[0]) WritePrivateProfileStringA("Debug", "NameScale", text, g_iniPath);
    Log(1, "dbg.namesize %s (src=%s)", text, ShotSource("dbg.namesize"));
    Out(o, n, "dbg.namesize %s", text);
    return true;
}
// dbg.triggers: every trigger kind together
void ValDvTriggers(char *o, size_t n) {
    int drawn = 0, listed = 0;
    for (int i = 0; i < kDvKinds; ++i) { drawn += g_dvDrawn[i]; listed += g_dvListed[i]; }
    Out(o, n, "%d (%d drawn of %d)", DvAnyTrigger() ? 1 : 0, drawn, listed);
}
bool RunDvTriggers(const char *arg, char *o, size_t n) {
    bool on = BoolArg(arg, DvAnyTrigger());
    const char *src = ShotSource("dbg.triggers");
    if (!g_debugEnabled) { Out(o, n, "debug drawing off ([Debug] Enabled=0)"); return false; }
    if (!g_dvTrgOk) {
        Out(o, n, "disabled: pre-check failed (%s)", g_dvTrgWhy);
        Log(1, "dbg.triggers %d refused - %s (src=%s)", on ? 1 : 0, o, src);
        return false;
    }
    for (int i = 0; i < kDvKinds; ++i) {
        InterlockedExchange(&g_dvOn[i], on ? 1 : 0);
        DvPersistKey(kDvLayers[i].key, on);
    }
    InterlockedExchange(&g_dvLogPending, 1);
    Log(1, "dbg.triggers %d (all %d kinds, src=%s)", on ? 1 : 0, static_cast<int>(kDvKinds), src);
    Out(o, n, "dbg.triggers %d", on ? 1 : 0);
    return true;
}

// dbg.view: the master - on = every 0.14 layer + dbg.labels + draw.markup + the [Debug] ViewNav switches; off = all of
// them off (nav.off); each one stays switchable alone afterwards. Value = 1 while any of them is on.
// 0.16: the layers named in [Debug] ViewSkip (default "sound": the sound / swoosh volumes cover whole corridors) are left
// as they are when the master switches on; off still switches them off.
bool DvViewAny() {
    if (DvAnyOn() || g_lblOn || g_drawMarkup) return true;
    for (int i = 0; i < kNavCount; ++i)
        if (NavByteOn(i)) return true;
    return false;
}
void ValDvView(char *o, size_t n) {
    int layers = 0, nav = 0;
    for (int i = 0; i < kDvCount; ++i) layers += g_dvOn[i] ? 1 : 0;
    for (int i = 0; i < kNavCount; ++i) nav += NavByteOn(i) ? 1 : 0;
    Out(o, n, "%d (%d / %d layers, labels %d, markup %d, %d nav switch(es))", DvViewAny() ? 1 : 0, layers,
        static_cast<int>(kDvCount), g_lblOn ? 1 : 0, g_drawMarkup ? 1 : 0, nav);
}
bool RunDvView(const char *arg, char *o, size_t n) {
    if (!g_debugEnabled) { Out(o, n, "debug drawing off ([Debug] Enabled=0)"); return false; }
    bool on = BoolArg(arg, DvViewAny());
    const char *src = ShotSource("dbg.view");
    int layers = 0;
    for (int i = 0; i < kDvCount; ++i) {
        const char *why = "";
        if (!DvLayerOk(i, &why)) continue;
        if (on && DvViewSkips(i)) continue;   // 0.16 [Debug] ViewSkip (default sound): stays as it is; off = all off
        InterlockedExchange(&g_dvOn[i], on ? 1 : 0);
        DvPersistKey(kDvLayers[i].key, on);
        ++layers;
    }
    InterlockedExchange(&g_dvLogPending, 1);
    char lbl[160] = "not verified", mk[96] = "not verified", nav[400] = "", one[300];
    if (g_lblOk) {
        RunLabels(on ? "1" : "0", lbl, sizeof(lbl));
        DvPersistKey("Labels", on);
    }
    if (g_drawOk) {
        RunDrawMarkup(on ? "1" : "0", mk, sizeof(mk));
        DvPersistKey("Markup", on);
    }
    size_t used = 0;
    if (on) {
        char copy[sizeof(g_dvViewNav)];
        strncpy_s(copy, sizeof(copy), g_dvViewNav, _TRUNCATE);
        char *context = nullptr;
        for (char *name = strtok_s(copy, ", ", &context); name; name = strtok_s(nullptr, ", ", &context)) {
            char cmd[64];
            Out(cmd, sizeof(cmd), "%s 1", name);
            bool ok = RunNavDraw(cmd, one, sizeof(one));
            LabelAdd(nav, sizeof(nav), &used, "%s%s %s", used ? ", " : "", name, ok ? "on" : "refused");
        }
    } else {
        bool ok = RunNavOff("", one, sizeof(one));
        LabelAdd(nav, sizeof(nav), &used, "nav.off %s", ok ? "ok" : one);
    }
    Log(1, "dbg.view %d: %d layer(s), labels: %s, markup: %s, nav: %s (src=%s)", on ? 1 : 0, layers, lbl, mk,
        used ? nav : "-", src);
    Out(o, n, "dbg.view %d: %d layer(s), labels %s, markup %s, nav %s", on ? 1 : 0, layers, lbl, mk, used ? nav : "-");
    return true;
}

// ring: why a dbg.* entry (not dbg.labels) is greyed out ("" = usable; outside a level it may be switched)
const char *RmRadWhy(const char *id);        // 0.15, below
const char *DvRadWhy(const char *id, const char *arg) {
    if (!_stricmp(id, "dbg.status") || !_stricmp(id, "dbg.style")) return "";
    if (!g_debugEnabled) return "debug drawing off ([Debug] Enabled=0)";
    if (!_stricmp(id, "dbg.depth") && arg && _stricmp(arg, "off") && _stricmp(arg, "aus") && !g_dpOk) return g_dpWhy;   // 0.16
    if (!_stricmp(id, "dbg.larain") && !g_dvLaraOk) return "Lara-in checks failed";
    const char *why = "";
    if (!_stricmp(id, "dbg.show")) {
        int i = DvFind(arg);
        if (i < 0) return "unknown layer";
        return DvLayerOk(i, &why) ? "" : why;
    }
    if (!_stricmp(id, "dbg.triggers")) return g_dvTrgOk ? "" : g_dvTrgWhy;
    if (!_stricmp(id, "dbg.portals")) return g_dvPortalOk ? "" : g_dvPortalWhy;
    if (!_stricmp(id, "dbg.checkpoints")) return g_dvCpOk ? "" : g_dvCpWhy;
    if (!_strnicmp(id, "dbg.name", 8)) return g_dvBaseOk ? "" : g_dvBaseWhy;   // dbg.names / namefilter / colour / size
    if (!_stricmp(id, "dbg.slide") || !_stricmp(id, "dbg.enemycoll")) return DvLayerOk(kDvSlide, &why) ? "" : why;   // 0.15
    if (!_strnicmp(id, "dbg.flat", 8) || !_stricmp(id, "dbg.census")) return RmRadWhy(id);   // 0.15 R0 / R1
    return "";
}

// ---- 0.15 Render mode (debug view stages R0 / R1 / R2, owner order 2026-11-06): render census, flat view, collision
// overlay ----
// Workspace docs\Befund-Debug-Rendermodus-0611.md (research) and docs\Befund-TruMenu-Rendermodus-0611.md (this build);
// every byte check is pinned in work\asi\menu015\precheck_015.txt (tools/pe_bytes_check.py on the Steam exe).
// R0 census (dbg.census [frames]): for N frames the drawable Draw calls per pass id (1, 2, 0x80, 0x100, 0x200, 0x400,
//   0x800) and class (terrain / model), their device draws, render target 0 (pointer, size, format), RT1 bound, the
//   render states the game's state manager holds for each draw (cache [sm + 0x168 + 4 * state], 0x502b70: Z, Z write,
//   alpha test, alpha blend, colour write), the material pass [0x8a2340] and the PCScene::Draw calls per frame; then
//   ONE block of "0.15 census" lines in TruMenu.log with a suggested pass mask (passes drawn into a target of the back
//   buffer's size with colour writes and mostly without blending). No line per frame.
// R1 flat view (dbg.flat): inside PCTerrainDrawable / PCModelDrawable Draw of a pass in [Debug] FlatPasses every device
//   DrawIndexedPrimitive / DrawPrimitive draws with one of 16 palette pixel shaders (colour = hash of the material
//   [0xa14188], or terrain one colour / models another); right after the draw the game's own pixel shader (state
//   manager +0x20 -> PCPixelShader +0xc, the one 0x526630 set) is set again, so the state manager's cache and the
//   device agree. The device is created PURE (0x522687: flags 0x50) - no Get* state calls; the game's shader comes
//   from the cache. Palette shaders: "def c0, r, g, b, 1; mov oC0, c0" as ps_2_0 and ps_3_0, picked by the version of
//   the game's shader of that draw (a vs_3_0 needs a ps_3_0 and the other way round); no constant register is written.
//   Edge pass (dbg.flatedges): the same draw again in wireframe with a dark shader, a small depth bias and Z write off;
//   fill mode / depth bias / Z write are put back from the state manager's cache. Only into a render target of the
//   back buffer's size unless [Debug] FlatAnyTarget=1 (shadow maps / reflections stay as they are even with a wrong
//   pass mask).
// Writes into game memory (pass this list on to TruGuard's author): only while the census runs or the flat view is on,
//   in a loaded level - the .rdata words 0x849948 (PCTerrainDrawable::Draw, 0x510dd0) and 0x849758
//   (PCModelDrawable::Draw, 0x50f4a0), during a census also 0x849a2c (PCScene::Draw, 0x5150e0); each only when it
//   holds the game's function, VirtualProtect around the write (WriteDword); put back - only while it still holds
//   TruMenu's hook - when switched off, when the level is left / a level change starts, when the census ends and at
//   unload. The game device's vtable slots 81 / 82 (DrawPrimitive / DrawIndexedPrimitive, d3d9.dll or proxy memory,
//   not tru.exe) the same way. Patched / unpatched only in the Present hook (between two frames).
// R2 collision overlay (the layers slide / enemycoll of the 0.14 table): the collision meshes of every loaded stream
//   unit (table 0xdbab40, state 2: +8 Level, [Level] Terrain, +8 group count, +0xc TerrainGroups of 0x50 bytes, +0x38
//   mesh - taken only when mesh +0x3c points back to the group, 0x48d2d4), faces 20 bytes at mesh +0x34 (count +0x44),
//   vertices at +0x30 (mesh +0x54 word 0: 3 x s16, else 16-byte floats, 0x460770), world = vertex + mesh +0x20
//   (0x78d05a). Read once per change of the loaded units into a static buffer (no allocation), drawn at Present as
//   translucent triangles + edges through the 0.14 projection, the nearest to the camera first ([Debug] CollRadius /
//   CollMax), on top of everything (no depth test). Slide = clientFlags (face +0x0e) & 0x04 (0x5d3af0): red when
//   steeper than the tuning angle s16 [[0xfad764]+0x100e] degrees (0x5dd3ba: the game slides only then), orange when
//   flatter; enemy-only = TerrainGroup extra flags ([group +0x30] +0) & 0x800 (TRLAU's name; tru.exe's collision
//   filter 0x48d2d0 of collide kinds 4 / 7 skips such groups, kind 3's 0x48d280 does not - which kind is the player is
//   not proven), violet. Read-only.
