// ---- 0.21.6 quick command line (owner 2026-11-07 "bau das direkt mit", TODO "Kleine Kommandozeile in der Leiste") ----
// In the open quick bar [Cmd] FocusButton (L3 by default - the button that focuses the menu's command bar) pressed and
// released alone opens / closes a compact command line at the bar's right edge: one input line and the last kQcOutMax
// answers. A press that becomes part of the open / close combo or the ring hold (L3 + R3) is not one (the other combo
// button down while it is held cancels - the rule of FeedGamepad's FocusButton). It is the 0.6 command bar's line: every
// run goes through CmdRunLine (same parser: help / list / get / <id> [arg], same items, the history g_cmdHist shared
// with the menu's bar and TruLink cmd.run, the same "cmd (quick): ..." log line, queued game-thread answers through
// CmdNoteQueued / CmdPollQueued) - this section has no execution path of its own.
// Keyboard: typing goes to the line (key messages and the game's DirectInput reads are held while it is open), Tab = the
// selected (else the first) suggestion of CmdBuildSuggestions, Up / Down = the suggestions while a typed line has some
// (0.21.8, the menu bar's walk), else the history, Enter = run (the selected suggestion if one is selected), Esc =
// close. Pad: D-pad up / down = history (older / newer), A = run, B = close; FocusButton / A / B are kept from the game
// (QbPad), the bar's rows wait. Closing the bar closes the line.
// 0.21.8 (TODO "kleine Befehlszeile ausbauen" (2) / (3), owner 2026-11-07 21:25; history accident 21:23:53):
//  - suggestions: the menu bar's list (CmdBuildSuggestions + CmdSugRows) under the input while a typed line has some;
//  - on-screen keyboard: Y opens the 0.7 keyboard (DrawOsk / OskInput with the target g_oskQc - the same keyboard, not
//    a second one); its keys as in the menu (A type, X backspace, Y take suggestion, Start run, B back to the line,
//    LB / RB rows); while it is open the bar also keeps Start from the game (kQcOskOwn, QbPad). A real key switches
//    back to typing;
//  - safety: the line a pad step put into the input is shown with its item label ("A runs: ...") before A runs it, and
//    a pad run (A, the keyboard's Start / run key) of a line kCmdDanger names (cheats, god mode, level / unit / save
//    loads, save writes, costume resets, sw.set, ...) only arms: a footer warning, a second A within kQcArmMs runs it.
//    Enter on the real keyboard runs at once (typed on purpose).
const int kQcOutMax = 4;
const DWORD kQcArmMs = 3000;                 // 0.21.8: the second A of a dangerous pad run
char g_qcBuf[kCmdLine] = "";                 // the input line (render thread)
char g_qcSet[kCmdLine] = "";                 // text for the line, applied in the callback (history, clear after a run)
bool g_qcSetPending = false, g_qcFocus = false;
int g_qcHistPos = -1;                        // browsing g_cmdHist (index), -1 = typing
struct QcAnswer { char line[kCmdLine], answer[200]; };
QcAnswer g_qcOut[kQcOutMax];                 // newest first
int g_qcOutN = 0;
char g_qcArmLine[kCmdLine] = "";             // 0.21.8: the dangerous line the first A armed ("" = none)
const CmdDanger *g_qcArmWhy = nullptr;
DWORD g_qcArmTick = 0;
WORD g_qcPadEdges = 0, g_qcPadHeld = 0;      // 0.21.8: this frame's pad for the keyboard (QcPadTick -> DrawQuickCmd)
void QcSetText(const char *text) {
    strncpy_s(g_qcSet, sizeof(g_qcSet), text, _TRUNCATE);
    strncpy_s(g_qcBuf, sizeof(g_qcBuf), text, _TRUNCATE);   // an inactive field reads the buffer itself
    g_qcSetPending = true;
}
void QcDisarm() {
    g_qcArmLine[0] = 0;
    g_qcArmWhy = nullptr;
}
bool QcArmed() { return g_qcArmLine[0] && GetTickCount() - g_qcArmTick <= kQcArmMs; }
// the keyboard's target: this line (section "0.7 on-screen keyboard", struct OskTarget)
void QcRun(bool pad);
void QcOskRun() { QcRun(true); }             // Start / the run key: a pad run (asks twice for kCmdDanger lines)
void QcOskClose(bool) {                      // the close key / B: back to the compact line, the field gets the text
    InterlockedExchange(&g_qcOskOpen, 0);
    QcSetText(g_qcBuf);
    g_qcFocus = true;
}
void QcEdited() {
    g_qcHistPos = -1;
    g_sugSel = -1;
    QcDisarm();
}
const OskTarget g_oskQc = {g_qcBuf, QcOskRun, QcOskClose, QcEdited,
                           "A tippen  X l\303\266schen  Y Vorschlag  Start ausf\303\274hren  B zur\303\274ck  LB / RB Reihen  L3 zu",
                           "A type  X backspace  Y suggestion  Start run  B back  LB / RB rows  L3 close"};
void QcOskOpen() {
    const bool de = g_qbLang == 0;
    if (!g_cmdKeyboard) {
        QbResult(true, "%s", de ? "Bildschirmtastatur aus ([Cmd] Keyboard=0)" : "on-screen keyboard off ([Cmd] Keyboard=0)");
        return;
    }
    InterlockedExchange(&g_qcOskOpen, 1);
    g_osk = &g_oskQc;
    OskEdited();
    g_oskRow = g_qcBuf[0] ? 3 : 0;           // an empty line starts on the history chips (row 0), else the letters
    g_oskCol = 0;
    Log(1, "quick: on-screen keyboard opened");
}
void QcOpen(bool open, const char *by) {
    if (open == (g_qcOpen != 0)) return;
    const bool de = g_qbLang == 0;
    if (open && !g_cmdEnabled) {
        QbResult(true, "%s", de ? "Kommandozeile aus ([Cmd] Enabled=0)" : "command line off ([Cmd] Enabled=0)");
        return;
    }
    InterlockedExchange(&g_qcOskOpen, 0);    // 0.21.8: the keyboard opens only from the open line (Y)
    InterlockedExchange(&g_qcOpen, open ? 1 : 0);
    g_qcFocus = open;
    g_qcHistPos = -1;
    QcDisarm();
    Log(1, "quick: command line %s (%s)", open ? "opened" : "closed", by);
}
// 0.21.11 (page Rettung): a kQfLine row - "<id> <arg> " into the quick command line, the line opened; the typed line runs
// through CmdExecute as every line (kCmdDanger asks twice for save.restore / level.reload ...)
bool QcPrefill(const QbRow &r) {
    if (!g_cmdEnabled) { QcOpen(true, "rescue row"); return false; }   // QcOpen says why ([Cmd] Enabled=0)
    _snprintf_s(g_qcBuf, sizeof(g_qcBuf), _TRUNCATE, "%s %s%s", r.id, r.arg, r.arg[0] ? " " : "");
    QcOpen(true, "rescue row");
    g_qcHistPos = -1;
    g_qcFocus = g_qcOpen != 0;
    return g_qcOpen != 0;
}
// one history step (up = older, down = newer, past the newest = an empty line) - the walk of the menu bar's CmdCallback
void QcHistory(bool up) {
    char entry[kCmdLine] = "";
    EnterCriticalSection(&g_cmdLock);
    const int count = g_cmdHistCount;
    int pos = g_qcHistPos >= count ? count - 1 : g_qcHistPos;
    if (up) pos = pos < 0 ? count - 1 : pos > 0 ? pos - 1 : 0;
    else pos = pos < 0 || pos + 1 >= count ? -1 : pos + 1;
    if (pos >= 0) strncpy_s(entry, sizeof(entry), g_cmdHist[pos], _TRUNCATE);
    LeaveCriticalSection(&g_cmdLock);
    g_qcHistPos = pos;
    QcSetText(entry);
    QcDisarm();                              // 0.21.8: another line - an armed one is off
}
// the line's only run: CmdRunLine (the command bar's path), the answer into the output lines (newest first).
// 0.21.8: pad = A / the keyboard's Start or run key - a kCmdDanger line only arms the first time (footer warning), the
// same line again within kQcArmMs runs; pad false = Enter on the real keyboard (runs at once)
void QcRun(bool pad) {
    char line[kCmdLine];
    CmdClean(g_qcBuf, line, sizeof(line));
    const bool de = g_qbLang == 0;
    if (!line[0]) {
        QbResult(true, "%s", de ? "leere Zeile (help = die Befehle)" : "empty line (help = the commands)");
        return;
    }
    const CmdDanger *danger = pad ? CmdDangerOf(line) : nullptr;
    if (danger && !(QcArmed() && !strcmp(g_qcArmLine, line))) {
        strncpy_s(g_qcArmLine, sizeof(g_qcArmLine), line, _TRUNCATE);
        g_qcArmWhy = danger;
        g_qcArmTick = GetTickCount();
        Log(1, "quick: '%s' %s - armed, the same pad run within %lu ms runs it (0.21.8 safety)", line, danger->en,
            kQcArmMs);
        return;
    }
    QcDisarm();
    const char *answer = CmdRunLine(line, false, "quick");
    CmdNoteQueued(answer, line);
    if (g_qcOutN < kQcOutMax) ++g_qcOutN;
    for (int i = g_qcOutN - 1; i > 0; --i) g_qcOut[i] = g_qcOut[i - 1];
    strncpy_s(g_qcOut[0].line, sizeof(g_qcOut[0].line), line, _TRUNCATE);
    strncpy_s(g_qcOut[0].answer, sizeof(g_qcOut[0].answer), answer, _TRUNCATE);
    g_qcHistPos = -1;
    QcSetText("");
}
// QuickTick, every frame (also with the bar closed): buttons = the raw pad; blocked = bar closed, menu or ring open.
// true while the line has the pad (the bar's rows wait)
bool QcPadTick(WORD buttons, bool blocked) {
    static WORD prev = 0;
    static bool armed = false;
    const WORD edges = static_cast<WORD>(buttons & ~prev);
    prev = buttons;
    if (blocked) {                           // bar closed, menu or ring open: the line closes too
        armed = false;
        QcOpen(false, !g_qbOpen ? "bar closed" : g_menuOpen ? "menu opened" : "ring opened");
        return false;
    }
    const WORD fb = g_cmdFocusButton;
    if (fb) {
        const WORD others = static_cast<WORD>((g_toggleButtons | g_radHold) & ~fb);
        const bool down = (buttons & fb) == fb;
        if (down && (edges & fb)) armed = true;
        if (down && (buttons & others)) armed = false;   // part of L3 + R3 (menu / ring): not ours
        if (!down && armed) {
            armed = false;
            QcOpen(!g_qcOpen, "FocusButton");
            return true;
        }
        if (!down) armed = false;
    }
    if (!g_qcOpen) return false;
    if (g_qcOskOpen) {                       // 0.21.8: the keyboard has the pad - DrawQuickCmd hands it to OskInput
        g_qcPadEdges = static_cast<WORD>(g_qcPadEdges | (edges & kQcOskPad));
        g_qcPadHeld = static_cast<WORD>(buttons & kQcOskPad);
        return true;
    }
    if (edges & 0x2000) {                    // B
        QcOpen(false, "B");
        return true;
    }
    if (edges & 0x1000) QcRun(true);         // A (0.21.8: asks twice for a kCmdDanger line)
    if (edges & 0x0001) QcHistory(true);     // D-pad up = older
    if (edges & 0x0002) QcHistory(false);    // D-pad down = newer
    if (edges & kQbY) QcOskOpen();           // 0.21.8: Y = the on-screen keyboard
    return true;
}
int QcCallback(ImGuiInputTextCallbackData *d) {
    switch (d->EventFlag) {
    case ImGuiInputTextFlags_CallbackAlways:
        if (g_qcSetPending) { g_qcSetPending = false; CmdReplace(d, g_qcSet); }
        break;
    case ImGuiInputTextFlags_CallbackEdit:
        QcEdited();                          // 0.21.8: + the suggestion selection and an armed line
        break;
    case ImGuiInputTextFlags_CallbackCompletion:   // Tab: the selected (else the first) suggestion (the menu bar's list)
        CmdBuildSuggestions(d->Buf, false);
        if (g_sugCount) {
            char text[kCmdLine];
            CmdCompletionText(g_sugSel >= 0 && g_sugSel < g_sugCount ? g_sugSel : 0, text, sizeof(text), true);
            CmdReplace(d, text);
            QcEdited();
        }
        break;
    case ImGuiInputTextFlags_CallbackHistory:
        // 0.21.8: a typed line with suggestions - Up / Down choose among them (the menu bar's walk); an empty line or a
        // line from the history - Up / Down walk the history
        if (g_qcHistPos < 0 && d->BufTextLen > 0 && g_sugCount) {
            if (d->EventKey == ImGuiKey_UpArrow) { if (g_sugSel >= 0) --g_sugSel; }
            else if (g_sugSel < g_sugCount - 1) ++g_sugSel;
            break;
        }
        QcHistory(d->EventKey == ImGuiKey_UpArrow);
        g_qcSetPending = false;
        CmdReplace(d, g_qcSet);
        break;
    default:
        break;
    }
    return 0;
}
// render thread, after DrawQuick while the line is open: an ImGui window right of the bar
void DrawQuickCmd() {
    const bool de = g_qbLang == 0;
    CmdPollQueued();                         // a queued game-thread item's answer (as the menu bar)
    ImGuiViewport *vp = ImGui::GetMainViewport();
    const float x = g_qbRect.x1 > g_qbRect.x0 ? g_qbRect.x1 + 8.0f : vp->WorkPos.x + 12.0f;
    const float y = g_qbRect.y1 > g_qbRect.y0 ? g_qbRect.y0 : vp->WorkPos.y + vp->WorkSize.y * 0.3f;
    ImGui::SetNextWindowPos(ImVec2(x, y), ImGuiCond_Always);
    ImGui::SetNextWindowSize(ImVec2(vp->WorkSize.x * 0.42f, 0.0f), ImGuiCond_Always);
    ImGui::SetNextWindowBgAlpha(0.8f);
    const ImGuiWindowFlags flags = ImGuiWindowFlags_NoDecoration | ImGuiWindowFlags_NoSavedSettings |
                                   ImGuiWindowFlags_NoNav | ImGuiWindowFlags_AlwaysAutoResize;
    if (ImGui::Begin("##TruQuickCmd", nullptr, flags)) {
        ImGui::TextColored(ImVec4(1.0f, 0.86f, 0.35f, 1.0f), "%s", de ? "Kommandozeile (wie die Befehlszeile im Men\303\274)"
                                                                      : "Command line (the menu's command bar)");
        const ImGuiID id = ImGui::GetID("##qcline");
        const bool osk = g_qcOskOpen != 0;
        if (osk) {
            // 0.21.8 keyboard open: the field only shows g_qcBuf (the keys edit it); a real key switches back to typing
            // (the characters are kept, as the menu bar's 0.7.1 rule)
            g_osk = &g_oskQc;
            if (ImGui::GetActiveID() == id) ImGui::ClearActiveID();
            ImGuiIO &io = ImGui::GetIO();
            bool typed = false;
            for (int i = 0; i < io.InputQueueCharacters.Size; ++i) {
                const ImWchar c = io.InputQueueCharacters[i];
                if (c >= 32 && c < 127) { char s[2] = {static_cast<char>(c), 0}; OskAppend(s); typed = true; }
            }
            if (typed) io.InputQueueCharacters.resize(0);
            if (ImGui::IsKeyPressed(ImGuiKey_Backspace, false)) { OskBackspace(); typed = true; }
            if (typed) {
                g_qcPadEdges = g_qcPadHeld = 0;
                QcOskClose(false);
                Log(3, "quick: real keyboard -> typing");
            }
        } else {
            if (g_qcFocus || ImGui::GetActiveID() != id) ImGui::SetKeyboardFocusHere();
            g_qcFocus = false;
        }
        ImGui::SetNextItemWidth(-1.0f);
        const ImGuiInputTextFlags tf = ImGuiInputTextFlags_EnterReturnsTrue | ImGuiInputTextFlags_CallbackAlways |
                                       ImGuiInputTextFlags_CallbackEdit | ImGuiInputTextFlags_CallbackCompletion |
                                       ImGuiInputTextFlags_CallbackHistory;
        if (ImGui::InputText("##qcline", g_qcBuf, sizeof(g_qcBuf), tf, QcCallback)) {
            // 0.21.8: Enter on a selected suggestion runs it (the menu bar's rule); Enter = typed on purpose, no arming
            if (g_sugSel >= 0 && g_sugSel < g_sugCount) CmdCompletionText(g_sugSel, g_qcBuf, sizeof(g_qcBuf), false);
            QcRun(false);
        }
        if (ImGui::IsKeyPressed(ImGuiKey_Escape, false)) QcOpen(false, "Esc");
        // 0.21.8 suggestions under the input (the menu bar's list and rows) while a typed line has some
        CmdBuildSuggestions(g_qcBuf, false);
        if (g_qcOpen && !osk && g_qcHistPos < 0 && g_qcBuf[0] && g_sugCount) {
            CmdSugRows(6);
            ImGui::TextDisabled("%d / %d   %s", g_sugSel >= 0 ? g_sugSel + 1 : 0, g_sugCount,
                                de ? "hoch / runter = w\303\244hlen, Tab = \303\274bernehmen, Enter = ausf\303\274hren"
                                   : "up / down = choose, Tab = take, Enter = run");
        }
        // 0.21.8 safety: the line a pad step put into the input, with its item's label, before A runs it
        if (g_qcOpen && g_qcBuf[0] && (g_qcHistPos >= 0 || osk)) {
            char word[64];
            size_t w = 0;
            while (g_qcBuf[w] && g_qcBuf[w] != ' ' && w + 1 < sizeof(word)) { word[w] = g_qcBuf[w]; ++w; }
            word[w] = 0;
            const CmdKind k = CmdKindOf(word);
            const char *label = k != kCkUnknown && k != kCkBuiltin ? CmdLabel(word) : "";
            ImGui::TextColored(ImVec4(0.45f, 0.8f, 1.0f, 1.0f), "%s %.70s%s%.60s", osk ? (de ? "Start f\303\274hrt aus:" :
                               "Start runs:") : (de ? "A f\303\274hrt aus:" : "A runs:"), g_qcBuf, label[0] ? "  - " : "", label);
            const CmdDanger *dz = CmdDangerOf(g_qcBuf);
            if (dz && !QcArmed())
                ImGui::TextColored(ImVec4(1.0f, 0.7f, 0.3f, 1.0f), "%s %s", de ? "Vorsicht:" : "Careful:", de ? dz->de : dz->en);
        }
        if (g_qcOpen && QcArmed() && g_qcArmWhy) {
            const DWORD left = kQcArmMs - (GetTickCount() - g_qcArmTick);
            ImGui::TextColored(ImVec4(1.0f, 0.45f, 0.35f, 1.0f), de ? "ACHTUNG: %s (%s) - %s nochmal in %.1f s = ausf\303\274hren"
                                                                    : "WARNING: %s (%s) - %s again within %.1f s = run",
                               g_qcArmLine, de ? g_qcArmWhy->de : g_qcArmWhy->en, osk ? "Start" : "A",
                               static_cast<double>(left) / 1000.0);
        } else if (g_qcArmLine[0]) {
            QcDisarm();                          // the 3 s are over
        }
        char last[sizeof(g_cmdResult)] = "", lastLine[kCmdLine] = "";
        EnterCriticalSection(&g_cmdLock);    // the newest line's answer may arrive later (queued game-thread item)
        strncpy_s(last, sizeof(last), g_cmdResult, _TRUNCATE);
        strncpy_s(lastLine, sizeof(lastLine), g_cmdResultLine, _TRUNCATE);
        LeaveCriticalSection(&g_cmdLock);
        if (g_qcOutN && !strcmp(lastLine, g_qcOut[0].line))
            strncpy_s(g_qcOut[0].answer, sizeof(g_qcOut[0].answer), last, _TRUNCATE);
        for (int i = 0; i < g_qcOutN; ++i) {
            const bool ok = !strncmp(g_qcOut[i].answer, "ok", 2);
            ImGui::TextColored(i ? ImVec4(0.7f, 0.7f, 0.7f, 1.0f) : ok ? ImVec4(0.55f, 0.9f, 0.6f, 1.0f)
                                                                       : ImVec4(1.0f, 0.55f, 0.45f, 1.0f),
                               "> %.60s  %.130s", g_qcOut[i].line, g_qcOut[i].answer);
        }
        if (!g_qcOutN) ImGui::TextDisabled("%s", de ? "(noch nichts - help, list <Teil>, get <id>, <id> [Wert])"
                                                    : "(nothing yet - help, list <part>, get <id>, <id> [value])");
        if (osk && g_qcOpen) {                   // 0.21.8: the menu's keyboard, target = this line
            const WORD e = g_qcPadEdges;
            g_cmdPadEdges = e;                   // CmdPadPress (repeat of a held direction / X) reads these
            g_cmdPadHeld = g_qcPadHeld;
            g_qcPadEdges = 0;
            OskInput(g_oskQc, e);
            if (g_qcOskOpen) DrawOsk(g_oskQc);
        } else {
            g_qcPadEdges = 0;
            ImGui::TextDisabled("%s", de ? "Enter / A: ausf\303\274hren   Tab: Vorschlag   hoch / runter: Verlauf   Y: Tastatur   "
                                           "Esc / B / L3: zu"
                                         : "Enter / A: run   Tab: suggestion   up / down: history   Y: keyboard   "
                                           "Esc / B / L3: close");
        }
    }
    ImGui::End();
}
// ---- end of 0.21.6 quick command line ----

// render thread, every Present (Render, before its early return): the open bar's input from the raw pad (g_pad, before
// QbPad masks it for the game) - edges of D-pad / LB / RB (0.21.3: + X / Y), a held D-pad direction repeats after 400 ms
// every 120 ms
void QuickTick() {
    static WORD prev = 0;
    static DWORD repeatAt = 0;
    ++g_qbFrame;
    PadState pad = {};
    EnterCriticalSection(&g_padLock);
    bool have = g_padConnected[g_lastPad];
    if (have) pad = g_pad[g_lastPad];
    LeaveCriticalSection(&g_padLock);
    const WORD b = have ? static_cast<WORD>(pad.wButtons & kQbOwn) : 0;
    QbPageKeep();                            // 0.22.19: [Quick] LastPage after a page change / at the close
    if (!g_qbOpen) g_qbSavesPageSeen = 0;    // 0.18: reopened on the Saves page = a fresh scan
    // 0.21.6 quick command line: FocusButton (L3) alone opens / closes it; while open it has D-pad up / down, A, B
    const bool qcHasPad = QcPadTick(have ? pad.wButtons : static_cast<WORD>(0), !g_qbOpen || g_menuOpen || g_radOpen);
    // 0.21.7 diagnosis (live 2026-11-07 20:45, DLC 2 mission menu: the bar's "left" ran, the next X started the mission):
    // the bar can keep its buttons from the game only through PadHook (QbPad's clear); while PadHook is not called the
    // pad is read in Present and every bar button reaches the game too - one line per bar opening, one per pressed
    // button set (read only: nothing here changes the pad)
    static bool idleLogged = false, idleEdgeLogged = false;
    if (!g_qbOpen) idleLogged = idleEdgeLogged = false;
    else if (g_padModeIdle && !idleLogged) {
        idleLogged = true;
        Log(1, "quick: bar open while PadHook is not called (250 ms, the pad is read in Present) - the bar cannot keep its "
               "buttons from the game (footer 'Pad NICHT gesperrt') - diagnosis 0.21.7");
    }
    if (!g_qbOpen || g_menuOpen || g_radOpen || InterlockedExchange(&g_qbJust, 0)) {
        prev = b;                            // buttons held at the open (or while the menu / ring had them) are no edges
        repeatAt = 0;
        return;
    }
    WORD edges = static_cast<WORD>(b & ~prev);
    prev = b;
    if (g_padModeIdle && edges && !idleEdgeLogged) {   // 0.21.7 diagnosis (see above)
        idleEdgeLogged = true;
        Log(1, "quick: bar buttons 0x%04x pressed while PadHook is not called - the game reads them too (diagnosis 0.21.7)",
            edges);
    }
    if (qcHasPad) {                          // 0.21.6: the rows wait while the command line has the pad
        repeatAt = 0;
        return;
    }
    const DWORD now = GetTickCount();
    const WORD dir = static_cast<WORD>(b & 0x000F);
    if (edges & 0x000F) repeatAt = now + 400;
    else if (dir && !(dir & (dir - 1)) && repeatAt && static_cast<LONG>(now - repeatAt) >= 0) {
        edges |= dir;
        repeatAt = now + 120;
    }
    if (!dir) repeatAt = 0;
    const int pages = QbPageCount();
    if (g_qbPage < 0 || g_qbPage >= pages) g_qbPage = 0;
    if (edges & 0x0100) g_qbPage = (g_qbPage + pages - 1) % pages;         // LB
    if (edges & 0x0200) g_qbPage = (g_qbPage + 1) % pages;                 // RB
    QbBuild(g_qbPage);                       // 0.18: this frame's rows (static + special)
    const int n = g_qbViewN > 0 ? g_qbViewN : 1;
    int &row = g_qbRow[g_qbPage];
    if (row < 0 || row >= n) row = 0;
    if (edges & 0x0001) row = (row + n - 1) % n;                            // up
    if (edges & 0x0002) row = (row + 1) % n;                                // down
    for (int k = 0; k < n && row < g_qbViewN && g_qbView[row].skip; ++k)   // 0.18: headings are passed over
        row = (edges & 0x0001) ? (row + n - 1) % n : (row + 1) % n;
    if (!(edges & (0x000C | kQbX | kQbY))) return;
    const QbPage &p = kQbPages[g_qbPage];
    if (row >= g_qbViewN) return;
    g_qbActRow = nullptr;                    // 0.21.1: only the row run now goes into the recent list
    const QbRow *src = g_qbView[row].src >= 0 ? &p.rows[g_qbView[row].src]   // 0.21.3: the row behind the view
                     : p.special ? QbSpecialRow(row - g_qbStaticN) : nullptr;
    if (edges & kQbY) {                      // 0.21.3: Y = pin / unpin (section "0.21.3 X / Y"); 0.21.8: special rows too
        QbFavPin(g_qbPage, src, row - g_qbStaticN, g_qbView[row].name);
        return;
    }
    if (edges & kQbX) {                      // 0.21.3: X = execute (one press per frame: no right press on top)
        const bool swRow = QbDynIsSw(row - g_qbStaticN);   // 0.21.8: a pinned switch on page 0 (X = toggle / step)
        if (src) QbExecRow(g_qbPage, *src);  // static row, or a favourite / recent row of page 0
        else if (p.special == kQsCostume) QbSpecialAct(p.special, row - g_qbStaticN, kQbXDir);   // 0.21.6: X = now
        else if (p.special == kQsChapters) QbSpecialAct(p.special, row - g_qbStaticN, kQbXDir);   // 0.21.7: X = toggle / run
        else if (p.special) QbSpecialAct(p.special, row - g_qbStaticN, p.special == kQsSwitches || swRow ? kQbXDir : 1);
        return;
    }
    const int d = (edges & 0x0004) ? -1 : 1;                                // left = off / step down, right = on / up
    if (g_qbView[row].src >= 0) QbAct(g_qbPage, g_qbView[row].src, d);   // 0.21.1: groups hide rows - map the view
    else if (p.special) QbSpecialAct(p.special, row - g_qbStaticN, d);
}

// the closed line ([Quick] ShowClosed) only with the debug view enabled and in a level; the open bar always
bool QuickWantsDraw() {
    if (!g_qbEnabled) return false;
    return g_qbOpen || (g_qbShowClosed && g_debugEnabled && InLevel());
}

bool QbFootHint(int page, int sel, bool de, char *o, size_t n);   // 0.21.6, section "0.21.6 costumes"
bool QbHelpLine(int page, int sel, bool de, char *o, size_t n);   // 0.21.7, after QbFootHint
const QbRow *QbSelRow(int page, int sel);                          // 0.21.7, after QbFootHint

// foreground draw list, left edge at [Quick] Top % of the screen height; g_qbRect = the panel (labels keep out of it)
void DrawQuick() {
    ImGuiIO &io = ImGui::GetIO();
    ImDrawList *dl = ImGui::GetForegroundDrawList();
    ImFont *font = ImGui::GetFont();
    const float fs = ImGui::GetFontSize() * g_qbScale, pad = 6.0f * g_qbScale, rowH = fs + 4.0f * g_qbScale,
                sq = fs * 0.55f, gap = fs * 0.9f;
    const bool de = g_qbLang == 0;
    const float x0 = 12.0f, y0 = io.DisplaySize.y * static_cast<float>(g_qbTop) / 100.0f;
    char combo[48];
    QbComboText(g_qbButtons, combo, sizeof(combo));
    auto width = [&](const char *t, float size) { return font->CalcTextSizeA(size, FLT_MAX, 0.0f, t).x; };
    if (!g_qbOpen) {                         // collapsed: "Debug: N an  (View + Start)"
        char line[64], hint[64];
        const int on = QbLayersOn();
        Out(line, sizeof(line), "Debug: %d %s", on, de ? "an" : "on");
        Out(hint, sizeof(hint), "  %s", combo);
        const float w = pad + width(line, fs) + width(hint, fs * 0.8f) + pad, h = fs + 2.0f * pad * 0.6f;
        dl->AddRectFilled(ImVec2(x0, y0), ImVec2(x0 + w, y0 + h), IM_COL32(0, 0, 0, 140), 4.0f);
        dl->AddText(font, fs, ImVec2(x0 + pad, y0 + pad * 0.6f), on ? kQbBlue : IM_COL32(190, 190, 190, 255), line);
        dl->AddText(font, fs * 0.8f, ImVec2(x0 + pad + width(line, fs), y0 + pad * 0.6f + fs * 0.15f),
                    IM_COL32(150, 150, 150, 230), hint);
        g_qbRect = {x0, y0, x0 + w, y0 + h};
        return;
    }
    if (g_qbPage < 0 || g_qbPage >= QbPageCount()) g_qbPage = 0;
    if (g_qbBuiltFrame != g_qbFrame || g_qbViewPage != g_qbPage) QbBuild(g_qbPage);   // 0.18 (QuickTick skipped it)
    const QbPage &p = kQbPages[g_qbPage];
    const int n = g_qbViewN;
    int sel = g_qbRow[g_qbPage];
    if (sel < 0 || sel >= (n ? n : 1)) sel = 0;
    // 0.18: pages longer than the screen scroll with the selection (the rows above / below are counted in the title)
    const float fsSmall = fs * 0.8f;
    char help[160] = "";                     // 0.21.7: the selected row's help line (one more footer line when it has one)
    const bool hasHelp = QbHelpLine(g_qbPage, sel, de, help, sizeof(help));
    const float fixedH = pad + rowH + (g_qbHead[0] ? rowH : 0.0f) + (hasHelp ? 3.0f : 2.0f) * (fsSmall + 3.0f) + pad;
    int visible = static_cast<int>((io.DisplaySize.y * 0.97f - y0 - fixedH) / rowH);
    if (visible < 6) visible = 6;
    int first = 0;
    if (n > visible) {
        first = sel - visible / 2;
        if (first < 0) first = 0;
        if (first > n - visible) first = n - visible;
    }
    const int last = n < first + visible ? n : first + visible;
    char title[128];
    Out(title, sizeof(title), "%s  < %s >  %d/%d", de ? "Schnellschalter" : "Quick toggles", de ? p.de : p.en,
        g_qbPage + 1, QbPageCount());
    if (n > visible) {
        char more[48];
        Out(more, sizeof(more), "   %d-%d / %d", first + 1, last, n);
        strncat_s(title, sizeof(title), more, _TRUNCATE);
    }
    // 0.22.18: headings at the left, the rows of a group one step (ind) per level further right, the square column only
    // on item rows; nameW = the widest left part (indent + square column + name)
    const float ind = width("[-] ", fs);
    auto leftOf = [&](const QbView &v) { return static_cast<float>(v.depth) * ind + (v.head ? 0.0f : sq + pad); };
    float nameW = 0.0f, stateW = 0.0f, countW = 0.0f;
    for (int i = first; i < last; ++i) {
        float a = leftOf(g_qbView[i]) + width(g_qbView[i].name, fs) + (g_qbView[i].fav ? width(" *", fs) : 0.0f),   // star
              b = width(g_qbView[i].state, fs), c = width(g_qbView[i].count, fs);
        if (a > nameW) nameW = a;
        if (b > stateW) stateW = b;
        if (c > countW) countW = c;
    }
    char foot[240];
    bool result = g_qbResult[0] && GetTickCount() - g_qbResultTick < 5000;
    if (result) Out(foot, sizeof(foot), "%s", g_qbResult);
    else if (!QbFootHint(g_qbPage, sel, de, foot, sizeof(foot)))   // 0.21.6: else the selected row's keys (flight, costumes)
    {
        Out(foot, sizeof(foot), "%s", de ? "hoch / runter: Zeile   links / rechts: aus / an   LB / RB: Seite"
                                          : "up / down: row   left / right: off / on   LB / RB: page");
        if (g_shotEnabled && g_shotKey) {    // 0.21.9 (Befund 17i "F11 steht nirgends"): the [Shot] Hotkey
            char key[24], more[48];
            if (g_shotKey >= 0x70 && g_shotKey <= 0x87) Out(key, sizeof(key), "F%d", g_shotKey - 0x6f);
            else Out(key, sizeof(key), "0x%02X", g_shotKey);
            Out(more, sizeof(more), "   %s: %s", key, de ? "Foto + Marke" : "shot + mark");
            strncat_s(foot, sizeof(foot), more, _TRUNCATE);
        }
    }
    // 0.21.3: the X / Y hint on the line that a result never replaces; 0.21.7: "Y: -" where Y is refused (QbFavOk, the
    // rule of QbFavPin), the command line key (L3) when [Cmd] Enabled, and a warning while the game polls the pad past
    // PadHook (front end: the bar cannot keep its buttons from the game then - TODO "Leiste sperrt das Pad ...")
    char close[200], l3[48] = "";
    if (g_cmdEnabled && g_cmdFocusButton) {
        char b[32];
        QbComboText(g_cmdFocusButton, b, sizeof(b));
        Out(l3, sizeof(l3), "  %s: %s", b, de ? "Befehlszeile" : "cmd line");
    }
    const QbRow *selRow = QbSelRow(g_qbPage, sel);   // 0.21.8: + the special rows QbDynFav can pin
    const bool yOk = QbFavOk(QbSelRow(g_qbPage, sel)) || (!selRow && QbDynFavOk(sel - g_qbStaticN));
    Out(close, sizeof(close), "%s%s   %s: %s%s", yOk ? (de ? "X: ausf\303\274hren  Y: Favorit" : "X: run  Y: favourite")
                                                 : (de ? "X: ausf\303\274hren  Y: -" : "X: run  Y: -"), l3, combo,
        de ? "zu" : "close", g_padModeIdle ? (de ? "   (Pad NICHT gesperrt)" : "   (pad NOT held)") : "");
    float w = pad + nameW + gap + stateW + gap + countW + pad;
    float tw = width(title, fs) + 2.0f * pad, fw = width(foot, fsSmall) + 2.0f * pad, cw = width(close, fsSmall) + 2.0f * pad;
    const float pw = hasHelp ? width(help, fsSmall) + 2.0f * pad : 0.0f;   // 0.21.7 help line
    if (pw > w) w = pw < io.DisplaySize.x * 0.45f ? pw : io.DisplaySize.x * 0.45f;
    float hw = g_qbHead[0] ? width(g_qbHead, fs) + 2.0f * pad : 0.0f;
    if (tw > w) w = tw;
    if (cw > w) w = cw;
    const float maxW = io.DisplaySize.x * 0.45f;
    if (hw > w) w = hw < maxW ? hw : maxW;
    if (fw > w) w = fw < maxW ? fw : maxW;
    const int shown = n ? last - first : 1;
    const float h = fixedH + shown * rowH;
    dl->AddRectFilled(ImVec2(x0, y0), ImVec2(x0 + w, y0 + h), IM_COL32(0, 0, 0, 175), 5.0f);
    dl->AddRect(ImVec2(x0, y0), ImVec2(x0 + w, y0 + h), IM_COL32(160, 230, 255, 120), 5.0f, 0, 1.0f);
    g_qbRect = {x0, y0, x0 + w, y0 + h};
    dl->PushClipRect(ImVec2(x0, y0), ImVec2(x0 + w, y0 + h), true);
    float y = y0 + pad;
    dl->AddText(font, fs, ImVec2(x0 + pad, y), IM_COL32(255, 220, 90, 255), title);
    y += rowH;
    if (g_qbHead[0]) {
        dl->AddText(font, fs, ImVec2(x0 + pad, y), IM_COL32(190, 190, 190, 255), g_qbHead);
        y += rowH;
    }
    if (!n) {
        dl->AddText(font, fs, ImVec2(x0 + pad, y), IM_COL32(170, 170, 170, 255), de ? "(keine)" : "(none)");
        y += rowH;
    }
    const float stateX = x0 + pad + nameW + gap, countRight = x0 + w - pad;
    const float guideDx = width("[", fs) * 0.5f;
    for (int i = first; i < last; ++i) {
        const QbView &v = g_qbView[i];
        if (i == sel) {
            dl->AddRectFilled(ImVec2(x0 + 2.0f, y - 1.0f), ImVec2(x0 + w - 2.0f, y + rowH - 1.0f), IM_COL32(70, 110, 190, 150), 3.0f);
            dl->AddRectFilled(ImVec2(x0 + 2.0f, y - 1.0f), ImVec2(x0 + 5.0f, y + rowH - 1.0f), IM_COL32(255, 220, 90, 255));
        }
        // 0.22.18: a thin guide line per open group level under its "[" (rows of an open group only)
        for (int k = 0; k < v.depth; ++k) {
            const float gx = x0 + pad + static_cast<float>(k) * ind + guideDx;
            dl->AddLine(ImVec2(gx, y - 1.0f), ImVec2(gx, y + rowH - 1.0f), IM_COL32(160, 230, 255, 70), 1.0f);
        }
        const float rowX = x0 + pad + static_cast<float>(v.depth) * ind;
        const float nameX = v.head ? rowX : rowX + sq + pad;
        if (v.square) {                      // the colour square: filled = on, an outline = off
            ImVec2 a(rowX, y + (fs - sq) * 0.5f + 1.0f), b(a.x + sq, a.y + sq);
            if (v.square == 1) dl->AddRectFilled(a, b, v.col | 0xff000000u, 2.0f);
            else dl->AddRect(a, b, v.col, 2.0f, 0, 1.2f);
        }
        dl->AddText(font, fs, ImVec2(nameX, y), v.col, v.name);
        if (v.fav)                           // 0.21.8: a favourite (item + argument in [Favorites] Ids)
            dl->AddText(font, fs, ImVec2(nameX + width(v.name, fs), y), IM_COL32(255, 220, 90, 255), " *");
        dl->AddText(font, fs, ImVec2(stateX, y), v.stateCol, v.state);
        if (v.count[0]) dl->AddText(font, fs, ImVec2(countRight - width(v.count, fs), y), v.col | 0xff000000u, v.count);
        y += rowH;
    }
    dl->AddText(font, fsSmall, ImVec2(x0 + pad, y + 2.0f), result ? (g_qbResultErr ? IM_COL32(255, 130, 110, 255)
                                                                               : IM_COL32(130, 230, 140, 255))
                                                               : IM_COL32(190, 190, 190, 230), foot);
    if (hasHelp) {                           // 0.21.7: the help line between the answer / keys line and the X / Y line
        y += fsSmall + 3.0f;
        dl->AddText(font, fsSmall, ImVec2(x0 + pad, y + 2.0f), IM_COL32(150, 215, 255, 240), help);
    }
    dl->AddText(font, fsSmall, ImVec2(x0 + pad, y + fsSmall + 5.0f), g_padModeIdle ? IM_COL32(255, 170, 90, 240)
                                                                                    : IM_COL32(150, 150, 150, 230), close);
    dl->PopClipRect();
}

// items
void ValQuickOpen(char *o, size_t n) {
    int page = g_qbPage >= 0 && g_qbPage < kQbPageN ? g_qbPage : 0;
    Out(o, n, "%d (page %s, row %d; %s)", g_qbOpen ? 1 : 0, QbPageName(page, true), g_qbRow[page] + 1,
        g_qbEnabled ? "[Quick] Enabled=1" : "off: [Quick] Enabled=0");
}
bool RunQuickOpen(const char *arg, char *o, size_t n) {
    if (!g_qbEnabled) { Out(o, n, "quick-toggle bar off ([Quick] Enabled=0)"); return false; }
    bool open = BoolArg(arg, g_qbOpen != 0);
    if (open != (g_qbOpen != 0)) {
        InterlockedExchange(&g_qbOpen, open ? 1 : 0);
        if (open) InterlockedExchange(&g_qbJust, 1);
        Log(1, "quick: %s (item, src=%s)", open ? "opened" : "closed", ShotSource("quick.open"));
    }
    Out(o, n, "quick.open %d", open ? 1 : 0);
    return true;
}
void ValQuickLang(char *o, size_t n) { Out(o, n, "%s", g_qbLang ? "en" : "de"); }
bool RunQuickLang(const char *arg, char *o, size_t n) {
    char v[16];
    strncpy_s(v, sizeof(v), arg ? arg : "", _TRUNCATE);
    DvTrim(v);
    int lang = !v[0] ? !g_qbLang : !_stricmp(v, "en") ? 1 : !_stricmp(v, "de") ? 0 : -1;
    if (lang < 0) { Out(o, n, "usage: quick.lang de|en; now %s", g_qbLang ? "en" : "de"); return false; }
    g_qbLang = lang;
    IniKeep("Quick", "Language", lang ? "en" : "de");   // 0.22.18: kept over restarts
    Log(1, "quick.lang %s (src=%s): [Quick] Language written", lang ? "en" : "de", ShotSource("quick.lang"));
    Out(o, n, "quick.lang %s (kept in TruMenu.ini)", lang ? "en" : "de");
    return true;
}
void ValQuickStatus(char *o, size_t n) {
    char combo[48];
    QbComboText(g_qbButtons, combo, sizeof(combo));
    int page = g_qbPage >= 0 && g_qbPage < kQbPageN ? g_qbPage : 0;
    Out(o, n, "enabled %d, open %d, page %d/%d '%s' row %d; OpenButtons 0x%04x (%s), ChordMs %d, ShowClosed %d, "
        "Language %s, Top %d%%, Scale %.2f; toggles %ld, lone combo taps passed on %ld, held alone (passed late) %ld, rows "
        "run %ld; debug layers on %d; last: %s", g_qbEnabled, g_qbOpen ? 1 : 0, page + 1, QbPageCount(), QbPageName(page, true),
        g_qbRow[page] + 1, g_qbButtons, combo, g_qbChordMs, g_qbShowClosed, g_qbLang ? "en" : "de", g_qbTop, g_qbScale,
        g_qbToggles, g_qbTaps, g_qbLate, g_qbRuns, QbLayersOn(), g_qbResult[0] ? g_qbResult : "-");
}

// ---- 0.17 cutscene shots ----
// shot.oncine (owner wish 2026-11-06, replaces a TruLink watcher script): when a cutscene starts in a level, [Shot]
// OnCinePairs pairs of shots, one every OnCineIntervalMs - each pair = a clean shot (copied before TruMenu draws) and a
// ui shot (after it) of the SAME Present (ShotRequestPair: one lock, both in the queue; the shot worker limit may move
// the ui one a frame later when two PNGs are still being written) - so the debug view picture can be laid over the clean
// one. Names shot_<HHMMSS>_<step>_cine<NN>_<i>_clean.png / _ui.png (NN = cutscene since the start). Live 2026-11-06
// (coordinator's watcher, prologue skip 160 -> 170): the camera flips between the cutscene camera and others several
// times per cutscene - a naive re-arm saw 7 "cutscenes" in 2 minutes and ran into MaxPerMinute. So: a cutscene ends only
// after the signal has been gone for 2 s (camera changes between non-gameplay cameras keep the same burst); the first
// OnCineFastPairs pairs come every OnCineIntervalMs, the rest every OnCineSlowMs, at most OnCinePairs per cutscene;
// pairs have their own rate window (MaxPerMinute pairs per minute - manual shots keep theirs). Signal ([Shot]
// OnCineSignal, both by default):
//   cine   = the game's own cinematic test tru+0x53f00 (0.10.2 CinematicNow: [0xe7f1c0] && byte +0xdd && dword +0x2c !=
//            -1 - the TU gate TruShadowPower uses), re-checked here;
//   camera = the camera manager's current camera [0xe804f0+0x44] is not the gameplay camera [manager+0xb80] (the one the
//            manager switches back to from its transition camera +0x120, 0x5f3cbe, and whose vtable +0x54 an input edge
//            runs, 0x5f3d9c). Live 2026-11-06: gameplay 0x00e83860, the prologue cutscene 0x00e80de0 ("other").
// Only in a loaded level (player, no level change pending); read-only; one TruMenu.log line at the start and at the end
// of a burst (with the count), never per frame. Render thread (Render, before its early return), polled every 50 ms.
const DvCheck kOcCamChecks[] = {
    {0x005f3cbe, "8bbe800b0000 8b03 8b5020 57 8bcb ffd2 897e44"},
    {0x005f3d9c, "8b4644 8b8e800b0000 3bc1 7509 8b11 8b4254 ffd0"},
};
const DvCheck kOcCineChecks[] = {
    {0x00453f00, "a1c0f1e700 85c0 7418 80b8dd00000000 740c 83782cff 7406 b801000000 c3 33c0 c3 32c0 c3"},
};
bool g_ocCamOk = false, g_ocCineOk = false;
int g_ocPairs = 10, g_ocIntervalMs = 1500, g_ocSignal = 3;   // [Shot] OnCinePairs / OnCineIntervalMs / OnCineSignal
int g_ocFastPairs = 4, g_ocSlowMs = 5000;    // [Shot] OnCineFastPairs / OnCineSlowMs
const DWORD kOcEndMs = 2000;                 // the signal gone this long = the cutscene is over
const char *OcSignalName(int s) { return s == 1 ? "cine" : s == 2 ? "camera" : "both"; }

// true = a cutscene now (what = which signal)
bool OcSignal(char *what, size_t n) {
    what[0] = 0;
    if (!InLevel()) return false;
    char why[96];
    if (LevelChangePending(why, sizeof(why))) return false;
    const bool cine = (g_ocSignal & 1) && g_ocCineOk && CinematicNow();
    DWORD cam = 0, game = 0;
    const bool other = (g_ocSignal & 2) && g_ocCamOk && ReadDword(kCurrentCamera, &cam) &&
                       ReadDword(kCameraManager + 0xb80, &game) && cam && game && cam != game;
    if (!cine && !other) return false;
    Out(what, n, "%s%s%s", cine ? "cinematic test" : "", cine && other ? " + " : "", other ? "camera left [manager+0xb80]" : "");
    return true;
}
// 0.18 segments (live 2026-11-06 18:12:56 - 18:16:00: cutscene 160 flowed into the exterior cutscene 170 without the
// gameplay camera coming back - ONE cutscene, its 10 pairs were used up at 18:13:31 and the wanted forecourt moment got
// none): while a cutscene runs, a new SEGMENT with a fresh pair budget (OnCinePairs, OnCineFastPairs fast ones first) starts
// when (a) Lara's unit changes (GameTracker+0x38, case-insensitive), (b) the game's cinematic object [0xe7f1c0] changes
// to another valid one (the reads of the 0.10.2 cinematic test, same byte check; 0.20: NOT its track +0x2c - live
// 2026-11-06 20:23 the track ran 0 -> 28 -> 60 -> 92 .. inside one cinematic = a new pair every second), (c) a script prints
// "StartCinematic called" / "Cine about to play" (only while log.script redirects the prints - ScriptText). A segment is
// at least 1 s old before the next may start (one change usually shows in two signals). Spread: after the fast pairs one
// pair every OnCineSlowMs (8000 by default, was 5000) up to OnCinePairs - 4 x 1.5 s + 6 x 8 s ~ 54 s per segment.
volatile LONG g_ocScriptTick = 0;            // GetTickCount of the last StartCinematic / Cine about to play print
int g_ocSegments = 1;                        // [Shot] OnCineSegments
const DWORD kOcSegMinMs = 1000;
// game thread (ScriptText): a script line that announces a cinematic
void OcScriptLine(const char *line) {
    if (!line || !line[0]) return;
    char low[200];
    strncpy_s(low, sizeof(low), line, _TRUNCATE);
    _strlwr_s(low, sizeof(low));
    if (strstr(low, "startcinematic called") || strstr(low, "cine about to play")) {
        DWORD now = GetTickCount();
        InterlockedExchange(&g_ocScriptTick, static_cast<LONG>(now ? now : 1));
    }
}
// the game's cinematic object and its track (0 / 0xffffffff = none); reads only, the 0.10.2 check covers them
void OcCineNow(DWORD *cine, DWORD *track) {
    *cine = 0;
    *track = 0xffffffff;
    if (!g_cineOk || !ReadDword(0x00e7f1c0, cine) || !*cine) { *cine = 0; return; }
    if (!ReadDword(*cine + 0x2c, track)) *track = 0xffffffff;
}
// one summary line per segment / per cutscene (the start lines name the signal)
void OcSegEnd(const char *why) {
    Log(1, "shot.oncine: cutscene %02d segment %d end (%s) - %d pair(s) taken, %d refused%s%s; %.1f s", g_oc.burst,
        g_oc.seg, why, g_oc.pairs, g_oc.refused, g_oc.refused ? " - last: " : "", g_oc.refused ? g_oc.lastWhy : "",
        static_cast<double>(GetTickCount() - g_oc.segStart) / 1000.0);
}
void OcEnd(const char *why) {
    OcSegEnd(why);
    Log(1, "shot.oncine: cutscene %02d end (%s) - %d segment(s), %d pair(s) taken, %d refused; %.1f s", g_oc.burst, why,
        g_oc.seg, g_oc.allPairs, g_oc.allRefused, static_cast<double>(GetTickCount() - g_oc.start) / 1000.0);
    g_oc.active = false;
}
// a new segment (seg 1 = the cutscene start): fresh pair budget, what it starts with
void OcSegStart(DWORD now, const char *why) {
    ++g_oc.seg;
    g_oc.pairs = g_oc.refused = 0;
    g_oc.lastWhy[0] = 0;
    g_oc.segStart = g_oc.next = now;
    OcCineNow(&g_oc.cine, &g_oc.track);
    CurrentUnit(g_oc.unit, sizeof(g_oc.unit));
    g_oc.scriptSeen = static_cast<DWORD>(g_ocScriptTick);
    if (g_oc.seg > 1)
        Log(1, "shot.oncine: cutscene %02d segment %d start - %s; unit %s; cinematic 0x%08lx track %ld; up to %d pair(s)",
            g_oc.burst, g_oc.seg, why, g_oc.unit[0] ? g_oc.unit : "-", g_oc.cine, static_cast<LONG>(g_oc.track), g_ocPairs);
}
// why a new segment starts now ("" = none)
void OcSegReason(DWORD now, char *o, size_t n) {
    o[0] = 0;
    if (!g_ocSegments || now - g_oc.segStart < kOcSegMinMs) return;
    char unit[64];
    CurrentUnit(unit, sizeof(unit));
    if (unit[0] && g_oc.unit[0] && _stricmp(unit, g_oc.unit)) { Out(o, n, "unit %s -> %s", g_oc.unit, unit); return; }
    DWORD cine = 0, track = 0;
    OcCineNow(&cine, &track);
    if (cine && track != 0xffffffff && (!g_oc.cine || g_oc.track == 0xffffffff)) {
        g_oc.cine = cine;                    // the segment began on the camera signal: its cinematic, no new segment
        g_oc.track = track;
    } else if (cine && track != 0xffffffff && cine != g_oc.cine) {
        Out(o, n, "cinematic 0x%08lx track %ld -> 0x%08lx track %ld", g_oc.cine, static_cast<LONG>(g_oc.track), cine,
            static_cast<LONG>(track));
        return;
    } else if (cine && track != 0xffffffff) {
        g_oc.track = track;                  // 0.20 (live 20:23: track 0 -> 28 -> 60 -> 92 .. = a pair per second): the
    }                                        // track runs on inside ONE cinematic - followed, no new segment
    DWORD script = static_cast<DWORD>(g_ocScriptTick);
    if (script && script != g_oc.scriptSeen && static_cast<LONG>(script - g_oc.segStart) > 0)
        Out(o, n, "script print 'StartCinematic called' / 'Cine about to play'");
}
void OnCineTick() {
    if (!g_ocOn) {
        if (g_oc.active) OcEnd("switched off");
        g_oc.armed = true;
        g_oc.offSince = 0;
        return;
    }
    static DWORD lastPoll = 0;
    const DWORD now = GetTickCount();
    if (now - lastPoll < 50) return;
    lastPoll = now;
    char what[96];
    const bool sig = OcSignal(what, sizeof(what));
    if (g_oc.active) {                       // debounce: over only after the signal has been gone for kOcEndMs
        if (!sig) {
            if (!g_oc.offSince) g_oc.offSince = now;
            if (now - g_oc.offSince >= kOcEndMs) {
                OcEnd("gameplay camera back 2 s");
                g_oc.armed = true;
                g_oc.offSince = 0;
            }
            return;
        }
        g_oc.offSince = 0;
        char why[160];
        OcSegReason(now, why, sizeof(why));  // 0.18: a new segment inside the running cutscene
        if (why[0]) {
            OcSegEnd(why);
            OcSegStart(now, why);
        }
    } else {
        if (!sig || !g_oc.armed) return;
        g_oc.active = true;
        g_oc.armed = false;
        g_oc.offSince = 0;
        g_oc.burst = static_cast<int>((InterlockedIncrement(&g_ocBursts) - 1) % 99 + 1);   // 01 .. 99
        g_oc.seg = 0;
        g_oc.allPairs = g_oc.allRefused = 0;
        g_oc.start = now;
        OcSegStart(now, "cutscene start");
        DWORD cam = 0, state = 0;
        ReadDword(kCurrentCamera, &cam);
        ReadDword(kMainState, &state);
        char camText[96];
        CameraObjectName(cam, camText, sizeof(camText));
        Log(1, "shot.oncine: cutscene %02d start - %s; camera %s; main state %lu; unit %s; cinematic 0x%08lx track %ld; up "
            "to %d pair(s) per segment: %d every %d ms, then every %d ms; segments %s", g_oc.burst, what, camText, state,
            g_oc.unit[0] ? g_oc.unit : "-", g_oc.cine, static_cast<LONG>(g_oc.track), g_ocPairs, g_ocFastPairs,
            g_ocIntervalMs, g_ocSlowMs, g_ocSegments ? "on (unit / cinematic / script print)" : "off");
    }
    const int done = g_oc.pairs + g_oc.refused;
    if (done < g_ocPairs && static_cast<LONG>(now - g_oc.next) >= 0) {
        char name[32], file[160], why[160];
        if (g_oc.seg > 1) Out(name, sizeof(name), "cine%02ds%d_%d", g_oc.burst, g_oc.seg, done + 1);
        else Out(name, sizeof(name), "cine%02d_%d", g_oc.burst, done + 1);
        if (ShotRequestPair(name, "shot.oncine", file, sizeof(file), why, sizeof(why))) { ++g_oc.pairs; ++g_oc.allPairs; }
        else {
            ++g_oc.refused;
            ++g_oc.allRefused;
            strncpy_s(g_oc.lastWhy, sizeof(g_oc.lastWhy), why, _TRUNCATE);
        }
        g_oc.next = now + static_cast<DWORD>(done + 1 < g_ocFastPairs ? g_ocIntervalMs : g_ocSlowMs);
    }
}
void ValShotOnCine(char *o, size_t n) {
    char run[48];
    if (g_oc.active) Out(run, sizeof(run), "a cutscene runs, segment %d", g_oc.seg);
    else Out(run, sizeof(run), "armed");
    Out(o, n, "%d (up to %d pairs per segment: %d every %d ms, then every %d ms; segments %s; signal %s; camera checks %s, "
        "cinematic test %s; %ld cutscene(s), %s)", g_ocOn ? 1 : 0, g_ocPairs, g_ocFastPairs, g_ocIntervalMs, g_ocSlowMs,
        g_ocSegments ? "on" : "off", OcSignalName(g_ocSignal), g_ocCamOk ? "ok" : "failed", g_ocCineOk ? "ok" : "failed",
        g_ocBursts, run);
}
bool RunShotOnCine(const char *arg, char *o, size_t n) {
    bool on = BoolArg(arg, g_ocOn != 0);
    if (on && !(((g_ocSignal & 1) && g_ocCineOk) || ((g_ocSignal & 2) && g_ocCamOk))) {
        Out(o, n, "disabled: pre-check failed (camera %s, cinematic test %s, signal %s)", g_ocCamOk ? "ok" : "failed",
            g_ocCineOk ? "ok" : "failed", OcSignalName(g_ocSignal));
        Log(1, "shot.oncine 1 refused - %s (src=%s)", o, ShotSource("shot.oncine"));
        return false;
    }
    InterlockedExchange(&g_ocOn, on ? 1 : 0);
    Log(1, "shot.oncine %d (%d pairs every %d ms, signal %s; src=%s)", on ? 1 : 0, g_ocPairs, g_ocIntervalMs,
        OcSignalName(g_ocSignal), ShotSource("shot.oncine"));
    Out(o, n, "shot.oncine %d", on ? 1 : 0);
    return true;
}

// ---- 0.17 checkpoint list ----
// Lukas, live 2026-11-06 ("aus den Checkpoints zum Abhaken einen Menuepunkt machen, auflisten und dann an / aus"): every
// checkpoint instance of the loaded units (the 0.14 rule: object name contains "checkpoint") with intro id [inst+0x58],
// owner unit (0.16 DvOwnerUnit), distance / height to Lara and ACTIVE for the one in the game data (+0x90, +0x114 when the
// word +0x1f4 is set - the 0.14 checks); per checkpoint its marker on / off (g_cpHide, [Debug] CheckpointHide, written
// back with Persist=1), all on / all off, and "go to" = cheat.flight 1 + player.goto <intro> as a two-step shortcut (the
// regression-shortcut runner: one game-thread command per free request slot). Read-only except the existing items.
struct CpRow { DWORD inst; LONG intro; float pos[3], dist, dz; char unit[40]; bool active, hidden; };
const int kCpMax = 48;
CpRow g_cpRows[kCpMax];                      // render thread: the list of the last menu / bar frame
int g_cpRowN = 0;
// the checkpoints nearest to Lara first; units = owner unit names (render thread only: DvUnitsRead's globals)
int CpCollect(CpRow *rows, int max, bool units, int *total) {
    *total = 0;
    if (!g_dvCpOk || !InLevel()) return 0;
    DWORD data = 0, active = 0xffffffff;
    WORD mode = 0;
    if (ReadDword(kDvGameData, &data) && data && ReadWord(data + 0x1f4, &mode)) ReadDword(data + (mode ? 0x114 : 0x90), &active);
    float lara[3] = {0, 0, 0}, rot[3];
    DWORD li = 0;
    const bool haveLara = ReadLara(lara, rot, &li);
    if (units) DvUnitsRead();
    int n = 0;
    DWORD inst = 0;
    ReadDword(kFirstInstance, &inst);
    for (int guard = 0; inst && guard < 4096; ++guard) {
        DWORD next = 0, object = 0, oid = 0;
        if (ReadDword(inst + 0x10, &object) && object && ReadDword(object + 0x14, &oid)) {
            int id = static_cast<int>(oid & 0xffff);
            int cached = id > 0 && id < 4096 ? g_dvNameKind[id] : 0;
            bool cp = cached == kDvCheckpoint + 1;
            if (!cached) {
                char name[64];
                cp = DvNameKind(inst, name, sizeof(name)) == kDvCheckpoint;
            }
            float p[3];
            DWORD intro = 0;
            if (cp && ReadFloats(inst + kInstancePosition, p, 3) && DvFinite(p, 3) && ReadDword(inst + 0x58, &intro)) {
                ++*total;
                CpRow r = {};
                r.inst = inst;
                r.intro = static_cast<LONG>(intro);
                for (int k = 0; k < 3; ++k) r.pos[k] = p[k];
                float dx = p[0] - lara[0], dy = p[1] - lara[1], dz = p[2] - lara[2];
                r.dist = haveLara ? sqrtf(dx * dx + dy * dy + dz * dz) : 0.0f;
                r.dz = haveLara ? dz : 0.0f;
                r.active = intro == active;
                r.hidden = CpHidden(r.intro);
                if (units) strncpy_s(r.unit, sizeof(r.unit), DvOwnerUnit(inst), _TRUNCATE);
                int at = n;
                while (at > 0 && rows[at - 1].dist > r.dist) --at;
                if (at < max) {
                    int last = n < max ? n : max - 1;
                    for (int m = last; m > at; --m) rows[m] = rows[m - 1];
                    rows[at] = r;
                    if (n < max) ++n;
                }
            }
        }
        if (!ReadDword(inst + 8, &next)) break;
        inst = next;
    }
    return n;
}
// "4321 [main_hall] 1200u ^300u ACTIVE (aus)"
void CpRowText(const CpRow &r, bool de, char *o, size_t n) {
    char dist[48] = "";
    if (r.dist > 0.0f) {
        LONG d = static_cast<LONG>(r.dist / 10.0f + 0.5f) * 10;
        if (fabsf(r.dz) >= 50.0f) Out(dist, sizeof(dist), " %ldu %c%ldu", d, r.dz > 0.0f ? '^' : 'v',
                                      static_cast<LONG>(fabsf(r.dz) / 10.0f + 0.5f) * 10);
        else Out(dist, sizeof(dist), " %ldu", d);
    }
    const char *unit = r.unit + (r.unit[0] && g_dvLaraUnit[0] ? DvCommonPrefix(r.unit, g_dvLaraUnit) : 0);
    Out(o, n, "CP %ld%s%s%s%s%s", r.intro, unit[0] ? " [" : "", unit, unit[0] ? "]" : "", dist, r.active ? " ACTIVE" : "");
    (void)de;
}
void CpPersist() {
    if (!g_dvPersist || !g_iniPath[0]) return;
    char list[512] = "";
    size_t used = 0;
    for (LONG i = 0; i < 65536; ++i)
        if (CpHidden(i)) LabelAdd(list, sizeof(list), &used, "%s%ld", used ? "," : "", i);
    WritePrivateProfileStringA("Debug", "CheckpointHide", list, g_iniPath);
}
void CpSetHidden(LONG intro, bool hide) {
    if (intro < 0 || intro >= 65536) return;
    BYTE bit = static_cast<BYTE>(1 << (intro & 7));
    if (hide) g_cpHide[intro >> 3] = static_cast<BYTE>(g_cpHide[intro >> 3] | bit);
    else g_cpHide[intro >> 3] = static_cast<BYTE>(g_cpHide[intro >> 3] & ~bit);
}
// [Debug] CheckpointHide at the start: a comma list of intro ids
void CpHideParse(const char *list) {
    memset(const_cast<BYTE *>(g_cpHide), 0, sizeof(g_cpHide));
    char copy[512];
    strncpy_s(copy, sizeof(copy), list ? list : "", _TRUNCATE);
    char *context = nullptr;
    for (char *w = strtok_s(copy, ", ", &context); w; w = strtok_s(nullptr, ", ", &context)) {
        char *end = nullptr;
        long v = strtol(w, &end, 10);
        if (end && !*end && v >= 0 && v < 65536) CpSetHidden(v, true);
    }
}
int CpHiddenCount() {
    int c = 0;
    for (LONG i = 0; i < 65536; ++i) c += CpHidden(i) ? 1 : 0;
    return c;
}
void ValDvCp(char *o, size_t n) { Out(o, n, "%d marker(s) hidden ([Debug] CheckpointHide)", CpHiddenCount()); }
// dbg.cp <intro> [0|1]: one checkpoint marker on / off (no value = the other state)
bool RunDvCp(const char *arg, char *o, size_t n) {
    char buf[48];
    strncpy_s(buf, sizeof(buf), arg ? arg : "", _TRUNCATE);
    char *context = nullptr;
    char *id = strtok_s(buf, " ", &context);
    char *value = id ? strtok_s(nullptr, " ", &context) : nullptr;
    char *end = nullptr;
    long intro = id ? strtol(id, &end, 10) : -1;
    if (!id || !end || *end || intro < 0 || intro >= 65536) { Out(o, n, "usage: dbg.cp <intro id> [0|1]"); return false; }
    if (!DvGate("dbg.cp", o, n)) return false;
    bool show = BoolArg(value ? value : "", !CpHidden(intro));
    CpSetHidden(intro, !show);
    CpPersist();
    Log(1, "dbg.cp %ld %d (src=%s)", intro, show ? 1 : 0, ShotSource("dbg.cp"));
    Out(o, n, "dbg.cp %ld %d%s", intro, show ? 1 : 0, g_dvOn[kDvCheckpoints] ? "" : " (layer Checkpoints is off)");
    return true;
}
// dbg.cpall 0|1: 1 = every marker shown (list cleared), 0 = every checkpoint of the loaded units hidden
bool RunDvCpAll(const char *arg, char *o, size_t n) {
    if (!DvGate("dbg.cpall", o, n)) return false;
    if (!g_dvCpOk) { Out(o, n, "disabled: pre-check failed (%s)", g_dvCpWhy); return false; }
    bool show = BoolArg(arg, CpHiddenCount() != 0);
    int total = 0, changed = 0;
    if (show) {
        changed = CpHiddenCount();
        memset(const_cast<BYTE *>(g_cpHide), 0, sizeof(g_cpHide));
    } else {
        CpRow rows[kCpMax];
        int k = CpCollect(rows, kCpMax, false, &total);
        for (int i = 0; i < k; ++i)
            if (!rows[i].hidden) { CpSetHidden(rows[i].intro, true); ++changed; }
    }
    CpPersist();
    Log(1, "dbg.cpall %d: %d marker(s) changed (src=%s)", show ? 1 : 0, changed, ShotSource("dbg.cpall"));
    Out(o, n, "dbg.cpall %d: %d marker(s) changed", show ? 1 : 0, changed);
    return true;
}
void ValDvCpList(char *o, size_t n) {
    CpRow rows[kCpMax];
    int total = 0;
    const bool render = g_renderThread && GetCurrentThreadId() == g_renderThread;
    int k = CpCollect(rows, kCpMax, render, &total);
    size_t used = 0;
    o[0] = 0;
    LabelAdd(o, n, &used, "%d checkpoint(s) in the loaded units%s", total, total ? ":" : "");
    for (int i = 0; i < k; ++i) {
        char t[128];
        CpRowText(rows[i], false, t, sizeof(t));
        LabelAdd(o, n, &used, " %s%s;", t, rows[i].hidden ? " (hidden)" : "");
    }
}
// dbg.cpgo <intro>|active: flight on, then Lara to the checkpoint (player.goto) - two queued steps
bool RunDvCpGo(const char *arg, char *o, size_t n) {
    char v[32];
    strncpy_s(v, sizeof(v), arg ? arg : "", _TRUNCATE);
    DvTrim(v);
    LONG intro = -1;
    if (!_stricmp(v, "active") || !_stricmp(v, "aktiv")) {
        CpRow rows[kCpMax];
        int total = 0, k = CpCollect(rows, kCpMax, false, &total);
        for (int i = 0; i < k; ++i)
            if (rows[i].active) intro = rows[i].intro;
        if (intro < 0) { Out(o, n, "the active checkpoint is not among the %d of the loaded units", total); return false; }
    } else {
        char *end = nullptr;
        long x = strtol(v, &end, 10);
        if (!v[0] || !end || *end || x < 0) { Out(o, n, "usage: dbg.cpgo <intro id>|active"); return false; }
        intro = x;
    }
    char steps[96], title[48];
    Out(steps, sizeof(steps), "cheat.flight 1;player.goto %ld", intro);
    Out(title, sizeof(title), "checkpoint %ld", intro);
    Log(1, "dbg.cpgo %ld: %s (src=%s)", intro, steps, ShotSource("dbg.cpgo"));
    return ShortcutStart(steps, title, o, n);
}
// 0.21.9 cp.jump <unit> <checkpoint intro> (docs\Befund-17i-Menue-Luecken-0811.md "Abschnitte als Checkpoint-Spruenge":
// "Sicherung -> level.load -> wait.unit -> dbg.cpgo"): one shortcut of the 0.8.1 runner - save.backup kapitel, unit.go
// <unit> (the stream portal when the unit is loaded, nothing when Lara is in it, else level.load - the runner decides
// when the step comes), wait.unit <unit>, dbg.cpgo <intro> (in a shortcut run in place as cheat.flight 1 + player.goto,
// ShortcutTick). Debug: no story value is set; the page Kapitel / Tests rows ask right twice (kQfConfirm).
bool RunCpJump(const char *arg, char *o, size_t n) {
    char unit[64] = "", rest[16] = "";
    if (!arg || sscanf_s(arg, "%63s %15s", unit, static_cast<unsigned>(sizeof(unit)), rest,
                         static_cast<unsigned>(sizeof(rest))) != 2) {
        Out(o, n, "usage: cp.jump <unit> <checkpoint intro id> (backup, unit.go, wait.unit, dbg.cpgo)");
        return false;
    }
    char *end = nullptr;
    const long intro = strtol(rest, &end, 10);
    if (!end || *end || intro <= 0) { Out(o, n, "cp.jump: '%s' is no intro id", rest); return false; }
    if (UnitIndexOf(unit) < 0) { Out(o, n, "cp.jump: %s is not in the level list (level.load values)", unit); return false; }
    if (UnitNameNoDrm(unit)) { Out(o, n, "cp.jump: %s has no .drm in mods - not loadable", unit); return false; }
    char why[200];
    if (LevelChangePending(why, sizeof(why))) { Out(o, n, "refused: level change pending (%s)", why); return false; }
    char steps[200], title[64];
    Out(steps, sizeof(steps), "save.backup kapitel;unit.go %s;wait.unit %s;dbg.cpgo %ld", unit, unit, intro);
    Out(title, sizeof(title), "CP %ld (%s)", intro, unit);
    Log(1, "cp.jump %s %ld: %s (src=%s)", unit, intro, steps, ShotSource("cp.jump"));
    return ShortcutStart(steps, title, o, n);
}

// ---- 0.17 position bookmarks ----
// Coordinator, live 2026-11-06: a teleport to converted coordinates of l3_main_hall from l3_main_bedroom ended in the void
// (the target unit was not loaded, the frame conversion was off by ~450 units). pos.save <name> keeps Lara's unit, live
// position, yaw, the unit's current shift P and its origin V in TruMenu.positions.txt next to tru.exe (one line each,
// "name|unit|x y z|yaw|Px Py Pz|Vx Vy Vz|saved"); pos.go <name> teleports ONLY when that unit is loaded (stream unit
// table, state 2) and converts with the unit's shift then and now: live = data - V + P (Befund-Position-und-Schrotflinte,
// P = 0 for Lara's unit) -> target = saved - P(saved) + P(now); V cancels and is kept for tools/unit_frames.py. Not loaded
// = refused with the reason (level.load <unit> stays a separate, explicit step). Byte checks: STREAM_LevelLoadAndInit
// reads P = [[entry+8 Level]+0] Terrain +0x10 -> 3 floats (0x5d3180 / 0x5d31a2), the intro loader writes V = Level
// +0x80 (0x5d1d39); the table itself = the 0.2 unit checks (g_unitOk). One TruMenu.log line per save / go.
const DvCheck kPosChecks[] = {
    {0x005d3180, "8b5608 8b02 8b4010 85c0 7445"},
    {0x005d31a2, "f30f10c8 f30f5c4808 f30f114c2448 f30f10c8 f30f5c00 f30f5c4804"},
    {0x005d1d39, "898e80000000 8b4c241c 899684000000 8b16 898688000000"},
};
bool g_posOk = false;
const char *g_posWhy = "not checked";
struct PosRow { char name[40], unit[48], saved[24]; float p[3], yaw, shift[3], origin[3]; };
const int kPosMax = 64;
void PosPath(char *o, size_t n) { Out(o, n, "%sTruMenu.positions.txt", g_exeDir); }
int PosLoad(PosRow *rows, int max) {
    char path[MAX_PATH];
    PosPath(path, sizeof(path));
    FILE *f = nullptr;
    if (fopen_s(&f, path, "r") || !f) return 0;
    int n = 0;
    char line[512];
    while (n < max && fgets(line, sizeof(line), f)) {
        if (line[0] == '#' || line[0] == '\n' || line[0] == '\r') continue;
        PosRow r = {};
        char *context = nullptr, *field[7] = {};
        int k = 0;
        for (char *t = strtok_s(line, "|\r\n", &context); t && k < 7; t = strtok_s(nullptr, "|\r\n", &context)) field[k++] = t;
        if (k < 6) continue;
        strncpy_s(r.name, sizeof(r.name), field[0], _TRUNCATE);
        strncpy_s(r.unit, sizeof(r.unit), field[1], _TRUNCATE);
        if (!ParseFloats(field[2], r.p, 3) || !ParseFloats(field[4], r.shift, 3) || !ParseFloats(field[5], r.origin, 3)) continue;
        r.yaw = static_cast<float>(atof(field[3]));
        if (k >= 7) strncpy_s(r.saved, sizeof(r.saved), field[6], _TRUNCATE);
        rows[n++] = r;
    }
    fclose(f);
    return n;
}
// the loaded stream unit of that name: P (current shift) and V (origin); false = not loaded
bool PosUnitFrame(const char *unit, float *shift, float *origin) {
    for (DWORD e = kStreamUnits; e < kStreamUnitsEnd; e += kStreamUnitSize) {
        DWORD state = 0, level = 0, terrain = 0, group = 0;
        char name[48];
        if (!ReadDword(e + 4, &state) || (state & 0xff) != 2 || !ReadString(e + 0xc, name, sizeof(name))) continue;
        if (_stricmp(name, unit)) continue;
        if (!ReadDword(e + 8, &level) || !level || !ReadFloats(level + 0x80, origin, 3)) return false;
        shift[0] = shift[1] = shift[2] = 0.0f;   // no TerrainGroup = no shift (0x5d318a: xorps)
        if (ReadDword(level, &terrain) && terrain && ReadDword(terrain + 0x10, &group) && group && !ReadFloats(group, shift, 3))
            return false;
        return DvFinite(shift, 3) && DvFinite(origin, 3);
    }
    return false;
}
// Lara's stream unit name (GameTracker +0xc0 id in the table), "" = none
void PosLaraUnit(char *o, size_t n) {
    o[0] = 0;
    DWORD cur = 0;
    if (!g_unitOk || !ReadDword(kUnitId, &cur)) return;
    for (DWORD e = kStreamUnits; e < kStreamUnitsEnd; e += kStreamUnitSize) {
        DWORD id = 0, state = 0;
        if (ReadDword(e, &id) && id == cur && ReadDword(e + 4, &state) && (state & 0xff) == 2) {
            if (!ReadString(e + 0xc, o, n)) o[0] = 0;
            return;
        }
    }
}
bool RunPosSave(const char *arg, char *o, size_t n) {
    if (!g_posOk) { Out(o, n, "disabled: pre-check failed (%s)", g_posWhy); return false; }
    char name[40];
    strncpy_s(name, sizeof(name), arg ? arg : "", _TRUNCATE);
    DvTrim(name);
    SYSTEMTIME t;
    GetLocalTime(&t);
    if (!name[0]) Out(name, sizeof(name), "pos%02d%02d%02d", t.wHour, t.wMinute, t.wSecond);
    for (char *c = name; *c; ++c)
        if (!(isalnum(static_cast<unsigned char>(*c)) || *c == '_' || *c == '-')) *c = '_';
    float p[3], r[3], shift[3], origin[3];
    DWORD inst = 0;
    char unit[48];
    if (!ReadLara(p, r, &inst)) { Out(o, n, "needs a level"); return false; }
    PosLaraUnit(unit, sizeof(unit));
    if (!unit[0] || !PosUnitFrame(unit, shift, origin)) { Out(o, n, "Lara's stream unit not found in the unit table"); return false; }
    char path[MAX_PATH];
    PosPath(path, sizeof(path));
    bool fresh = GetFileAttributesA(path) == INVALID_FILE_ATTRIBUTES;
    FILE *f = nullptr;
    if (fopen_s(&f, path, "a") || !f) { Out(o, n, "cannot write %s", path); return false; }
    if (fresh) fprintf(f, "# TruMenu positions (0.17 pos.save): name|unit|live x y z|yaw|unit shift P|unit origin V|saved"
                          " - pos.go converts with the unit's shift then and now (the unit must be loaded)\n");
    fprintf(f, "%s|%s|%.2f %.2f %.2f|%.5f|%.3f %.3f %.3f|%.3f %.3f %.3f|%04d-%02d-%02d %02d:%02d:%02d\n", name, unit, p[0],
            p[1], p[2], r[2], shift[0], shift[1], shift[2], origin[0], origin[1], origin[2], t.wYear, t.wMonth, t.wDay,
            t.wHour, t.wMinute, t.wSecond);
    fclose(f);
    Log(1, "pos.save %s: unit %s, live %.1f %.1f %.1f, yaw %.3f, shift P %.1f %.1f %.1f, origin V %.1f %.1f %.1f (src=%s)",
        name, unit, p[0], p[1], p[2], r[2], shift[0], shift[1], shift[2], origin[0], origin[1], origin[2],
        ShotSource("pos.save"));
    Out(o, n, "pos.save %s (%s %.0f %.0f %.0f)", name, unit, p[0], p[1], p[2]);
    return true;
}
void ValPosList(char *o, size_t n) {
    static PosRow rows[kPosMax];             // the list is read on the caller's thread; one caller at a time is enough
    int k = PosLoad(rows, kPosMax);
    size_t used = 0;
    o[0] = 0;
    LabelAdd(o, n, &used, "%d position(s)%s", k, k ? ":" : " (pos.save <name>)");
    for (int i = 0; i < k; ++i)
        LabelAdd(o, n, &used, " %s [%s] %.0f %.0f %.0f;", rows[i].name, rows[i].unit, rows[i].p[0], rows[i].p[1], rows[i].p[2]);
}
// game thread (queued): pos.go <name> | last
bool RunPosGo(const char *arg, char *o, size_t n) {
    if (!g_posOk) { Out(o, n, "disabled: pre-check failed (%s)", g_posWhy); return false; }
    DWORD player = 0;
    if (!NeedPlayer(&player, o, n)) return false;
    char name[40];
    strncpy_s(name, sizeof(name), arg ? arg : "", _TRUNCATE);
    DvTrim(name);
    if (!name[0]) { Out(o, n, "usage: pos.go <name>|last (pos.list)"); return false; }
    static PosRow rows[kPosMax];
    int k = PosLoad(rows, kPosMax), hit = -1;
    for (int i = 0; i < k; ++i)
        if (!_stricmp(rows[i].name, name)) hit = i;   // the newest of that name wins
    if (!_stricmp(name, "last") && k) hit = k - 1;
    if (hit < 0) { Out(o, n, "no position '%s' (%d in TruMenu.positions.txt)", name, k); return false; }
    const PosRow &r = rows[hit];
    float shift[3], origin[3];
    char lara[48];
    PosLaraUnit(lara, sizeof(lara));
    if (!PosUnitFrame(r.unit, shift, origin)) {
        float centre[3];
        if (RkLaraPortalTo(r.unit, centre)) {   // 0.21.1: behind a portal of Lara's own unit - the 0.20 portal path
            char steps[300], title[64];
            Out(steps, sizeof(steps), "cheat.flight 1;pos.portal %s;wait.unit %s;pos.go %s", r.unit, r.unit, r.name);
            Out(title, sizeof(title), "pos.go %s", r.name);
            Log(1, "pos.go %s: unit %s not loaded, a portal of Lara's unit %s leads there -> %s", r.name, r.unit,
                lara[0] ? lara : "-", steps);
            return ShortcutStart(steps, title, o, n);
        }
        Out(o, n, "refused: unit %s is not loaded (Lara is in %s) - pos.goload %s loads it and goes there (bar / menu: "
            "'laden + hin'; a level.load may change story state)", r.unit, lara[0] ? lara : "-", r.name);
        Log(1, "pos.go %s refused: unit %s not loaded (Lara in %s)", r.name, r.unit, lara[0] ? lara : "-");
        return false;
    }
    float target[3];
    for (int i = 0; i < 3; ++i) target[i] = r.p[i] - r.shift[i] + shift[i];
    if (!SetPosition(player, target)) { Out(o, n, "write failed"); return false; }
    SetYaw(player, r.yaw);
    Log(1, "pos.go %s: unit %s (Lara was in %s), saved %.1f %.1f %.1f with shift %.1f %.1f %.1f, shift now %.1f %.1f %.1f "
           "-> %.1f %.1f %.1f, yaw %.3f", r.name, r.unit, lara[0] ? lara : "-", r.p[0], r.p[1], r.p[2], r.shift[0], r.shift[1],
        r.shift[2], shift[0], shift[1], shift[2], target[0], target[1], target[2], r.yaw);
    Out(o, n, "pos.go %s: Lara at %.0f %.0f %.0f (%s)", r.name, target[0], target[1], target[2], r.unit);
    return true;
}
void ValPos(char *o, size_t n) {
    char unit[48];
    PosLaraUnit(unit, sizeof(unit));
    Out(o, n, "%s; Lara's unit %s", g_posOk ? "checks ok" : g_posWhy, unit[0] ? unit : "-");
}
// 0.18 pos.goload <name>|last (coordinator, live 2026-11-06: "pos.go glaskasten" from the prologue start was refused
// correctly, but Lukas did not know what to do): a shortcut through the 0.8.1 runner - when the unit is not loaded
// "level.load <unit>" first (the runner waits until no level change is pending, a player exists and GameTracker+0x38 is
// that unit, 2 s in a row, at most 120 s), then "cheat.flight 1" and "pos.go <name>" (the same conversion with the
// unit's shift). Explicit only (an item, a bar row with a second press, a menu button) - never automatic. A level.load
// starts the unit fresh: what that does to story values (stickies, chapter) is not known.
// 0.20 (Lukas, live 2026-11-06: a level.load for a unit right next door restarts it): when a loaded unit has a stream
// portal towards the target unit (portal +0 = the unit on the other side - docs\Befund-TruMenu-Trigger-0611.md, logs
// trg0611_portals_l3_main_bedroom.txt; the 0.14 dbg.portals read, g_dvPortalOk), the steps are "cheat.flight 1;
// pos.portal <unit>;wait.unit <unit>;pos.go <name>": Lara (flying) to the portal quad's centre, the runner waits until the
// stream unit table has the unit loaded (state 2) for 1 s (at most 30 s), then the usual pos.go. One hop only (a portal
// of a LOADED unit). Without such a portal - or with "pos.goload <name> load" - the 0.18 level.load path.
// the portal of a loaded unit (not the target itself) whose name is the target unit; its centre and the owner's name
bool PosPortalTo(const char *target, float *centre, char *from, size_t fromSize) {
    if (!g_dvPortalOk || !g_unitOk) return false;
    for (DWORD e = kStreamUnits; e < kStreamUnitsEnd; e += kStreamUnitSize) {
        DWORD state = 0, level = 0, terrain = 0, arr = 0;
        WORD count = 0;
        char unit[48];
        if (!ReadDword(e + 4, &state) || (state & 0xff) != 2 || !ReadString(e + 0xc, unit, sizeof(unit))) continue;
        if (!_stricmp(unit, target)) continue;
        if (!ReadDword(e + 8, &level) || !level || !ReadDword(level, &terrain) || !terrain ||
            !ReadWord(terrain + 2, &count) || count > 64 || !ReadDword(terrain + 4, &arr) || !arr)
            continue;
        for (DWORD i = 0; i < count; ++i) {
            const DWORD p = arr + i * 0x100;
            char name[48];
            float q[4][4];
            if (!ReadString(p, name, sizeof(name)) || _stricmp(name, target)) continue;
            if (!ReadFloats(p + 0xb0, &q[0][0], 16) || !DvFinite(&q[0][0], 16)) continue;
            for (int b = 0; b < 3; ++b) centre[b] = (q[0][b] + q[1][b] + q[2][b] + q[3][b]) * 0.25f;
            strncpy_s(from, fromSize, unit, _TRUNCATE);
            return true;
        }
    }
    return false;
}
bool PosUnitLoaded(const char *unit) {       // 0.20 wait.unit: the stream unit table has it, state 2
    float shift[3], origin[3];
    return unit && unit[0] && PosUnitFrame(unit, shift, origin);
}
// game thread (queued): pos.portal <unit>
bool RunPosPortal(const char *arg, char *o, size_t n) {
    if (!g_posOk || !g_dvPortalOk) {
        Out(o, n, "disabled: pre-check failed (%s)", !g_posOk ? g_posWhy : g_dvPortalWhy);
        return false;
    }
    DWORD player = 0;
    if (!NeedPlayer(&player, o, n)) return false;
    char unit[48], from[48];
    strncpy_s(unit, sizeof(unit), arg ? arg : "", _TRUNCATE);
    DvTrim(unit);
    if (!unit[0]) { Out(o, n, "usage: pos.portal <unit> (a stream portal of a loaded unit towards it)"); return false; }
    float centre[3];
    if (RkLaraPortalTo(unit, centre)) {      // 0.21.1: Lara's own unit first (only its portals switch her unit)
        PosLaraUnit(from, sizeof(from));
    } else if (!PosPortalTo(unit, centre, from, sizeof(from))) {
        Out(o, n, "no loaded unit has a stream portal towards %s", unit);
        return false;
    }
    if (!SetPosition(player, centre)) { Out(o, n, "write failed"); return false; }
    Log(1, "pos.portal %s: Lara to the portal of %s at %.1f %.1f %.1f (src=%s)", unit, from, centre[0], centre[1], centre[2],
        ShotSource("pos.portal"));
    Out(o, n, "pos.portal %s: Lara at the portal of %s (%.0f %.0f %.0f)", unit, from, centre[0], centre[1], centre[2]);
    return true;
}
bool RunPosGoLoad(const char *arg, char *o, size_t n) {
    if (!g_posOk) { Out(o, n, "disabled: pre-check failed (%s)", g_posWhy); return false; }
    char name[40];
    strncpy_s(name, sizeof(name), arg ? arg : "", _TRUNCATE);
    DvTrim(name);
    bool forceLoad = false;                  // 0.20: "<name> load" = the level.load path even with a portal
    if (char *sp = strchr(name, ' ')) {
        char *rest = sp + 1;
        while (*rest == ' ') ++rest;
        if (_stricmp(rest, "load")) { Out(o, n, "usage: pos.goload <name>|last [load]"); return false; }
        forceLoad = true;
        *sp = 0;
    }
    if (!name[0]) { Out(o, n, "usage: pos.goload <name>|last [load] (pos.list)"); return false; }
    static PosRow rows[kPosMax];
    int k = PosLoad(rows, kPosMax), hit = -1;
    for (int i = 0; i < k; ++i)
        if (!_stricmp(rows[i].name, name)) hit = i;
    if (!_stricmp(name, "last") && k) hit = k - 1;
    if (hit < 0) { Out(o, n, "no position '%s' (%d in TruMenu.positions.txt)", name, k); return false; }
    const PosRow &r = rows[hit];
    if (!InLevel()) { Out(o, n, "needs a level"); return false; }
    char why[200];
    if (LevelChangePending(why, sizeof(why))) { Out(o, n, "refused: level change pending (%s)", why); return false; }
    float shift[3], origin[3], centre[3];
    const bool loaded = PosUnitFrame(r.unit, shift, origin);
    char steps[300], title[64], from[48] = "", how[96];
    // 0.21.1: only a portal of Lara's own unit - from a neighbour's portal the engine never requests the target
    // (docs\Befund-Unit-Streaming-0611.md section 6: only the signals of Lara's unit count, wait.unit would time out)
    const bool portal = !loaded && !forceLoad && RkLaraPortalTo(r.unit, centre);
    if (portal) PosLaraUnit(from, sizeof(from));
    if (loaded) {
        Out(steps, sizeof(steps), "cheat.flight 1;pos.go %s", r.name);
        Out(how, sizeof(how), "loaded");
    } else if (portal) {
        Out(steps, sizeof(steps), "cheat.flight 1;pos.portal %s;wait.unit %s;pos.go %s", r.unit, r.unit, r.name);
        Out(how, sizeof(how), "not loaded - over the stream portal of %s", from);
    } else {
        Out(steps, sizeof(steps), "level.load %s;cheat.flight 1;pos.go %s", r.unit, r.name);
        Out(how, sizeof(how), "not loaded - %s", forceLoad ? "level.load asked for" : "no loaded unit has a portal to it");
    }
    Out(title, sizeof(title), "pos.goload %s", r.name);
    Log(1, "pos.goload %s: unit %s %s -> %s (src=%s)", r.name, r.unit, how, steps, ShotSource("pos.goload"));
    return ShortcutStart(steps, title, o, n);
}
// ---- 0.18 quick-toggle pages (render thread): the special rows of the pages Lara (saved positions), Checkpoints and
// Saves. Each row is a QbView (drawn by DrawQuick) plus a QbDyn (what left / right do). Rows of the last QbBuild.
enum QbDynKind { kQdNone = 0, kQdPos, kQdCpActive, kQdCpAll, kQdCp, kQdBackupNow, kQdRescan, kQdSave, kQdBackup, kQdLabel,
                 kQdItem, kQdPrepare, kQdStop, kQdTodo,     // 0.21.1: page 0 rows, page Tests rows
                 kQdSwGroup, kQdSw,                         // 0.21.5: page Fixes (group, switch)
                 kQdCosPick, kQdCosNext, kQdCosRec, kQdCosGroup, kQdCos,     // 0.21.6: page Kostueme
                 kQdChapGroup, kQdChap,                     // 0.21.7: page Kapitel (units per chapter)
                 kQdChapCp,                                 // 0.21.9: page Kapitel, a checkpoint of the open unit
                 kQdFigGroup };                             // 0.22.16: page Figur (switch group; 0.22.18: no planned row)
struct QbDyn { int kind; LONG intro; char arg[64], unit[48]; bool loaded; };
QbDyn g_qbDyn[kQbViewMax];
int g_qbDynN = 0;
// Lara page: the saved positions, newest first (the file read at most once a second)
int QbPosRows(QbView *v, QbDyn *d, int max, bool de) {
    static PosRow rows[kPosMax];
    static int count = 0;
    static DWORD readAt = 0;
    if (!readAt || GetTickCount() - readAt > 1000) { count = PosLoad(rows, kPosMax); readAt = GetTickCount(); }
    char lara[48];
    PosLaraUnit(lara, sizeof(lara));
    int n = 0;
    for (int i = count - 1; i >= 0 && n < max && n < 8; --i) {
        const PosRow &r = rows[i];
        float shift[3], origin[3];
        const bool loaded = PosUnitFrame(r.unit, shift, origin);
        QbView &w = v[n];
        QbDyn &q = d[n];
        ++n;
        q.kind = kQdPos;
        q.loaded = loaded;
        strncpy_s(q.arg, sizeof(q.arg), r.name, _TRUNCATE);
        strncpy_s(q.unit, sizeof(q.unit), r.unit, _TRUNCATE);
        const char *u = r.unit + (lara[0] ? DvCommonPrefix(r.unit, lara) : 0);
        Out(w.name, sizeof(w.name), "-> %s [%s]", r.name, u);
        char key[160];
        Out(key, sizeof(key), "pos.goload %s", r.name);
        const bool armed = QbArmed(key);
        Out(w.state, sizeof(w.state), "%s", loaded ? (de ? "rechts = hin" : "right = go")
                                         : armed ? (de ? "nochmal rechts!" : "right again!")
                                         : (de ? "laden + hin (2x)" : "load + go (2x)"));
        w.count[0] = 0;
        w.square = 0;
        w.skip = false;
        w.col = loaded ? IM_COL32(150, 240, 150, 255) : IM_COL32(190, 190, 190, 255);
        w.stateCol = armed ? IM_COL32(255, 110, 90, 255) : loaded ? IM_COL32(110, 230, 120, 255) : IM_COL32(235, 200, 120, 255);
    }
    return n;
}
// Checkpoints page: "to the active one", all markers on / off, the nearest 14 (left = marker on / off, right = go with
// a confirm - flight on + player.goto, two queued steps)
int QbCpPageRows(QbView *v, QbDyn *d, int max, bool de) {
    int total = 0;
    g_cpRowN = CpCollect(g_cpRows, kCpMax, true, &total);
    Out(g_qbHead, sizeof(g_qbHead), "%d %s%s%s", total, de ? "geladen" : "loaded", g_dvOn[kDvCheckpoints] ? ""
        : de ? " - Ebene Checkpoints ist aus" : " - layer Checkpoints is off", g_dvCpOk ? "" : " - checks failed");
    int n = 0;
    auto add = [&](int kind, const char *name, const char *state, ImU32 col, ImU32 stateCol, int square) -> QbDyn & {
        QbView &w = v[n];
        QbDyn &q = d[n];
        ++n;
        memset(&q, 0, sizeof(q));
        q.kind = kind;
        Out(w.name, sizeof(w.name), "%s", name);
        Out(w.state, sizeof(w.state), "%s", state);
        w.count[0] = 0;
        w.square = square;
        w.skip = false;
        w.col = col;
        w.stateCol = stateCol;
        return q;
    };
    if (max < 2) return 0;
    const bool armedActive = QbArmed("dbg.cpgo active");
    add(kQdCpActive, de ? "Zum aktiven Checkpoint" : "To the active checkpoint",
        armedActive ? (de ? "nochmal rechts!" : "right again!") : (de ? "rechts 2x = hin" : "right 2x = go"),
        IM_COL32(230, 255, 60, 255), armedActive ? IM_COL32(255, 110, 90, 255) : IM_COL32(235, 235, 235, 255), 0);
    char st[48];
    Out(st, sizeof(st), "< %d %s >", CpHiddenCount(), de ? "verborgen" : "hidden");
    add(kQdCpAll, de ? "Alle Marker aus / an" : "All markers off / on", st, kDvLayers[kDvCheckpoints].colour,
        IM_COL32(235, 235, 235, 255), 0);
    for (int i = 0; i < g_cpRowN && i < 14 && n < max; ++i) {
        const CpRow &r = g_cpRows[i];
        char text[128], key[48];
        CpRowText(r, de, text, sizeof(text));
        Out(key, sizeof(key), "dbg.cpgo %ld", r.intro);
        const bool armed = QbArmed(key), on = !r.hidden;
        ImU32 col = r.active ? IM_COL32(230, 255, 60, 255) : kDvLayers[kDvCheckpoints].colour;
        if (!on) col = (col & 0x00ffffffu) | (150u << 24);
        Out(st, sizeof(st), "%s  %s", on ? (de ? "an" : "on") : (de ? "aus" : "off"),
            armed ? (de ? "nochmal rechts!" : "right again!") : (de ? "rechts 2x = hin" : "right 2x = go"));
        QbDyn &q = add(kQdCp, text, st, col, armed ? IM_COL32(255, 110, 90, 255) : on ? IM_COL32(110, 230, 120, 255)
                                                                                     : IM_COL32(170, 170, 170, 255),
                       on ? 1 : 2);
        q.intro = r.intro;
        q.loaded = on;
    }
    return n;
}
// Saves page: backup now, re-read, the save files (newest first: right twice within 10 s = save.load), the backups
// (newest first: right twice within 10 s = save.restore - the 0.9 double confirmation)
void PlayTimeText(DWORD s, char *o, size_t n) { Out(o, n, "%lu:%02lu:%02lu", s / 3600, (s / 60) % 60, s % 60); }
int QbSavesRows(QbView *v, QbDyn *d, int max, bool de) {
    if (!g_qbSavesPageSeen) SaveScan(true);  // entering the page: a fresh scan (CRC over every file, render thread)
    g_qbSavesPageSeen = 2;
    static SaveInfo rows[kSaveMax];
    static SaveDir backups[kSaveBackupMax];
    EnterCriticalSection(&g_saveLock);
    int count = g_saveCount < 0 ? 0 : g_saveCount, nb = g_saveBackupCount;
    for (int i = 0; i < count; ++i) rows[i] = g_saves[i];
    for (int i = 0; i < nb; ++i) backups[i] = g_saveBackups[i];
    LeaveCriticalSection(&g_saveLock);
    int order[kSaveMax];                     // newest first (FILETIME as a 64-bit number - no new import)
    auto stamp = [&](int i) {
        return (static_cast<ULONGLONG>(rows[i].written.dwHighDateTime) << 32) | rows[i].written.dwLowDateTime;
    };
    for (int i = 0; i < count; ++i) {
        int at = i;
        while (at > 0 && stamp(order[at - 1]) < stamp(i)) { order[at] = order[at - 1]; --at; }
        order[at] = i;
    }
    char armedKey[200] = "";
    DWORD left = 0;
    SaveArmed(armedKey, sizeof(armedKey), &left);
    Out(g_qbHead, sizeof(g_qbHead), "%d %s, %d %s; %s", count, de ? "Spielst\303\244nde" : "saves", nb, de ? "Sicherungen" : "backups",
        !g_slDirect ? (de ? "Laden aus (DirectLoad=0)" : "load off (DirectLoad=0)")
        : !g_slOk ? (de ? "Laden: Pr\303\274fung fehlgeschlagen" : "load: checks failed")
        : g_slActive ? (de ? "ein Laden l\303\244uft" : "a load runs") : (de ? "rechts 2x = laden" : "right 2x = load"));
    int n = 0;
    auto add = [&](int kind, const char *name, const char *state, ImU32 col, ImU32 stateCol, bool skip) -> QbDyn & {
        QbView &w = v[n];
        QbDyn &q = d[n];
        ++n;
        memset(&q, 0, sizeof(q));
        q.kind = kind;
        Out(w.name, sizeof(w.name), "%s", name);
        Out(w.state, sizeof(w.state), "%s", state);
        w.count[0] = 0;
        w.square = 0;
        w.skip = skip;
        w.col = col;
        w.stateCol = stateCol;
        return q;
    };
    if (max < 4) return 0;
    add(kQdBackupNow, de ? "Jetzt sichern" : "Back up now", de ? "rechts" : "right", kQbPlayer, IM_COL32(235, 235, 235, 255), false);
    add(kQdRescan, de ? "Liste neu lesen" : "Re-read the list", de ? "rechts" : "right", kQbGrey, IM_COL32(235, 235, 235, 255), false);
    char label[64];
    Out(label, sizeof(label), "-- %s (%d)", de ? "Spielst\303\244nde" : "Saves", count);
    add(kQdLabel, label, "", kQbBlue, kQbBlue, true);
    for (int k = 0; k < count && k < 8 && n < max - 2; ++k) {
        const SaveInfo &s = rows[order[k]];
        char when[32], play[24], text[160], key[200];
        FileTimeText(s.written, when, sizeof(when));
        PlayTimeText(s.playTime, play, sizeof(play));
        if (s.formatOk) Out(text, sizeof(text), "%s | %s CP %lu | %s | %s", s.utf8, s.unit[0] ? s.unit : "?", s.checkpoint, play,
                            strlen(when) > 5 ? when + 5 : when);   // "MM-DD hh:mm:ss"
        else Out(text, sizeof(text), "%s | %s", s.utf8, s.problem);
        Out(key, sizeof(key), "save.load %s", s.utf8);
        const bool armed = !strcmp(armedKey, key);
        const bool can = s.formatOk && g_slDirect && g_slOk;
        QbDyn &q = add(kQdSave, text, armed ? (de ? "nochmal rechts!" : "right again!") : can ? (de ? "laden (2x)" : "load (2x)") : "-",
                       s.formatOk ? IM_COL32(235, 235, 235, 255) : IM_COL32(255, 140, 120, 255),
                       armed ? IM_COL32(255, 110, 90, 255) : can ? IM_COL32(235, 200, 120, 255) : IM_COL32(150, 150, 150, 255), false);
        strncpy_s(q.arg, sizeof(q.arg), s.utf8, _TRUNCATE);
        q.loaded = can;
    }
    Out(label, sizeof(label), "-- %s (%d)", de ? "Sicherungen" : "Backups", nb);
    add(kQdLabel, label, "", kQbBlue, kQbBlue, true);
    for (int k = 0; k < nb && k < 6 && n < max; ++k) {
        char text[96], key[200];
        Out(text, sizeof(text), "%s (%d %s)", backups[k].name, backups[k].files, de ? "Dateien" : "files");
        Out(key, sizeof(key), "save.restore %s", backups[k].name);
        const bool armed = !strcmp(armedKey, key);
        QbDyn &q = add(kQdBackup, text, armed ? (de ? "nochmal rechts!" : "right again!") : (de ? "zur\303\274ckspielen (2x)" : "restore (2x)"),
                       IM_COL32(200, 200, 200, 255), armed ? IM_COL32(255, 110, 90, 255) : IM_COL32(235, 200, 120, 255), false);
        strncpy_s(q.arg, sizeof(q.arg), backups[k].name, _TRUNCATE);
    }
    return n;
}
// 0.21.1 page 0 "Favoriten / Zuletzt": the rows of this frame (bar rows copied, or made from the item's type)
QbRow g_qbFavRow[kQbViewMax];
char g_qbFavText[kQbViewMax][3][112];        // 0.21.8: id, argument, label of a favourite without a static row
void QbSwView(int i, QbView &x, QbDyn &y, bool de);   // 0.21.8, section "0.21.5" page Fixes
void CosLabel(DWORD id, char *o, size_t n);            // 0.21.6, section "0.21.6 costumes"
void QbViewOf(int page, const QbRow &r, QbView &v, bool de);
const QbRow *QbFindRow(const char *id, const char *arg) {   // the first static bar row of this item + argument
    for (const QbPage &p : kQbPages)
        for (int i = 0; i < p.n; ++i) {
            const QbRow &r = p.rows[i];
            if (r.kind != kQbLabel && r.kind != kQbPlanned && r.kind != kQbGroup && !_stricmp(r.id, id) && !strcmp(r.arg, arg))
                return &r;
        }
    if (!_stricmp(kQbCosNext.id, id) && !strcmp(kQbCosNext.arg, arg)) return &kQbCosNext;   // 0.21.6 page Kostueme
    return nullptr;
}
void QbDynLabel(QbView *v, QbDyn *d, const char *text) {
    memset(v, 0, sizeof(*v));
    Out(v->name, sizeof(v->name), "-- %s", text);
    v->col = kQbBlue;
    v->stateCol = IM_COL32(125, 125, 125, 255);
    v->skip = true;
    v->src = -1;
    memset(d, 0, sizeof(*d));
    d->kind = kQdLabel;
}
int QbFavRows(QbView *v, QbDyn *d, int max, bool de) {
    int n = 0, rows = 0;
    auto add = [&](const QbRow &r) {
        if (n >= max || rows >= kQbViewMax) return;
        g_qbFavRow[rows] = r;
        QbViewOf(0, g_qbFavRow[rows], v[n], de);
        memset(&d[n], 0, sizeof(d[n]));
        d[n].kind = kQdItem;
        d[n].intro = rows++;
        ++n;
    };
    if (n < max) QbDynLabel(&v[n], &d[n], de ? "Favoriten (Y = anheften / l\303\266sen, hier und im Men\303\274)"   // 0.21.3: Y in
                                             : "Favourites (Y = pin / unpin, here and in the menu)"), ++n;   // the bar too
    int favs = 0;
    bool swRefreshed = false;
    ForFavEntries([&](const char *id, const char *arg) {   // 0.21.8: entries with an argument too
        ++favs;
        if (arg[0] && !_stricmp(id, "sw.set") && n < max) {   // a switch of page Fixes: its own row (value, keys)
            if (!swRefreshed) { SwRefresh(); swRefreshed = true; }
            EnterCriticalSection(&g_swLock);
            const int i = SwFindLocked(arg);
            if (i >= 0) QbSwView(i, v[n], d[n], de);
            LeaveCriticalSection(&g_swLock);
            if (i >= 0) { ++n; return; }
        }
        const QbRow *found = QbFindRow(id, arg);
        if (found) { add(*found); return; }
        if (rows >= kQbViewMax) return;
        const Item *item = FindItem(id);
        const char *type = item ? item->type : "action";
        char (&t)[3][112] = g_qbFavText[rows];
        strncpy_s(t[0], sizeof(t[0]), id, _TRUNCATE);
        strncpy_s(t[1], sizeof(t[1]), arg, _TRUNCATE);
        int kind = !strcmp(type, "bool") ? kQbBool : !strcmp(type, "info") ? kQbInfo : kQbAction, flags = 0;
        ImU32 colour = kQbWhite;
        if (!arg[0]) {
            Out(t[2], sizeof(t[2]), "%s", id);
        } else if (!_stricmp(id, "costume.set") && arg[0] >= '0' && arg[0] <= '9') {   // a costume row: its label
            char lab[100];
            CosLabel(static_cast<DWORD>(atoi(arg)), lab, sizeof(lab));
            Out(t[2], sizeof(t[2]), "%s %s", de ? "Kost\303\274m" : "Costume", lab);
            kind = kQbAction;
            colour = kQbPlayer;
        } else if (!_stricmp(id, "level.load")) {   // a chapter unit: the chapter rows' confirmation + backup
            Out(t[2], sizeof(t[2]), "%s %s", de ? "Laden" : "Load", arg);
            kind = kQbAction;
            flags = kQfConfirm | kQfBackup;
            colour = kQbChapter;
        } else {
            Out(t[2], sizeof(t[2]), "%s %s", id, arg);
            kind = kQbAction;
            char line[200];
            Out(line, sizeof(line), "%s %s", id, arg);
            if (CmdDangerOf(line)) flags = kQfConfirm;   // the bar's right-twice for kCmdDanger lines
        }
        QbRow r = {t[2], t[2], t[0], t[1], kind, -1, kQcNone, 0, colour, flags};
        add(r);
    });
    if (!favs && n < max) {
        memset(&v[n], 0, sizeof(v[n]));
        Out(v[n].name, sizeof(v[n].name), "   %s", de ? "(keine)" : "(none)");
        v[n].col = IM_COL32(150, 150, 150, 255);
        v[n].skip = true;
        v[n].src = -1;
        memset(&d[n], 0, sizeof(d[n]));
        d[n].kind = kQdLabel;
        ++n;
    }
    if (g_qbRecentMax <= 0) return n;
    if (n < max) QbDynLabel(&v[n], &d[n], de ? "Zuletzt" : "Recent"), ++n;
    for (int i = 0; i < g_qbRecentN; ++i) {
        if (FavHasArg(g_qbRecent[i].id, g_qbRecent[i].arg)) continue;   // a favourite is not shown twice (0.21.8: + arg)
        const QbRow *found = QbFindRow(g_qbRecent[i].id, g_qbRecent[i].arg);
        if (found) add(*found);
    }
    return n;
}
// 0.21.1 page Tests: the Prepare shortcuts of both regression lists (one row per distinct shortcut, as the ring's Tests /
// Prepare), Stop while one runs, then the TO TEST rows
int QbTestsRows(QbView *v, QbDyn *d, int max, bool de) {
    static TestRow rows[kRegLists + 1][kTestMax];
    static char cuts[kRegLists][kTestMax][kShortcutLen];
    int count[kRegLists + 1];
    EnterCriticalSection(&g_testLock);
    for (int l = 0; l < kRegLists; ++l) {
        count[l] = g_regCount[l];
        memcpy(rows[l], g_reg[l], sizeof(TestRow) * static_cast<size_t>(count[l]));
        memcpy(cuts[l], g_regShortcut[l], kShortcutLen * static_cast<size_t>(count[l]));
    }
    count[2] = g_testCount;
    memcpy(rows[2], g_tests, sizeof(TestRow) * static_cast<size_t>(count[2]));
    LeaveCriticalSection(&g_testLock);
    int n = 0;
    if (n < max) QbDynLabel(&v[n], &d[n], de ? "Vorbereiten (rechts 2x)" : "Prepare (right 2x)"), ++n;
    for (int l = 0; l < kRegLists; ++l)
        for (int i = 0; i < count[l] && n < max; ++i) {
            if (!cuts[l][i][0]) continue;
            bool dup = false;
            for (int j = 0; j < i && !dup; ++j) dup = !strcmp(cuts[l][j], cuts[l][i]);
            if (dup) continue;
            char title[96] = "", steps[kScMaxSteps][kScStepLen], o[80];
            int c = 0;
            ShortcutParse(cuts[l][i], title, sizeof(title), steps, &c, o, sizeof(o));
            QbView &w = v[n];
            QbDyn &q = d[n];
            memset(&w, 0, sizeof(w));
            memset(&q, 0, sizeof(q));
            w.src = -1;
            Out(w.name, sizeof(w.name), "%s", title[0] ? title : rows[l][i].id);
            Out(q.arg, sizeof(q.arg), "%s:%s", kRegNames[l], rows[l][i].id);
            char key[160];
            Out(key, sizeof(key), "prepare %s", q.arg);
            const bool armed = QbArmed(key);
            Out(w.state, sizeof(w.state), "%s", armed ? (de ? "nochmal rechts!" : "right again!") : (de ? "rechts 2x" : "right 2x"));
            w.col = kQbClaude;
            w.stateCol = armed ? IM_COL32(255, 110, 90, 255) : IM_COL32(235, 235, 235, 255);
            q.kind = kQdPrepare;
            ++n;
        }
    if (g_scActive && n < max) {
        QbView &w = v[n];
        QbDyn &q = d[n];
        memset(&w, 0, sizeof(w));
        memset(&q, 0, sizeof(q));
        w.src = -1;
        Out(w.name, sizeof(w.name), "%s", de ? "Vorbereiten stoppen" : "Stop the prepare");
        Out(w.state, sizeof(w.state), "%s", de ? "rechts" : "right");
        w.col = kQbRed;
        w.stateCol = IM_COL32(235, 235, 235, 255);
        q.kind = kQdStop;
        ++n;
    }
    if (n < max) QbDynLabel(&v[n], &d[n], de ? "TO TEST (rechts = OK / erledigt / an, links = Fehler / offen / aus)"
                                            : "TO TEST (right = ok / done / on, left = fail / open / off)"), ++n;
    for (int i = 0; i < count[2] && n < max; ++i) {
        const TestRow &t = rows[2][i];
        QbView &w = v[n];
        QbDyn &q = d[n];
        memset(&w, 0, sizeof(w));
        memset(&q, 0, sizeof(q));
        w.src = -1;
        char hint[72];
        strncpy_s(hint, sizeof(hint), t.hint, _TRUNCATE);
        Out(w.name, sizeof(w.name), "%s: %s", t.id, hint);
        const bool toggle = !strcmp(t.kind, "toggle"), step = !strcmp(t.kind, "step");
        const char *st = t.state;
        Out(w.state, sizeof(w.state), "%s", !strcmp(st, "ok") ? "OK" : !strcmp(st, "fail") ? (de ? "Fehler" : "fail")
                                            : !strcmp(st, "skip") ? (de ? "\303\274bersprungen" : "skipped")
                                            : !strcmp(st, "done") ? (de ? "erledigt" : "done")
                                            : !strcmp(st, "on") ? (de ? "an" : "on") : !strcmp(st, "off") ? (de ? "aus" : "off")
                                            : (de ? "offen" : "open"));
        w.col = toggle ? kQbAi : step ? kQbPlayer : kQbWhite;
        w.stateCol = !strcmp(st, "ok") || !strcmp(st, "done") || !strcmp(st, "on") ? IM_COL32(110, 230, 120, 255)
                   : !strcmp(st, "fail") ? IM_COL32(255, 110, 90, 255) : IM_COL32(200, 200, 200, 255);
        q.kind = kQdTodo;
        strncpy_s(q.arg, sizeof(q.arg), t.id, _TRUNCATE);
        strncpy_s(q.unit, sizeof(q.unit), t.kind, _TRUNCATE);
        ++n;
    }
    return n;
}
// 0.21.5 page Fixes (section "0.21.5 Fixes"): the groups of TruMenu.switches.txt as group rows ("[+]" / "[-]", one open
// at a time - right / X opens it and closes the others, left closes it; kept until the game ends, the file's "open" mark
// is the start state), the open group's switches below it: name, value ("an" / "aus", "< 3 >", "< es >"), count column
// "live" / "Neustart"; a key missing in the INI shows the default in brackets, a plugin without INI "keine INI"
void QbSwView(int i, QbView &x, QbDyn &y, bool de);   // 0.21.8, below
int QbSwRows(QbView *v, QbDyn *d, int max, bool de) {
    SwRefresh();
    EnterCriticalSection(&g_swLock);
    int n = 0, first = 0, live = 0;
    for (int i = 0; i < g_swN; ++i) live += g_sw[i].when != kSwRestart;
    Out(g_qbHead, sizeof(g_qbHead), de ? "%d Schalter (%d live), Plugin-INIs neben tru.exe" : "%d switches (%d live), plugin "
        "INIs next to tru.exe", g_swN, live);
    if (!g_swN) Out(g_qbHead, sizeof(g_qbHead), "TruMenu.switches.txt: %s", g_swState);
    for (int g = 0; g < g_swGroupN && n < max; first += g_swGroup[g].count, ++g) {
        const SwGroup &grp = g_swGroup[g];
        QbView &w = v[n];
        QbDyn &q = d[n];
        memset(&w, 0, sizeof(w));
        memset(&q, 0, sizeof(q));
        w.src = -1;
        Out(w.name, sizeof(w.name), "%s %s", grp.open ? "[-]" : "[+]", de ? grp.de : grp.en);
        if (grp.open) Out(w.state, sizeof(w.state), "%s", de ? "links = zu" : "left = close");
        else Out(w.state, sizeof(w.state), de ? "%d Zeilen - rechts = auf" : "%d rows - right = open", grp.count);
        w.col = kQbBlue;
        w.stateCol = IM_COL32(170, 170, 170, 255);
        q.kind = kQdSwGroup;
        q.intro = g;
        ++n;
        if (!grp.open) continue;
        for (int i = first; i < first + grp.count && i < g_swN && n < max; ++i) {
            QbSwView(i, v[n], d[n], de);
            ++n;
        }
    }
    LeaveCriticalSection(&g_swLock);
    return n;
}
// one switch row (g_swLock held; page Fixes and - 0.21.8 - a pinned switch on page 0, "sw.set|<switch>")
void QbSwView(int i, QbView &x, QbDyn &y, bool de) {
    const SwRow &r = g_sw[i];
    const SwValue &val = g_swVal[i];
    memset(&x, 0, sizeof(x));
    memset(&y, 0, sizeof(y));
    x.src = -1;
    Out(x.name, sizeof(x.name), "  %s", de ? r.de : r.en);
    const char *cur = SwEffective(r, val);
    char text[40];
    if (r.type == kSwBool) Out(text, sizeof(text), "%s", atoi(cur) ? (de ? "an" : "on") : (de ? "aus" : "off"));
    else Out(text, sizeof(text), "< %s >", cur);
    if (val.state == 2) Out(x.state, sizeof(x.state), "%s", de ? "keine INI" : "no INI");
    else if (val.state == 1) Out(x.state, sizeof(x.state), "(%s)", text);
    else Out(x.state, sizeof(x.state), "%s", text);
    Out(x.count, sizeof(x.count), "%s", r.when == kSwRestart ? (de ? "Neustart" : "restart") : "live");
    if (r.type == kSwBool && val.state != 2) x.square = atoi(cur) ? 1 : 2;
    x.col = r.when == kSwRestart ? kQbGrey : kQbMarkup;
    x.stateCol = val.state == 2 ? IM_COL32(125, 125, 125, 255) : val.state == 1 ? IM_COL32(255, 190, 90, 255)
               : r.type == kSwBool && atoi(cur) ? IM_COL32(110, 230, 120, 255) : IM_COL32(220, 220, 220, 255);
    y.kind = kQdSw;
    y.intro = i;
}
// page Fixes: right / left / X on a group or a switch row (dir kQbXDir = X)
void QbSwAct(const QbDyn &q, int dir) {
    const bool de = g_qbLang == 0;
    EnterCriticalSection(&g_swLock);
    const int i = static_cast<int>(q.intro);
    if (q.kind == kQdSwGroup) {
        if (i < 0 || i >= g_swGroupN) { LeaveCriticalSection(&g_swLock); return; }
        SwGroup &grp = g_swGroup[i];
        const bool open = dir == kQbXDir ? !grp.open : dir > 0;
        if (open == grp.open) {
            QbResult(false, "%s: %s", de ? grp.de : grp.en, open ? (de ? "schon auf" : "already open")
                                                             : (de ? "schon zu" : "already closed"));
        } else {
            for (int g = 0; g < g_swGroupN; ++g) g_swGroup[g].open = false;   // one group open at a time
            grp.open = open;
            QbResult(false, "%s: %s", de ? grp.de : grp.en, open ? (de ? "auf" : "open") : (de ? "zu" : "closed"));
        }
        LeaveCriticalSection(&g_swLock);
        return;
    }
    if (i < 0 || i >= g_swN) { LeaveCriticalSection(&g_swLock); return; }
    const SwRow r = g_sw[i];
    const SwValue val = g_swVal[i];
    LeaveCriticalSection(&g_swLock);
    const char *name = de ? r.de : r.en;
    if (val.state == 2) {
        QbResult(true, de ? "%s: %s.ini fehlt (nicht installiert) - nichts geschrieben" : "%s: %s.ini missing (not "
                 "installed) - nothing written", name, r.plugin);
        return;
    }
    char next[32], arg[160];
    if (!SwNext(r, SwEffective(r, val), dir, next, sizeof(next))) {
        QbResult(false, "%s: %s", name, r.type == kSwBool ? (atoi(SwEffective(r, val)) ? (de ? "schon an" : "already on")
                                                                                       : (de ? "schon aus" : "already off"))
                                                          : (de ? "Ende" : "end"));
        return;
    }
    Out(arg, sizeof(arg), "%s %s", r.target + 4, next);
    QbRun("Fixes", r.de, name, "sw.set", arg);
}
// ---- 0.22.16 page Figur (plan section 4, TODO N17; owner 2026-11-10: shadow power as a group at the figure, no tab of
// its own, the doppelganger rows greyed): after the saved positions two groups of page Fixes' switches - the same rows
// (QbSwView / QbSwAct, kQdSw: one state, two places, favourites "sw.set|<switch>" as on Fixes). Greyed (colour, count
// column "Lara") while the doppelganger is not played - the flag of TruDlc2Player (TruDlc2PlayerDoppelganger, the
// fight.trace column pc_doppelganger); the rows stay switchable (the INI is read for the next doppelganger part, live
// switches act at once). Group state = [Quick] Closed keys fig_shadow (open at the start) / fig_combat (closed).
struct QbFigSw { const char *plugin, *section, *key; };
const QbFigSw kQbFigShadow[] = {
    {"TruShadowPower", "ShadowPower", "Enabled"}, {"TruShadowPower", "Look", "Enabled"},
    {"TruShadowPower", "Look", "ScreenEffect"}, {"TruShadowPower", "Meter", "HudBar"},
    {"TruShadowPower", "Adrenaline", "Translate"}, {"TruShadowPower", "Reticle", "TranslateRequest"},
    {"TruShadowPower", "TimeScale", "TranslateSlot6"}, {"TruShadowPower", "ShadowPower", "Buttons"},
    {"TruShadowPower", "Meter", "Infinite"},   // 0.22.18: TruShadowPower 0.23 live switch (was the planned row, N2)
};
const QbFigSw kQbFigCombat[] = {
    {"TruShadowCombat", "Strike", "Translate"}, {"TruShadowCombat", "Strike", "Gate"},
    {"TruShadowCombat", "Damage", "Translate"}, {"TruShadowCombat", "Hit", "Translate"},
    {"TruShadowCombat", "Melee", "Translate"}, {"TruShadowCombat", "Companion", "Translate"},
};
void FtLookPlugins();                        // section "0.22.11 fight.trace" (game thread, once)
int QbFigDoppel() {                          // 1 doppelganger, 0 Lara, -1 unknown (TruDlc2Player missing / not looked up)
    if (!g_ftMeterLooked || !g_ftDg) return -1;
    int v = 0;
    __try {
        v = g_ftDg();
    } __except (EXCEPTION_EXECUTE_HANDLER) {
        return -1;
    }
    return v ? 1 : 0;
}
int QbFigRows(QbView *v, QbDyn *d, int max, bool de) {
    int n = QbPosRows(v, d, max, de);
    SwRefresh();
    const int dg = QbFigDoppel();
    EnterCriticalSection(&g_swLock);
    for (int g = 0; g < 2 && n < max; ++g) {
        const char *key = g ? "fig_combat" : "fig_shadow";
        const bool closed = QbGroupClosed(key);
        QbView &w = v[n];
        QbDyn &q = d[n];
        memset(&w, 0, sizeof(w));
        memset(&q, 0, sizeof(q));
        w.src = -1;
        Out(w.name, sizeof(w.name), "%s %s", closed ? "[+]" : "[-]",
            g ? (de ? "Kampf (Doppelg\303\244ngerin)" : "Combat (doppelganger)")
              : (de ? "Schattenkraft (Doppelg\303\244ngerin)" : "Shadow power (doppelganger)"));
        Out(w.state, sizeof(w.state), "%s", dg == 1 ? (de ? "Doppelg\303\244ngerin aktiv" : "doppelganger active")
                                          : dg == 0 ? (de ? "grau: Lara spielt" : "grey: Lara is played")
                                                    : (de ? "Figur unbekannt" : "figure unknown"));
        w.col = kQbBlue;
        w.stateCol = dg == 1 ? IM_COL32(110, 230, 120, 255) : IM_COL32(170, 170, 170, 255);
        q.kind = kQdFigGroup;
        q.intro = g;
        ++n;
        if (closed) continue;
        const QbFigSw *list = g ? kQbFigCombat : kQbFigShadow;
        const int count = g ? static_cast<int>(sizeof(kQbFigCombat) / sizeof(kQbFigCombat[0]))
                            : static_cast<int>(sizeof(kQbFigShadow) / sizeof(kQbFigShadow[0]));
        for (int k = 0; k < count && n < max; ++k)
            for (int i = 0; i < g_swN; ++i) {
                if (_stricmp(g_sw[i].plugin, list[k].plugin) || _stricmp(g_sw[i].section, list[k].section) ||
                    _stricmp(g_sw[i].key, list[k].key))
                    continue;
                QbSwView(i, v[n], d[n], de);
                if (dg != 1) {               // N17: greyed while Lara is played (still switchable)
                    v[n].col = IM_COL32(130, 130, 130, 255);
                    Out(v[n].count, sizeof(v[n].count), "%s %s", g_sw[i].when == kSwRestart ? (de ? "Neustart" : "restart")
                                                                                            : "live", "(Lara)");
                }
                ++n;
                break;
            }
    }
    LeaveCriticalSection(&g_swLock);
    return n;
}
void QbFigAct(const QbDyn &q, int dir) {
    const bool de = g_qbLang == 0;
    const char *key = q.intro ? "fig_combat" : "fig_shadow";
    const bool closed = QbGroupClosed(key);
    const bool close = dir == kQbXDir ? !closed : dir < 0;
    if (close == closed) {
        QbResult(false, "%s", close ? (de ? "schon zu" : "already closed") : (de ? "schon auf" : "already open"));
        return;
    }
    QbGroupSet(key, close);
    Log(1, "quick: Figur / group %s %s ([Quick] Closed=%s)", key, close ? "closed" : "opened", g_qbClosed);
    QbResult(false, "%s", close ? (de ? "zu" : "closed") : (de ? "auf" : "open"));
}
void QbActRow(int page, const QbRow &r, int dir);
// ---- 0.21.6 costumes (quick bar page Kostueme) ----
// Owner 2026-11-07: "Kostuem-Wechsel in der Leiste waere auch gut", then: a list or one row switched with left / right -
// both. Own page after Lara: with the list open it has 4 + N rows (N = the outfit cycle list, about 36); on the Lara page
// that would be 15 static rows + 8 positions + 4 + N, more than kQbViewMax (64). Every row is built from the data of the
// long menu sections "Outfits (live switch)" (GlobalInfo [0xe7ee50]+4, costume.set / costume.next) and "Outfits (next
// level load)" (player records of the type table, costume.choosereload) and runs those items - no new write path:
//   Kostuem: < name >       left / right = previous / next entry of the cycle list (wraps at both ends); only the shown
//                           name changes - costume.set <id> runs once the choice stood still kCosSettleMs (QbCosTick:
//                           one switch, one "quick:" line); X = the shown entry now
//   Naechstes Kostuem       costume.next (the game's own cycle step 0x6f0a90 with altPlayerObjectID 0); the one costume
//                           row Y can pin as a favourite (an item without an argument)
//   Fuers naechste Laden    left / right = a player record (wraps), X arms, X / right within 3 s = costume.choosereload
//   + neu laden             <record index> (the unit is reloaded - the confirmation of the other reload rows)
//   [+] Alle Kostueme (N)   one group, closed at the start (right / X open, left / X close - as a Fixes group); one row
//                           per cycle entry, right / X = costume.set <id> at once
// The current costume [0xe7f1c8] is marked in every row. Labels: dlc_costume_<a..p> = "<slot> <the game's outfit text>
// (<object name>)"; every other costume (lara_*, dlc_doppel_costume_*, doppelganger_casual) only its object name - no
// text mapping is known for them. Rows are refused with the long menu's reason without a level / costume check /
// [Cheat] Experimental; Y on a costume row other than "Naechstes Kostuem" is refused (QbFavPin, as page Fixes).
const DWORD kCosSettleMs = 500;              // the choice row switches once its entry stood still this long
// the outfit texts of the DLC costume slots a .. p: PC locals id 83 + slot (B138 locals.bin_001), measured in
// work/rebuild/costumes_0311/logs/check_names.txt (docs/Befund-Kostueme-Port.md: Xbox index 61 + slot -> PC 83 .. 98; the
// Xbox packs have the same texts except slot o = "Extra Costume 15" in pack1 / pack2)
const char *const kCosSlotNames[16] = {"Classic Lara", "Blue Bikini", "Black and White Bikini", "Red Bikini",
                                       "Camo Bikini", "Casual Explorer", "Grey Jungle Shorts", "Legend Lara",
                                       "Bright Blue Bikini", "Gold Bikini", "Red Drysuit", "Fashion Winner",
                                       "People's Choice", "Grey Jungle Shorts", "Grey Jungle Shorts", "Blue Wetsuit"};
struct CosBar {
    WORD ids[128];                           // the outfit cycle list of this frame
    int n;                                   // its entries (-1 = no list)
    DWORD now;                               // current costume [0xe7f1c8]
    WORD pickId;                             // the entry the choice row shows while a switch waits
    DWORD pickTick;                          // when it was picked (left / right)
    bool pending;                            // a switch waits until the pick stood still kCosSettleMs
    bool listOpen;                           // group "Alle Kostueme" (closed at the start, kept until the game ends)
    int rec;                                 // the record the next-load row shows (index into g_cosRec, -1 = current)
};
CosBar g_cos = {{}, -1, 0, 0, 0, false, false, -1};   // render thread
struct CosRec { int index, id; char name[48]; };   // a player record of the type table with its object id
CosRec g_cosRec[64];
int g_cosRecN = 0;
void CosLabelOf(const char *obj, char *o, size_t n) {   // "<slot> <outfit text> (<object name>)" or the object name
    const size_t k = 12;                     // strlen("dlc_costume_")
    if (!_strnicmp(obj, "dlc_costume_", k) && obj[k] >= 'a' && obj[k] <= 'p' && !obj[k + 1])
        Out(o, n, "%c %s (%s)", obj[k], kCosSlotNames[obj[k] - 'a'], obj);
    else Out(o, n, "%s", obj);
}
void CosLabel(DWORD id, char *o, size_t n) {
    char name[64];
    if (!id) Out(o, n, "-");
    else if (ObjectName(static_cast<int>(id), name, sizeof(name))) CosLabelOf(name, o, n);
    else Out(o, n, "%lu ?", id);
}
// this frame's cycle list and current costume; the player records again only when the object name table or the type
// table moved (the long menu's rule: ObjectId walks ~1000 names)
void CosRefresh() {
    g_cos.n = GlobalCostumes(g_cos.ids, 128);
    g_cos.now = 0;
    ReadDword(kCostumeNow, &g_cos.now);
    static DWORD names = 1, types = 1;
    DWORD nm = 0;
    ReadDword(kObjNames, &nm);
    const DWORD tt = TypeTable();
    if (nm == names && tt == types) return;
    names = nm;
    types = tt;
    g_cosRecN = 0;
    char name[48];
    bool player = false;
    for (int i = 0; i < 64 && TypeRecord(i, name, sizeof(name), &player); ++i) {
        if (!player) continue;
        const int id = ObjectId(name);
        if (!id) continue;                   // not in the object list (the long menu greys it): not offered here
        CosRec &r = g_cosRec[g_cosRecN++];
        r.index = i;
        r.id = id;
        strncpy_s(r.name, sizeof(r.name), name, _TRUNCATE);
    }
}
int CosIndexOf(DWORD id) {
    for (int i = 0; i < g_cos.n; ++i)
        if (static_cast<DWORD>(g_cos.ids[i]) == id) return i;
    return -1;
}
// 0.21.7 (live 2026-11-07 21:14: a cycle-list entry was refused only when worn - "object 33 refused by the game's check
// 0x005c54e0 (no .drm?)"): the same check before a row is offered. kCostumeValid is game code (id within the object list
// and <name>.drm present through the game's file system - the check costume.set runs first), so CosValidTick calls it on
// the game thread (the pad hook's once-per-frame block, where queued items such as costume.set run) - only while page
// Kostueme was built in the last 2 s, only when the cycle list changed, never a write. The rows read the results.
const int kCosValidMax = 128;
CRITICAL_SECTION g_cosValidLock;             // g_cosValidIds / Ok / N (game thread writes, render thread reads)
WORD g_cosValidIds[kCosValidMax];
signed char g_cosValidOk[kCosValidMax];      // 1 = offered, 0 = refused by 0x5c54e0
int g_cosValidN = -1;                        // -1 = not checked yet
volatile LONG g_cosValidWant = 0;            // GetTickCount of the last QbCosRows (render thread)
LONG g_cosValidRuns = 0;
// one call of the game's check, an exception = refused
bool CosValidCall(WORD id) {
    __try {
        return reinterpret_cast<CostumeValidFn>(kCostumeValid)(static_cast<int>(id));
    } __except (EXCEPTION_EXECUTE_HANDLER) {
        return false;
    }
}
// game thread, once per game frame (cheap while page Kostueme is not shown: one read)
void CosValidTick() {
    const LONG want = g_cosValidWant;
    if (!want || GetTickCount() - static_cast<DWORD>(want) > 2000) return;
    if (!g_costumeOk || !g_experimental || !InLevel()) return;
    WORD ids[kCosValidMax];
    const int n = GlobalCostumes(ids, kCosValidMax);
    if (n <= 0) return;
    EnterCriticalSection(&g_cosValidLock);
    const bool same = n == g_cosValidN && !memcmp(ids, g_cosValidIds, sizeof(WORD) * static_cast<size_t>(n));
    LeaveCriticalSection(&g_cosValidLock);
    if (same) return;
    signed char ok[kCosValidMax];
    char refused[200] = "";
    size_t used = 0;
    int bad = 0;
    for (int i = 0; i < n; ++i) {
        ok[i] = CosValidCall(ids[i]) ? 1 : 0;
        if (!ok[i] && ++bad <= 12) LabelAdd(refused, sizeof(refused), &used, "%s%u", used ? " " : "", ids[i]);
    }
    EnterCriticalSection(&g_cosValidLock);
    memcpy(g_cosValidIds, ids, sizeof(WORD) * static_cast<size_t>(n));
    memcpy(g_cosValidOk, ok, static_cast<size_t>(n));
    g_cosValidN = n;
    LeaveCriticalSection(&g_cosValidLock);
    ++g_cosValidRuns;
    Log(1, "costumes: %d cycle-list entries checked with the game's check 0x%08lx, %d refused (no .drm?)%s%s", n,
        kCostumeValid, bad, bad ? ": " : "", refused);
}
// render thread: 1 offered, 0 refused by the game's check, -1 not checked (yet)
int CosOffered(WORD id) {
    int r = -1;
    EnterCriticalSection(&g_cosValidLock);
    for (int i = 0; i < g_cosValidN; ++i)
        if (g_cosValidIds[i] == id) { r = g_cosValidOk[i]; break; }
    LeaveCriticalSection(&g_cosValidLock);
    return r;
}
// left / right: the neighbour, wrapping at both ends; from outside the list (-1) right starts at the first entry, left
// at the last
int CosStep(int i, int dir, int n) {
    if (n <= 0) return -1;
    if (i < 0 || i >= n) return dir < 0 ? n - 1 : 0;
    return (i + (dir < 0 ? n - 1 : 1)) % n;
}
// the long menu's conditions (PageCostumeLive / PageOutfits, SwitchCostume / SetCostume), short for the count column
const char *CosWhy(bool live, bool de) {
    if (!g_experimental) return "Experimental=0";
    if (live ? !(g_switchOk && g_postOk) : !g_costumeOk) return de ? "Pr\303\274fung fehlgeschl." : "code check failed";
    if (!InLevel()) return de ? "braucht ein Level" : "needs a level";
    return "";
}
int CosRecShown() {                          // the record the next-load row shows: the picked one, else the current
    if (g_cosRecN <= 0) return -1;
    if (g_cos.rec >= 0 && g_cos.rec < g_cosRecN) return g_cos.rec;
    for (int i = 0; i < g_cosRecN; ++i)
        if (static_cast<DWORD>(g_cosRec[i].id) == g_cos.now) return i;
    return 0;
}
// the one place this page switches live: costume.set <object id> through QbRun (the item's own line + one "quick:"
// line); the costume already worn = nothing
void CosApply(WORD id) {
    const bool de = g_qbLang == 0;
    char label[112], arg[16];
    CosLabel(id, label, sizeof(label));
    if (static_cast<DWORD>(id) == g_cos.now) {
        QbResult(false, "%s: %s - %s", de ? "Kost\303\274m" : "Costume", label, de ? "schon an" : "already on");
        return;
    }
    Out(arg, sizeof(arg), "%u", static_cast<unsigned>(id));
    g_qbActRow = nullptr;                    // no static row: nothing for the recent list
    QbRun("Kost\303\274me", "Kost\303\274m", label, "costume.set", arg);
}
// every frame (Render, also while the bar is closed): the waiting switch of the choice row once it stood still
void QbCosTick() {
    if (!g_cos.pending || GetTickCount() - g_cos.pickTick < kCosSettleMs) return;
    g_cos.pending = false;
    const bool de = g_qbLang == 0;
    const char *why = CosWhy(true, de);
    if (why[0]) { QbResult(true, "%s: %s", de ? "Kost\303\274m" : "Costume", why); return; }
    g_cos.now = 0;
    ReadDword(kCostumeNow, &g_cos.now);
    CosApply(g_cos.pickId);
}
int QbCosRows(QbView *v, QbDyn *d, int max, bool de) {
    CosRefresh();
    const DWORD tick = GetTickCount();
    InterlockedExchange(&g_cosValidWant, static_cast<LONG>(tick ? tick : 1));   // 0.21.7: CosValidTick checks the list
    const char *whyLive = CosWhy(true, de), *whyRec = CosWhy(false, de);
    char cur[112];
    CosLabel(g_cos.now, cur, sizeof(cur));
    const int listN = g_cos.n < 0 ? 0 : g_cos.n;
    int refused = 0;
    for (int i = 0; i < listN; ++i) refused += CosOffered(g_cos.ids[i]) == 0;
    char refusedText[48] = "";
    if (refused) Out(refusedText, sizeof(refusedText), de ? ", %d vom Spiel abgelehnt" : ", %d refused by the game", refused);
    Out(g_qbHead, sizeof(g_qbHead), de ? "aktuell: %s - %d im Wechsel%s, %d Spieler-Records%s"
                                       : "current: %s - %d in the cycle%s, %d player records%s", cur, listN, refusedText,
        g_cosRecN, g_cos.listOpen && 4 + listN > max ? (de ? " (Liste gek\303\274rzt)" : " (list cut)") : "");
    const ImU32 grey = IM_COL32(130, 130, 130, 255), red = IM_COL32(220, 120, 100, 255), green = IM_COL32(110, 230, 120, 255),
                white = IM_COL32(235, 235, 235, 255), orange = IM_COL32(255, 190, 90, 255);
    int n = 0;
    auto add = [&](int kind, LONG intro) -> QbView & {
        QbView &w = v[n];
        QbDyn &q = d[n];
        ++n;
        memset(&w, 0, sizeof(w));
        memset(&q, 0, sizeof(q));
        w.src = -1;
        q.kind = kind;
        q.intro = intro;
        return w;
    };
    char lab[112];
    if (n < max) {                           // Kostuem: < name >
        QbView &w = add(kQdCosPick, 0);
        CosLabel(g_cos.pending ? g_cos.pickId : g_cos.now, lab, sizeof(lab));
        Out(w.name, sizeof(w.name), "%s", de ? "Kost\303\274m" : "Costume");
        Out(w.state, sizeof(w.state), "< %s >", lab);
        Out(w.count, sizeof(w.count), "%s", whyLive[0] ? whyLive : g_cos.pending ? (de ? "wechselt gleich" : "switching")
                                            : (de ? "aktuell" : "current"));
        w.col = whyLive[0] ? grey : kQbPlayer;
        w.stateCol = whyLive[0] ? red : g_cos.pending ? orange : green;
    }
    if (n < max) {                           // Naechstes Kostuem (the static row's view)
        QbView &w = add(kQdCosNext, 0);
        QbViewOf(g_qbPage, kQbCosNext, w, de);
    }
    if (n < max) {                           // Fuers naechste Laden + neu laden
        QbView &w = add(kQdCosRec, 0);
        const int k = CosRecShown();
        Out(w.name, sizeof(w.name), "%s", de ? "F\303\274rs n\303\244chste Laden + neu laden" : "For the next load + reload");
        char key[64] = "";
        if (k >= 0) {
            char l2[100];
            CosLabelOf(g_cosRec[k].name, l2, sizeof(l2));
            Out(lab, sizeof(lab), "%d %s", g_cosRec[k].index, l2);
            Out(key, sizeof(key), "costume.choosereload %d", g_cosRec[k].index);
        } else {
            Out(lab, sizeof(lab), "-");
        }
        CostumeState s;
        ReadCostumeState(&s);
        const bool armed = key[0] && QbArmed(key);
        const bool chosen = k >= 0 && g_cosRec[k].id == static_cast<int>(s.mode ? s.chosen2 : s.chosen0);
        Out(w.state, sizeof(w.state), "< %s >", lab);
        Out(w.count, sizeof(w.count), "%s", whyRec[0] ? whyRec : armed ? (de ? "X nochmal!" : "X again!")
                                            : chosen ? (de ? "gew\303\244hlt, X 2x" : "chosen, X 2x") : "X 2x");
        w.col = whyRec[0] ? grey : kQbRed;
        w.stateCol = whyRec[0] ? red : armed ? IM_COL32(255, 110, 90, 255) : white;
    }
    if (n < max) {                           // [+] Alle Kostueme (N)
        QbView &w = add(kQdCosGroup, 0);
        Out(w.name, sizeof(w.name), "%s %s (%d)", g_cos.listOpen ? "[-]" : "[+]", de ? "Alle Kost\303\274me" : "All costumes", listN);
        Out(w.state, sizeof(w.state), "%s", g_cos.listOpen ? (de ? "links = zu" : "left = close")
                                                           : (de ? "rechts = auf" : "right = open"));
        w.col = kQbBlue;
        w.stateCol = IM_COL32(170, 170, 170, 255);
    }
    for (int i = 0; g_cos.listOpen && i < listN && n < max; ++i) {
        const bool now = static_cast<DWORD>(g_cos.ids[i]) == g_cos.now;
        QbView &w = add(kQdCos, g_cos.ids[i]);
        CosLabel(g_cos.ids[i], lab, sizeof(lab));
        Out(w.name, sizeof(w.name), "  %s", lab);
        const bool off = !now && CosOffered(g_cos.ids[i]) == 0;   // 0.21.7: refused by the game's check 0x5c54e0
        Out(w.state, sizeof(w.state), "%s", whyLive[0] ? (de ? "gesperrt" : "n/a") : now ? (de ? "aktuell" : "current")
                                            : off ? (de ? "abgelehnt (keine .drm?)" : "refused (no .drm?)")
                                            : (de ? "rechts = an" : "right = wear"));
        w.square = now ? 1 : 0;
        w.col = whyLive[0] || off ? grey : now ? green : kQbPlayer;
        w.stateCol = whyLive[0] || off ? red : now ? green : white;
    }
    return n;
}
// page Kostueme: right / left / X (dir kQbXDir) on a costume row ("Naechstes Kostuem" goes through QbActRow / QbExecRow)
void QbCosAct(const QbDyn &q, int dir) {
    const bool de = g_qbLang == 0, x = dir == kQbXDir;
    const char *cos = de ? "Kost\303\274m" : "Costume";
    char lab[112];
    switch (q.kind) {
    case kQdCosPick: {
        const char *why = CosWhy(true, de);
        if (why[0]) { QbResult(true, "%s: %s", cos, why); return; }
        if (g_cos.n <= 0) {
            QbResult(true, "%s: %s", cos, de ? "keine Wechsel-Liste (GlobalInfo [0xe7ee50]+4)" : "no cycle list (GlobalInfo "
                     "[0xe7ee50]+4)");
            return;
        }
        const WORD shown = g_cos.pending ? g_cos.pickId : static_cast<WORD>(g_cos.now);
        if (x) {                             // X = the shown entry now (no wait)
            g_cos.pending = false;
            CosApply(shown);
            return;
        }
        int next = CosIndexOf(shown);         // 0.21.7: entries the game refuses (0x5c54e0) are passed over
        for (int k = 0; k < g_cos.n; ++k) {
            next = CosStep(next, dir, g_cos.n);
            if (CosOffered(g_cos.ids[next]) != 0) break;
        }
        if (CosOffered(g_cos.ids[next]) == 0) {
            QbResult(true, "%s: %s", cos, de ? "alle Eintr\303\244ge vom Spiel abgelehnt (0x5c54e0)" : "every entry refused by the "
                     "game (0x5c54e0)");
            return;
        }
        g_cos.pickId = g_cos.ids[next];      // only the shown name changes - QbCosTick switches after kCosSettleMs
        g_cos.pickTick = GetTickCount();
        g_cos.pending = true;
        CosLabel(g_cos.pickId, lab, sizeof(lab));
        QbResult(false, "%s: %s (%d/%d) - %s", cos, lab, next + 1, g_cos.n, de ? "wechselt nach 0,5 s Ruhe, X = sofort"
                                                                             : "switches after 0.5 s, X = now");
        return;
    }
    case kQdCosNext:
        QbActRow(g_qbPage, kQbCosNext, dir);
        return;
    case kQdCosRec: {
        const char *name = de ? "F\303\274rs n\303\244chste Laden" : "For the next load";
        const char *why = CosWhy(false, de);
        if (why[0]) { QbResult(true, "%s: %s", name, why); return; }
        const int k = CosRecShown();
        if (k < 0) {
            QbResult(true, "%s: %s", name, de ? "keine Spieler-Records im Objektverzeichnis" : "no player record in the "
                     "object list");
            return;
        }
        char key[64], arg[16];
        Out(arg, sizeof(arg), "%d", g_cosRec[k].index);
        Out(key, sizeof(key), "costume.choosereload %s", arg);
        if (!x && !(dir > 0 && QbArmed(key))) {   // left / right = another record (right while armed = the confirmation)
            g_cos.rec = CosStep(k, dir, g_cosRecN);
            CosLabelOf(g_cosRec[g_cos.rec].name, lab, sizeof(lab));
            QbResult(false, "%s: %d %s - %s", name, g_cosRec[g_cos.rec].index, lab, de ? "X 2x = w\303\244hlen + Unit neu laden"
                                                                                     : "X twice = choose + reload the unit");
            return;
        }
        CosLabelOf(g_cosRec[k].name, lab, sizeof(lab));
        if (!QbConfirm(key, name, de ? "l\303\244dt die Unit neu (Story-Werte?)" : "reloads the unit (story values?)")) return;
        g_qbActRow = nullptr;
        QbRun("Kost\303\274me", "F\303\274rs n\303\244chste Laden", lab, "costume.choosereload", arg);
        return;
    }
    case kQdCosGroup: {
        const bool open = x ? !g_cos.listOpen : dir > 0;
        const char *name = de ? "Alle Kost\303\274me" : "All costumes";
        if (open == g_cos.listOpen) {
            QbResult(false, "%s: %s", name, open ? (de ? "schon auf" : "already open") : (de ? "schon zu" : "already closed"));
            return;
        }
        g_cos.listOpen = open;
        QbResult(false, "%s: %s", name, open ? (de ? "auf" : "open") : (de ? "zu" : "closed"));
        return;
    }
    case kQdCos: {
        const char *why = CosWhy(true, de);
        if (why[0]) { QbResult(true, "%s: %s", cos, why); return; }
        if (dir < 0) { QbResult(false, "%s", de ? "rechts / X = dieses Kost\303\274m" : "right / X = wear this one"); return; }
        if (CosOffered(static_cast<WORD>(q.intro)) == 0) {   // 0.21.7: the game's check said no - nothing runs
            CosLabel(static_cast<DWORD>(q.intro), lab, sizeof(lab));
            QbResult(true, "%s: %s - %s", cos, lab, de ? "vom Spiel abgelehnt (Pr\303\274fung 0x5c54e0, keine .drm?)"
                                                       : "refused by the game's check 0x5c54e0 (no .drm?)");
            return;
        }
        g_cos.pending = false;               // an explicit pick replaces a waiting one
        CosApply(static_cast<WORD>(q.intro));
        return;
    }
    default: return;
    }
}
// the footer's first line while a row is selected and no answer is shown: the row's keys (static rows: QbRowHint)
bool ChapFootHint(const QbDyn &q, bool de, char *o, size_t n);   // 0.21.9, section "0.21.7 chapter units"
bool QbFootHint(int page, int sel, bool de, char *o, size_t n) {
    if (page < 0 || page >= kQbPageN || sel < 0 || sel >= g_qbViewN) return false;
    const QbPage &p = kQbPages[page];
    const int src = g_qbView[sel].src, k = sel - g_qbStaticN;
    if (src >= 0) return src < p.n && QbRowHint(p.rows[src], de, o, n);
    if (p.special == kQsFav) {
        const QbRow *r = QbSpecialRow(k);
        return r && QbRowHint(*r, de, o, n);
    }
    if (p.special == kQsChapters) return k >= 0 && k < g_qbDynN && ChapFootHint(g_qbDyn[k], de, o, n);   // 0.21.9
    if (p.special != kQsCostume || k < 0 || k >= g_qbDynN) return false;
    const char *t = nullptr;
    switch (g_qbDyn[k].kind) {
    case kQdCosPick: t = de ? "links / rechts: Kost\303\274m (wechselt nach 0,5 s Ruhe)   X: sofort"
                            : "left / right: costume (switches after 0.5 s)   X: now"; break;
    case kQdCosRec: t = de ? "links / rechts: Record   X 2x: w\303\244hlen + Unit neu laden"
                           : "left / right: record   X twice: choose + reload the unit"; break;
    case kQdCosGroup: t = de ? "rechts: auf   links: zu   X: auf / zu" : "right: open   left: close   X: open / close"; break;
    case kQdCos: t = de ? "rechts / X: dieses Kost\303\274m jetzt" : "right / X: wear this one now"; break;
    default: return false;
    }
    Out(o, n, "%s", t);
    return true;
}
