int g_chapCpOpen = -1;                       // 0.21.9: the kUnits index whose checkpoints are shown (-1 = none)
char g_chapCpArg[kQbViewMax][72];            // 0.21.9: the cp.jump arguments of this frame's checkpoint rows
const ChapOrder *ChapOrderOf(int unit) {
    if (unit < 0 || unit >= kUnitCount) return nullptr;
    for (const ChapOrder &c : kChapOrder)
        if (!_stricmp(c.unit, kUnits[unit].unit)) return &c;
    return nullptr;
}
int ChapCpCount(const ChapOrder *c) {
    int count = 0;
    for (const char *p = c ? c->cps : ""; *p; ++p)
        if (*p != ' ' && (p == c->cps || p[-1] == ' ')) ++count;
    return count;
}
// the units of group g in page order: kChapOrder first (play order), then the group's other units of kUnits
int ChapUnits(int g, int *out, int max) {
    const char *key = kChapGroups[g].key;
    int n = 0;
    for (const ChapOrder &c : kChapOrder) {
        const int i = strcmp(c.group, key) ? -1 : UnitIndexOf(c.unit);
        if (i >= 0 && !strcmp(kUnits[i].group, key) && n < max) out[n++] = i;
    }
    for (int i = 0; i < kUnitCount && n < max; ++i) {
        if (strcmp(kUnits[i].group, key)) continue;
        bool have = false;
        for (int j = 0; j < n && !have; ++j) have = out[j] == i;
        if (!have) out[n++] = i;
    }
    if (!strcmp(key, kUnitsNoDataGroup))     // 0.21.10: the unused-slot group also lists left / right (they stay in DLC 1)
        for (const char *u : kUnitsNoData) {
            const int i = UnitIndexOf(u);
            bool have = i < 0;
            for (int j = 0; j < n && !have; ++j) have = out[j] == i;
            if (!have && n < max) out[n++] = i;
        }
    return n;
}
// a DLC 2 unit that is not the DLC 2 start: a direct load may skip the doppelganger setup
bool ChapDlc2Note(int unit) {
    return unit >= 0 && unit < kUnitCount && !strcmp(kUnits[unit].group, "DLC 2") && _stricmp(kUnits[unit].unit, kChapDlc2Start);
}
int QbChapRows(QbView *v, QbDyn *d, int max, bool de) {
    char lara[48];
    PosLaraUnit(lara, sizeof(lara));
    int n = 0, rows = 0;
    for (int g = 0; g < kChapGroupN && n < max; ++g) {
        int order[kUnitCount];               // 0.21.9: play order for DLC 1 / DLC 2 (kChapOrder)
        const int count = ChapUnits(g, order, kUnitCount);
        const bool open = g_chapOpen == g;
        QbView &w = v[n];
        QbDyn &q = d[n];
        memset(&w, 0, sizeof(w));
        memset(&q, 0, sizeof(q));
        w.src = -1;
        Out(w.name, sizeof(w.name), "%s %s (%d)", open ? "[-]" : "[+]", de ? kChapGroups[g].de : kChapGroups[g].en, count);
        Out(w.state, sizeof(w.state), "%s", open ? (de ? "links = zu" : "left = close") : (de ? "rechts = auf" : "right = open"));
        if (!strcmp(kChapGroups[g].key, "DLC 2"))
            Out(w.count, sizeof(w.count), "%s", de ? "besser Start + laufen" : "better start + walk");
        else if (!strcmp(kChapGroups[g].key, kUnitsNoDataGroup))   // 0.21.10
            Out(w.count, sizeof(w.count), "%s", de ? "keine Daten (17p/17s)" : "no data (17p/17s)");
        w.col = kQbChapter;
        w.stateCol = IM_COL32(170, 170, 170, 255);
        q.kind = kQdChapGroup;
        q.intro = g;
        ++n;
        if (!open) continue;
        bool ringShown = false;
        for (int j = 0; j < count && n < max && rows < kQbViewMax; ++j) {
            const int i = order[j];
            const ChapOrder *co = ChapOrderOf(i);   // 0.21.9: ring mark, checkpoints
            if (co && co->ring && !ringShown) {  // 0.21.9: the loop's units under one heading
                QbDynLabel(&v[n], &d[n], de ? "Rundweg (Richtung nicht in den Daten)" : "Loop (direction not in the data)");
                ringShown = true;
                if (++n >= max) break;
            }
            QbRow &r = g_chapRow[rows];
            r = {kUnits[i].unit, kUnits[i].unit, "level.load", kUnits[i].unit, kQbAction, -1, kQcNone, 0, kQbChapter,
                 kQfConfirm | kQfBackup};
            QbView &x = v[n];
            QbDyn &y = d[n];
            memset(&x, 0, sizeof(x));
            memset(&y, 0, sizeof(y));
            x.src = -1;
            char key[160];
            Out(key, sizeof(key), "%d/%s %s", g_qbPage, r.id, r.arg);   // QbActRow's confirmation key
            const bool armed = QbArmed(key), note = ChapDlc2Note(i), here = lara[0] && !_stricmp(lara, kUnits[i].unit);
            const bool noDrm = UnitNoDrm(i);     // 0.21.9: grey, not loadable
            const bool unused = UnitUnused(i);   // 0.21.10: one of the six slots without data (17p / 17s)
            const int cps = ChapCpCount(co);
            const bool cpOpen = cps > 0 && g_chapCpOpen == i;
            char more[48] = "";
            if (cps) Out(more, sizeof(more), "  %s %d CP", cpOpen ? "[-]" : "[+]", cps);
            Out(x.name, sizeof(x.name), "  %s%s%s", kUnits[i].unit, co && co->ring ? (de ? " (Rundweg)" : " (loop)") : "", more);
            Out(x.state, sizeof(x.state), "%s", unused ? (de ? "ungenutzt" : "unused") : noDrm ? (de ? "keine .drm" : "no .drm")
                                                : armed ? (de ? "nochmal rechts!" : "right again!")
                                                : cps ? (de ? "rechts 2x, links: CP" : "right 2x, left: CP") : (de ? "rechts 2x" : "right 2x"));
            Out(x.count, sizeof(x.count), "%s", unused ? (de ? "keine Daten (17p/17s)" : "no data (17p/17s)")
                                                : here ? (de ? "Lara hier" : "Lara here") : noDrm ? (de ? "nicht ladbar" : "not loadable")
                                                : note ? (de ? "Doppel-Zustand?" : "doppel state?") : "");
            x.col = noDrm ? IM_COL32(130, 130, 130, 255) : here ? IM_COL32(150, 240, 150, 255) : kQbChapter;
            x.stateCol = noDrm ? IM_COL32(130, 130, 130, 255) : armed ? IM_COL32(255, 110, 90, 255) : note ? IM_COL32(255, 190, 90, 255)
                                                                                                       : IM_COL32(235, 235, 235, 255);
            y.kind = kQdChap;
            y.intro = rows++;
            y.loaded = note;
            strncpy_s(y.unit, sizeof(y.unit), kUnits[i].unit, _TRUNCATE);
            ++n;
            if (!cpOpen) continue;
            // 0.21.9: the open unit's checkpoints - cp.jump <unit> <intro> (backup, unit.go, wait.unit, dbg.cpgo), right 2x
            char ids[160];
            strncpy_s(ids, sizeof(ids), co->cps, _TRUNCATE);
            char *context = nullptr;
            for (char *id = strtok_s(ids, " ", &context); id && n < max && rows < kQbViewMax; id = strtok_s(nullptr, " ", &context)) {
                Out(g_chapCpArg[rows], sizeof(g_chapCpArg[rows]), "%s %s", kUnits[i].unit, id);
                QbRow &c = g_chapRow[rows];
                c = {kUnits[i].unit, kUnits[i].unit, "cp.jump", g_chapCpArg[rows], kQbAction, -1, kQcNone, 0, kQbChapter,
                     kQfConfirm};
                QbView &cx = v[n];
                QbDyn &cy = d[n];
                memset(&cx, 0, sizeof(cx));
                memset(&cy, 0, sizeof(cy));
                cx.src = -1;
                Out(key, sizeof(key), "%d/%s %s", g_qbPage, c.id, c.arg);
                const bool cpArmed = QbArmed(key);
                const bool ghoul = !_stricmp(kUnits[i].unit, "dlc_yggdrasil_end") && !strcmp(id, "9608");
                Out(cx.name, sizeof(cx.name), "      CP %s", id);
                Out(cx.state, sizeof(cx.state), "%s", cpArmed ? (de ? "nochmal rechts!" : "right again!") : (de ? "rechts 2x" : "right 2x"));
                Out(cx.count, sizeof(cx.count), "%s", ghoul ? (de ? "020_ghoul sofort" : "020_ghoul at once") : "");
                cx.col = kQbChapter;
                cx.stateCol = cpArmed ? IM_COL32(255, 110, 90, 255) : IM_COL32(235, 235, 235, 255);
                cy.kind = kQdChapCp;
                cy.intro = rows++;
                cy.loaded = note;
                strncpy_s(cy.unit, sizeof(cy.unit), kUnits[i].unit, _TRUNCATE);
                strncpy_s(cy.arg, sizeof(cy.arg), id, _TRUNCATE);
                ++n;
            }
        }
    }
    return n;
}
// 0.21.9: the footer's key line on page Kapitel (unit rows with checkpoints, checkpoint rows, units without a DRM)
bool ChapFootHint(const QbDyn &q, bool de, char *o, size_t n) {
    const int u = UnitIndexOf(q.unit);
    const char *t = nullptr;
    if (q.kind == kQdChapCp) t = de ? "rechts 2x: Sicherung, Unit, Flug + Checkpoint" : "right 2x: backup, unit, flight + checkpoint";
    else if (q.kind != kQdChap) return false;
    else if (UnitUnused(u)) t = de ? "ungenutzt - keine Daten (17p/17s), nicht ladbar" : "unused - no data (17p/17s), not loadable";
    else if (UnitNoDrm(u)) t = de ? "keine .drm in mods - nicht ladbar" : "no .drm in mods - not loadable";
    else if (ChapCpCount(ChapOrderOf(u))) t = de ? "rechts 2x: Sicherung + laden   links: Checkpoints auf / zu"
                                                 : "right 2x: backup + load   left: checkpoints open / close";
    else return false;
    Out(o, n, "%s", t);
    return true;
}
// page Kapitel: right / left / X (dir kQbXDir) on a group or a unit row
void QbChapAct(const QbDyn &q, int dir) {
    const bool de = g_qbLang == 0;
    if (q.kind == kQdChapGroup) {
        const int g = static_cast<int>(q.intro);
        if (g < 0 || g >= kChapGroupN) return;
        const char *name = de ? kChapGroups[g].de : kChapGroups[g].en;
        const bool open = dir == kQbXDir ? g_chapOpen != g : dir > 0;
        if (open == (g_chapOpen == g)) {
            QbResult(false, "%s: %s", name, open ? (de ? "schon auf" : "already open") : (de ? "schon zu" : "already closed"));
            return;
        }
        g_chapOpen = open ? g : -1;          // one group open at a time
        QbResult(false, "%s: %s", name, open ? (de ? "auf" : "open") : (de ? "zu" : "closed"));
        return;
    }
    const int k = static_cast<int>(q.intro);
    if (k < 0 || k >= kQbViewMax) return;
    const QbRow &r = g_chapRow[k];
    if (q.kind == kQdChap) {                 // 0.21.9: units without a DRM; left = the unit's checkpoints
        const int u = UnitIndexOf(q.unit);
        if (UnitUnused(u)) {                 // 0.21.10: the proven result + the engine's reaction (17s)
            QbResult(true, "%s: %s", q.unit, de ? "ungenutzt - in keinem Archiv und nicht in mods (17p/17s); Laden = "
                                                  "Fehlerfenster \"Can't open file\" + Spielende - nicht angeboten"
                                                : "unused - in no archive and not in mods (17p/17s); a load = error box "
                                                  "\"Can't open file\" + the game exits - not offered");
            return;
        }
        if (UnitNoDrm(u)) {
            QbResult(true, "%s: %s", q.unit, de ? "keine .drm in mods - nicht ladbar" : "no .drm in mods - not loadable");
            return;
        }
        if (dir == -1 && ChapCpCount(ChapOrderOf(u))) {
            const bool open = g_chapCpOpen != u;
            g_chapCpOpen = open ? u : -1;    // one unit's checkpoints at a time
            QbResult(false, "%s: %s", q.unit, open ? (de ? "Checkpoints auf (rechts 2x = hin)" : "checkpoints open (right 2x = go)")
                                                   : (de ? "Checkpoints zu" : "checkpoints closed"));
            return;
        }
    }
    char key[160];
    Out(key, sizeof(key), "%d/%s %s", g_qbPage, r.id, r.arg);
    const bool first = dir != -1 && !QbArmed(key);
    QbActRow(g_qbPage, r, dir == kQbXDir ? 1 : dir);   // the chapter rows' path: confirm, save.backup, level.load
    if (first && q.loaded)                   // DLC 2 unit: the note with the confirmation
        QbResult(true, "%s: %s", r.arg, de ? "Doppelg\303\244ngerin evtl. nicht aufgesetzt (besser DLC-2-Start + laufen) - "
                                             "rechts / X nochmal = laden" : "doppelganger state may be missing (better the "
                                             "DLC 2 start + walk) - right / X again = load");
}
// the help line of a unit row (0.21.9: also of a checkpoint row)
bool ChapHelp(const QbDyn &q, bool de, char *o, size_t n) {
    if (q.kind == kQdChapCp) {               // 0.21.9
        if (!_stricmp(q.unit, "dlc_yggdrasil_end") && !strcmp(q.arg, "9608"))
            Out(o, n, "%s", de ? "CP 9608 liegt wohl im Trigger 10026: 020_ghoul sofort" : "CP 9608 is likely inside trigger "
                                 "10026: 020_ghoul at once");
        else Out(o, n, "%s", de ? "Sicherung, dann in die Unit und zum Checkpoint (Flug an)" : "Backup, then into the unit "
                                  "and to the checkpoint (flight on)");
        return true;
    }
    if (UnitNameUnused(q.unit))              // 0.21.10 (17s): proven result + engine reaction, at most 60 characters each
        Out(o, n, "%s", de ? "In keinem Archiv (17s); Laden: Fehlerfenster + Spielende" : "In no archive (17s); a load: error "
                             "box + the game exits");
    else if (UnitNameNoDrm(q.unit))          // 0.21.9
        Out(o, n, "%s", de ? "Keine .drm in mods: nur in unitlist.txt, nicht ladbar" : "No .drm in mods: in unitlist.txt "
                             "only, not loadable");
    else if (q.loaded) Out(o, n, "%s", de ? "Direkt laden setzt die Doppelg\303\244ngerin evtl. nicht auf" : "A direct load may not set "
                                      "up the doppelganger state");
    else Out(o, n, "%s", de ? "Sicherung, dann diese Unit laden (debug, keine Story-Werte)" : "Backup, then load this unit "
                              "(debug, no story values)");
    return true;
}
// ---- end of 0.21.7 chapter units ----

// 0.21.8 favourites with an argument: the item + argument a special row stands for (page Fixes switch = sw.set <switch>,
// costume list row = costume.set <object id>, chapter unit = level.load <unit>); false = not pinnable (groups, choosers,
// positions / checkpoints / saves rows)
bool QbDynFav(int k, char *id, size_t idN, char *arg, size_t argN) {
    if (k < 0 || k >= g_qbDynN) return false;
    const QbDyn &q = g_qbDyn[k];
    if (q.kind == kQdSw) {
        bool ok = false;
        EnterCriticalSection(&g_swLock);
        const int i = static_cast<int>(q.intro);
        if (i >= 0 && i < g_swN) { Out(id, idN, "sw.set"); Out(arg, argN, "%s", g_sw[i].target + 4); ok = true; }
        LeaveCriticalSection(&g_swLock);
        return ok && FavArgOk(arg);
    }
    if (q.kind == kQdCos) {
        Out(id, idN, "costume.set");
        Out(arg, argN, "%ld", q.intro);
        return true;
    }
    if (q.kind == kQdChap && q.intro >= 0 && q.intro < kQbViewMax && !UnitNameNoDrm(q.unit)) {   // 0.21.9: not without a DRM
        Out(id, idN, "level.load");
        Out(arg, argN, "%s", g_chapRow[q.intro].arg);
        return FavArgOk(arg);
    }
    return false;
}
bool QbDynIsSw(int k) { return k >= 0 && k < g_qbDynN && g_qbDyn[k].kind == kQdSw; }

// ---- 0.21.7 help line / Y hint (TODO "kurze Hilfe-Zeile zum gewaehlten Punkt", "Y: -" on rows that refuse Y) ----
// the bar row behind the selected view: a static row, a favourite / recent row of page 0, "Naechstes Kostuem"; nullptr
// for every other special row (positions, checkpoints, saves, Tests, Fixes, costumes)
const QbRow *QbSelRow(int page, int sel) {
    if (page < 0 || page >= kQbPageN || sel < 0 || sel >= g_qbViewN) return nullptr;
    const QbPage &p = kQbPages[page];
    const int src = g_qbView[sel].src;
    if (src >= 0) return src < p.n ? &p.rows[src] : nullptr;
    return p.special ? QbSpecialRow(sel - g_qbStaticN) : nullptr;
}
// the selected row's help line (one language, kQbHelpMax characters): kQbHelp for item rows, the hint column of
// TruMenu.switches.txt on page Fixes, the costume rows' own lines (a refused entry says why); false = no help
bool QbHelpLine(int page, int sel, bool de, char *o, size_t n) {
    o[0] = 0;
    if (page < 0 || page >= kQbPageN || sel < 0 || sel >= g_qbViewN) return false;
    const QbRow *r = QbSelRow(page, sel);
    if (r) {
        if (!_stricmp(r->id, "power.infinite")) {   // 0.22.19: a greyed row says why (plugin / version / INI missing)
            const char *why = PiWhy();
            if (why[0]) { Out(o, n, "%s", why); return true; }
        }
        const char *t = QbHelpText(r->id, r->arg);
        if (!t) return false;
        QbHelpPart(t, de, o, n);
        return o[0] != 0;
    }
    const int k = sel - g_qbStaticN;
    if (k < 0 || k >= g_qbDynN) return false;
    const QbDyn &q = g_qbDyn[k];
    if (q.kind == kQdSw) {                   // page Fixes: "<DE> // <EN>" of the file
        EnterCriticalSection(&g_swLock);
        const int i = static_cast<int>(q.intro);
        if (i >= 0 && i < g_swN) Out(o, n, "%s", de ? g_sw[i].hint : g_sw[i].hintEn);
        LeaveCriticalSection(&g_swLock);
        return o[0] != 0;
    }
    if (q.kind == kQdChap || q.kind == kQdChapCp) return ChapHelp(q, de, o, n);   // 0.21.7 page Kapitel (0.21.9: + CP rows)
    const char *t = nullptr;
    switch (q.kind) {
    case kQdCosPick: t = de ? "Kost\303\274m live wechseln, ohne die Unit neu zu laden" : "Switch the costume live, no unit reload";
        break;
    case kQdCosRec: t = de ? "Kost\303\274m f\303\274rs n\303\244chste Laden w\303\244hlen; l\303\244dt die Unit neu"
                           : "Choose the costume for the next load; reloads the unit"; break;
    case kQdCos:
        t = CosOffered(static_cast<WORD>(q.intro)) == 0
                ? (de ? "Vom Spiel abgelehnt (Pr\303\274fung 0x5c54e0, keine .drm?)" : "Refused by the game's check (no .drm?)")
                : (de ? "Dieses Kost\303\274m jetzt anziehen (live)" : "Wear this costume now (live)");
        break;
    default: return false;
    }
    Out(o, n, "%s", t);
    return true;
}
// ---- end of 0.21.7 help line ----
int QbSpecialBuild(int special, int base, bool de) {
    const int max = kQbViewMax - base;
    g_qbDynN = 0;
    if (max <= 0) return 0;
    int n = 0;
    if (special == kQsFav) n = QbFavRows(g_qbView + base, g_qbDyn, max, de);           // 0.21.1
    else if (special == kQsTests) n = QbTestsRows(g_qbView + base, g_qbDyn, max, de);
    else if (special == kQsSwitches) n = QbSwRows(g_qbView + base, g_qbDyn, max, de);   // 0.21.5
    else if (special == kQsCostume) n = QbCosRows(g_qbView + base, g_qbDyn, max, de);   // 0.21.6
    else if (special == kQsChapters) n = QbChapRows(g_qbView + base, g_qbDyn, max, de);   // 0.21.7
    if (special == kQsLara) n = QbFigRows(g_qbView + base, g_qbDyn, max, de);   // 0.22.16: positions + switch groups
    else if (special == kQsCheckpoints) n = QbCpPageRows(g_qbView + base, g_qbDyn, max, de);
    else if (special == kQsSaves) n = QbSavesRows(g_qbView + base, g_qbDyn, max, de);
    g_qbDynN = n;
    return n;
}
const QbRow *QbSpecialRow(int row) {         // 0.21.3: X / Y on page 0 act on the favourite / recent row itself
    if (row >= 0 && row < g_qbDynN && g_qbDyn[row].kind == kQdCosNext) return &kQbCosNext;   // 0.21.6
    if (row < 0 || row >= g_qbDynN || g_qbDyn[row].kind != kQdItem) return nullptr;
    const int k = static_cast<int>(g_qbDyn[row].intro);
    return k >= 0 && k < kQbViewMax ? &g_qbFavRow[k] : nullptr;
}
void QbSpecialAct(int special, int row, int dir) {
    (void)special;
    const bool de = g_qbLang == 0;
    if (row < 0 || row >= g_qbDynN) return;
    const QbDyn &q = g_qbDyn[row];
    char arg[96], key[160];
    switch (q.kind) {
    case kQdItem:                            // 0.21.1 page 0: the favourite / recent row as its bar row
        if (q.intro >= 0 && q.intro < kQbViewMax) QbActRow(0, g_qbFavRow[q.intro], dir);
        return;
    case kQdPrepare: {                       // 0.21.1 page Tests: the regression shortcut, right twice
        if (dir < 0) { QbResult(false, "%s", de ? "rechts 2x = vorbereiten" : "right 2x = prepare"); return; }
        Out(key, sizeof(key), "prepare %s", q.arg);
        if (!QbConfirm(key, q.arg, de ? "l\303\244dt / teleportiert (Story-Werte?)" : "loads / teleports (story values?)")) return;
        char o[300];
        const bool ok = RunRegressPrepare(q.arg, o, sizeof(o));
        SetLastAction("regress.prepare", ok, o);
        ++g_qbRuns;
        Log(1, "quick: Tests / Prepare %s: %s%s", q.arg, ok ? "" : "err ", o);
        QbResult(!ok, "Prepare %s: %s", q.arg, o);
        return;
    }
    case kQdStop: {
        char o[200];
        const bool ok = RunRegressPrepare("stop", o, sizeof(o));
        SetLastAction("regress.prepare", ok, o);
        QbResult(!ok, "%s", o);
        return;
    }
    case kQdTodo: {                          // 0.21.1 page Tests: TO TEST state as the ring's OK / Fail / Done / toggle
        const bool toggle = !strcmp(q.unit, "toggle"), step = !strcmp(q.unit, "step");
        const char *state = toggle ? (dir > 0 ? "on" : "off") : step ? (dir > 0 ? "done" : "open") : (dir > 0 ? "ok" : "fail");
        TestMarkFromMenu(q.arg, state);
        Log(1, "quick: Tests / TO TEST %s -> %s", q.arg, state);
        QbResult(false, "%s", g_lastAction);
        return;
    }
    case kQdSwGroup:                         // 0.21.5 page Fixes
    case kQdSw:
        QbSwAct(q, dir);
        return;
    case kQdFigGroup:                        // 0.22.16 page Figur (0.22.18: the planned row is a real switch now)
        QbFigAct(q, dir);
        return;
    case kQdCosPick:                         // 0.21.6 page Kostueme
    case kQdCosNext:
    case kQdCosRec:
    case kQdCosGroup:
    case kQdCos:
        QbCosAct(q, dir);
        return;
    case kQdChapGroup:                       // 0.21.7 page Kapitel (X = kQbXDir: a group toggles, a unit = right)
    case kQdChap:
    case kQdChapCp:                          // 0.21.9: a checkpoint of the open unit (cp.jump)
        QbChapAct(q, dir);
        return;
    case kQdPos:
        if (dir < 0) { QbResult(false, "%s", de ? "rechts = hin" : "right = go"); return; }
        if (q.loaded) { QbRun("Lara", "position", q.arg, "pos.go", q.arg); return; }
        Out(key, sizeof(key), "pos.goload %s", q.arg);
        {
            char lara[48], what[160];
            PosLaraUnit(lara, sizeof(lara));
            Out(what, sizeof(what), de ? "Unit %s nicht geladen (Lara in %s) - l\303\244dt sie (Story-Werte?)"
                                       : "unit %s not loaded (Lara in %s) - loads it (story values?)", q.unit, lara[0] ? lara : "-");
            if (!QbConfirm(key, q.arg, what)) return;
        }
        QbRun("Lara", "position", q.arg, "pos.goload", q.arg);
        return;
    case kQdCpActive:
        if (dir < 0) { QbResult(false, "%s", de ? "rechts 2x = hin" : "right 2x = go"); return; }
        if (!QbConfirm("dbg.cpgo active", de ? "Aktiver Checkpoint" : "Active checkpoint", nullptr)) return;
        QbRun("Checkpoints", "active", de ? "Aktiver Checkpoint" : "Active checkpoint", "dbg.cpgo", "active");
        return;
    case kQdCpAll:
        QbRun("Checkpoints", "all", de ? "Alle Marker" : "All markers", "dbg.cpall", dir > 0 ? "1" : "0");
        return;
    case kQdCp:
        Out(arg, sizeof(arg), "%ld", q.intro);
        if (dir < 0) {                       // left = marker on <-> off
            Out(arg, sizeof(arg), "%ld %d", q.intro, q.loaded ? 0 : 1);
            QbRun("Checkpoints", "marker", "CP", "dbg.cp", arg);
            return;
        }
        Out(key, sizeof(key), "dbg.cpgo %ld", q.intro);
        if (!QbConfirm(key, "CP", de ? "Fliegen an + hin" : "flight on + go")) return;
        QbRun("Checkpoints", "go", "CP", "dbg.cpgo", arg);
        return;
    case kQdBackupNow:
        if (dir < 0) return;
        QbRun("Saves", "backup", de ? "Sichern" : "Backup", "save.backup", "");
        return;
    case kQdRescan:
        if (dir < 0) return;
        SaveScan(true);
        QbResult(false, "%s", de ? "Liste neu gelesen" : "list re-read");
        return;
    case kQdSave:
        if (dir < 0) { QbResult(false, "%s", de ? "rechts 2x (10 s) = laden" : "right 2x (10 s) = load"); return; }
        QbRun("Saves", "load", q.arg, "save.load", q.arg);
        return;
    case kQdBackup:
        if (dir < 0) { QbResult(false, "%s", de ? "rechts 2x (10 s) = zur\303\274ckspielen" : "right 2x (10 s) = restore"); return; }
        QbRun("Saves", "restore", q.arg, "save.restore", q.arg);
        return;
    default:
        return;
    }
}

// menu (Debug view page, render thread): the checkpoint list and the positions
void PageCpPos() {
    char o[400];
    if (ImGui::TreeNodeEx("Checkpoints (0.17) / Checkpoint-Liste###cplist", ImGuiTreeNodeFlags_DefaultOpen)) {
        if (!g_dvCpOk) ImGui::TextWrapped("checkpoints off: %s", g_dvCpWhy);
        int total = 0;
        g_cpRowN = CpCollect(g_cpRows, kCpMax, true, &total);
        bool layer = g_dvOn[kDvCheckpoints] != 0;
        if (TmCheckbox("layer / Ebene  [dbg.checkpoints]###cplayer", &layer)) DvSet(kDvCheckpoints, layer, "menu", o, sizeof(o));
        ImGui::SameLine();
        if (TmButton("all on / alle an  [dbg.cpall 1]###cpallon")) RunDvCpAll("1", o, sizeof(o));
        ImGui::SameLine();
        if (TmButton("all off / alle aus  [dbg.cpall 0]###cpalloff")) RunDvCpAll("0", o, sizeof(o));
        ImGui::Text("%d checkpoint(s) in the loaded units, nearest first; %d hidden", total, CpHiddenCount());
        for (int i = 0; i < g_cpRowN; ++i) {
            const CpRow &r = g_cpRows[i];
            char text[128], id[48], arg[32];
            CpRowText(r, false, text, sizeof(text));
            bool show = !r.hidden;
            Out(id, sizeof(id), "%s###cpr%ld", text, r.intro);
            if (TmCheckbox(id, &show)) { Out(arg, sizeof(arg), "%ld %d", r.intro, show ? 1 : 0); RunDvCp(arg, o, sizeof(o)); }
            ImGui::SameLine();
            Out(id, sizeof(id), "go to / hin###cpg%ld", r.intro);
            if (TmButton(id)) { Out(arg, sizeof(arg), "%ld", r.intro); RunDvCpGo(arg, o, sizeof(o)); }
        }
        ImGui::TreePop();
    }
    if (ImGui::TreeNodeEx("Positions (0.17) / Positionen###poslist", ImGuiTreeNodeFlags_DefaultOpen)) {
        if (!g_posOk) ImGui::TextWrapped("positions off: %s", g_posWhy);
        static char name[40] = "";
        ImGui::InputText("name###posname", name, sizeof(name));
        ImGui::SameLine();
        if (TmButton("save here / hier merken  [pos.save]###possave")) RunPosSave(name, o, sizeof(o));
        static PosRow rows[kPosMax];
        static DWORD loaded = 0;
        static int count = 0;
        if (GetTickCount() - loaded > 1000) { count = PosLoad(rows, kPosMax); loaded = GetTickCount(); }   // the file, 1 / s
        float shift[3], origin[3];
        for (int i = count - 1; i >= 0; --i) {   // newest first
            const PosRow &r = rows[i];
            bool loadedUnit = PosUnitFrame(r.unit, shift, origin);
            char id[96];
            if (loadedUnit) {
                Out(id, sizeof(id), "go / hin###posg%d", i);
                if (TmButton(id)) InvokeCore("pos.go", r.name, false);
            } else {                             // 0.18: load the unit first (level.load), then flight + pos.go
                Out(id, sizeof(id), "load + go / laden + hin###posgl%d", i);
                if (TmButton(id)) InvokeCore("pos.goload", r.name, false);
            }
            ImGui::SameLine();
            ImGui::TextColored(loadedUnit ? ImVec4(0.6f, 1.0f, 0.6f, 1.0f) : ImVec4(0.7f, 0.7f, 0.7f, 1.0f), "%s  [%s%s]  %.0f %.0f "
                               "%.0f  %s", r.name, r.unit, loadedUnit ? "" : ", not loaded", r.p[0], r.p[1], r.p[2], r.saved);
        }
        ImGui::TreePop();
    }
}
void PosCheck() {
    DWORD at = 0;
    static char why[96];
    g_posOk = g_unitOk && g_playerOk && DvChecks(kPosChecks, sizeof(kPosChecks) / sizeof(kPosChecks[0]), &at);
    if (!g_unitOk) Out(why, sizeof(why), "stream unit table check (0.2) failed");
    else if (!g_playerOk) Out(why, sizeof(why), "player pointer check failed");
    else Out(why, sizeof(why), "unit frame code differs at 0x%08lx", at);
    g_posWhy = g_posOk ? "ok" : why;
    char path[MAX_PATH];
    PosPath(path, sizeof(path));
    Log(g_posOk ? 1 : 0, "0.17 checkpoint list: %d marker(s) hidden ([Debug] CheckpointHide); positions: %s, file %s",
        CpHiddenCount(), g_posWhy, path);
}

// dbg.depthdump (0.17, depth section above: DpDumpCall / DpTick)
void ValDpDump(char *o, size_t n) {
    if (g_dpDumpFrame >= 0) Out(o, n, "pending: frame %ld", static_cast<LONG>(g_dpDumpFrame));
    else Out(o, n, "idle (last dump: %d scene call(s))", g_dpDumpCount);
}
bool RunDpDump(const char *, char *o, size_t n) {
    if (!DvGate("dbg.depthdump", o, n)) return false;
    if (!g_dpMode) { Out(o, n, "switch dbg.depth on / dim first - the PCScene::Draw hook runs only then"); return false; }
    if (!DvAnyOn()) { Out(o, n, "switch a debug view layer on first - the PCScene::Draw hook runs only then"); return false; }
    if (g_dpDumpFrame >= 0) { Out(o, n, "a dump is pending (frame %ld)", static_cast<LONG>(g_dpDumpFrame)); return false; }
    g_dpDumpCount = 0;
    InterlockedExchange(&g_dpDumpFrame, g_dpFrame + 1);
    Log(1, "dbg.depthdump: frame %ld requested (DepthCall %d, src=%s)", static_cast<LONG>(g_dpDumpFrame), g_dpCall,
        ShotSource("dbg.depthdump"));
    Out(o, n, "dump of frame %ld requested - TruMenu.log '0.17 depthdump' lines", static_cast<LONG>(g_dpDumpFrame));
    return true;
}

// load (Start, after the 0.10.2 cinematic check): the byte checks of precheck_017.txt and the row table against kItems
void QuickCheck() {
    DWORD camAt = 0, cineAt = 0;
    g_ocCamOk = g_camLogOk && DvChecks(kOcCamChecks, sizeof(kOcCamChecks) / sizeof(kOcCamChecks[0]), &camAt);
    g_ocCineOk = g_cineOk && DvChecks(kOcCineChecks, sizeof(kOcCineChecks) / sizeof(kOcCineChecks[0]), &cineAt);
    char camText[64], cineText[64];
    if (g_ocCamOk) Out(camText, sizeof(camText), "ok");
    else if (!g_camLogOk) Out(camText, sizeof(camText), "failed (0.8 camera log check)");
    else Out(camText, sizeof(camText), "failed at 0x%08lx", camAt);
    if (g_ocCineOk) Out(cineText, sizeof(cineText), "ok");
    else if (!g_cineOk) Out(cineText, sizeof(cineText), "failed (0.10.2 check)");
    else Out(cineText, sizeof(cineText), "failed at 0x%08lx", cineAt);
    int rows = 0, unknown = 0;
    int planned = 0;
    for (const QbPage &p : kQbPages)
        for (int i = 0; i < p.n; ++i) {
            if (p.rows[i].kind == kQbLabel || p.rows[i].kind == kQbPlanned ||
                p.rows[i].kind == kQbGroup) {   // 0.18: no item (0.22.18: group headings too - were 29 "unknown")
                planned += p.rows[i].kind == kQbPlanned ? 1 : 0;
                continue;
            }
            ++rows;
            if (!FindItem(p.rows[i].id)) {
                ++unknown;
                Log(0, "0.17 quick toggles: row '%s' names the unknown item %s", p.rows[i].de, p.rows[i].id);
            }
        }
    char combo[48];
    QbComboText(g_qbButtons, combo, sizeof(combo));
    Log(g_ocCamOk && g_ocCineOk && !unknown ? 1 : 0, "0.17 quick toggles: [Quick] Enabled %d, OpenButtons 0x%04x (%s), "
        "ChordMs %d, ShowClosed %d, Language %s, Top %d%%, Scale %.2f; %d pages (0.18), %d item rows + %d planned, %d "
        "unknown item(s); cutscene shots: camera checks %s, cinematic test %s, [Shot] OnCine %ld (up to %d pairs per "
        "segment: %d every %d ms, then every %d ms; signal %s; segments %d)", g_qbEnabled, g_qbButtons, combo, g_qbChordMs,
        g_qbShowClosed, g_qbLang ? "en" : "de", g_qbTop, g_qbScale, kQbPageN, rows, planned, unknown, camText, cineText,
        static_cast<LONG>(g_ocOn), g_ocPairs, g_ocFastPairs, g_ocIntervalMs, g_ocSlowMs, OcSignalName(g_ocSignal),
        g_ocSegments);
}

